T07_GRAPH_EDGE_KEYS = {"e4_to_e1", "e4t_to_e1", "e4z_to_e1"}
CHAR_WORK_GATE_DISPLAY_ID = "T05"
CHAR_WORK_GATE_SESSION_IDS = {CHAR_WORK_GATE_DISPLAY_ID, "T06"}


def _format_gate_work_suggestion_text(value) -> str:
    text = campaign_ui_helpers._repair_polish_text(str(value or "").strip())
    if not text:
        return ""
    lines = []
    for line in text.splitlines():
        for idx, char in enumerate(line):
            if char.isspace():
                continue
            if char.isalpha():
                line = f"{line[:idx]}{char.upper()}{line[idx + 1:]}"
            break
        lines.append(line)
    return "\n".join(lines)


def _campaign_dataset_display_id(path_like, *, target_hint: str | None = None, counts: dict | None = None) -> str:
    raw = str(path_like or "").strip()
    if not raw:
        return ""
    try:
        return build_dataset_display_ref(raw, target_hint=target_hint, counts=counts).id
    except Exception:
        try:
            return Path(raw).parent.name if Path(raw).name.lower() == "data.yaml" else Path(raw).name
        except Exception:
            return raw


def _campaign_model_display_id(model_info, *, target_hint: str | None = None) -> str:
    try:
        return build_model_display_ref(model_info, target_hint=target_hint).id
    except Exception:
        if isinstance(model_info, dict):
            for key in ("run_id", "id", "best_weights", "model_path", "path"):
                raw = str(model_info.get(key, "") or "").strip()
                if raw:
                    try:
                        return Path(raw).stem if key not in {"run_id", "id"} else raw
                    except Exception:
                        return raw
        raw = str(model_info or "").strip()
        if not raw:
            return ""
        try:
            return Path(raw).stem
        except Exception:
            return raw


def _campaign_run_display_id(run_info, *, kind_hint: str | None = None) -> str:
    if isinstance(run_info, dict):
        for key in ("run_name", "name", "run_id", "id"):
            raw_direct = str(run_info.get(key, "") or "").strip()
            if re.match(r"^(TRN|Z2|Z3|DST|RUN)-", raw_direct, re.IGNORECASE):
                return raw_direct
    else:
        raw_direct = str(run_info or "").strip()
        if re.match(r"^(TRN|Z2|Z3|DST|RUN)-", raw_direct, re.IGNORECASE):
            return raw_direct
    try:
        return build_run_display_ref(run_info, kind_hint=kind_hint).id
    except Exception:
        if isinstance(run_info, dict):
            for key in ("run_name", "name", "run_id", "id", "run_dir", "path", "output_dir"):
                raw = str(run_info.get(key, "") or "").strip()
                if raw:
                    if re.match(r"^(TRN|Z2|Z3|DST|RUN)-", raw, re.IGNORECASE):
                        return raw
                    try:
                        return Path(raw).name
                    except Exception:
                        return raw
        raw = str(run_info or "").strip()
        if not raw:
            return ""
        if re.match(r"^(TRN|Z2|Z3|DST|RUN)-", raw, re.IGNORECASE):
            return raw
        try:
            return Path(raw).name
        except Exception:
            return raw


def _is_t07_graph_edge(edge_key: str | None) -> bool:
    return str(edge_key or "").strip() in T07_GRAPH_EDGE_KEYS


def _t07_graph_edge_for_path(path_key: str | None) -> str:
    normalized = normalize_iteration_path(path_key)
    if normalized == "plate_training":
        return "e4t_to_e1"
    if normalized in {"char_from_images", "char_from_ready_plates"}:
        return "e4z_to_e1"
    return ""


def _graph_edge_gate_display_id(edge_key: str | None) -> str:
    edge = CAMPAIGN_TRANSITION_GRAPH.get_edge(str(edge_key or "").strip())
    if edge is None:
        return ""
    specs = get_transition_specs_for_edge(getattr(edge, "key", ""))
    spec = specs[0] if specs else None
    gate_id = str(getattr(spec, "badge_id", "") or "").strip().upper()
    return campaign_visible_gate_id(gate_id) if gate_id else ""


def get_active_campaign_graph_gate_badge_label(self) -> str:
    """Return the currently selected graph gate for the main app badge."""

    try:
        if not (CAMPAIGN.get_active_project_name() or "").strip():
            return ""
    except Exception:
        return ""

    try:
        edge_key = str(getattr(self, "_campaign_graph_selected_edge_key", "") or "").strip()
    except Exception:
        edge_key = ""
    if not edge_key:
        try:
            edge_key = str(CAMPAIGN.get_graph_selected_edge_key() or "").strip()
        except Exception:
            edge_key = ""

    if edge_key in {"e1_to_e2_plate_training", "e1_to_e2_char_from_images"}:
        edge_key = "e1_to_e2"
    elif edge_key == "e4_to_e1":
        try:
            edge_key = _t07_graph_edge_for_path(CAMPAIGN.get_iteration_path()) or edge_key
        except Exception:
            pass

    display_id = _graph_edge_gate_display_id(edge_key)
    if display_id:
        return display_id

    try:
        current_step = int(CAMPAIGN.get_current_step() or 1)
    except Exception:
        current_step = 1
    try:
        selected_path = normalize_iteration_path(CAMPAIGN.get_iteration_path())
    except Exception:
        selected_path = ""

    candidates: list[str] = []
    for edge in CAMPAIGN_TRANSITION_GRAPH.edges:
        try:
            edge_key = str(getattr(edge, "key", "") or "").strip()
            if not edge_key:
                continue
            if campaign_stage_step(getattr(edge, "source", "")) != current_step:
                continue
            if _is_t07_graph_edge(edge_key):
                expected_t07_edge = _t07_graph_edge_for_path(selected_path)
                if expected_t07_edge and edge_key != expected_t07_edge:
                    continue
            specs = get_transition_specs_for_edge(edge_key)
            spec = specs[0] if specs else None
            path_key = normalize_iteration_path(getattr(spec, "path_key", "") if spec is not None else "")
            edge_paths = tuple(getattr(edge, "paths", ()) or ())
            if path_key and selected_path and path_key != selected_path:
                continue
            if not path_key and edge_paths and selected_path and selected_path not in edge_paths:
                continue
            candidates.append(edge_key)
        except Exception:
            continue

    if len(candidates) == 1:
        return _graph_edge_gate_display_id(candidates[0])
    return ""


def _format_char_dataset_resource_status(char_gate: dict | None) -> tuple[str, str, str, str]:
    """Return source/validation/tone/counter for the T06 character dataset gate."""

    gate = dict(char_gate or {})
    ok = bool(gate.get("ok"))
    reason = str(gate.get("reason") or "").strip().lower()
    message = str(gate.get("message") or gate.get("validation_message") or "").strip()
    ready_dataset = str(gate.get("ready_dataset") or gate.get("dataset_hint") or "").strip()
    try:
        char_count = int(gate.get("exportable_char_count", 0) or 0)
    except Exception:
        char_count = 0
    try:
        perfect_count = int(gate.get("perfect_count", 0) or 0)
    except Exception:
        perfect_count = 0
    counter = str(char_count) if ok and char_count > 0 else ""
    try:
        source_iteration = int(gate.get("source_iteration") or gate.get("pz3_iteration") or gate.get("iteration") or 0)
    except Exception:
        source_iteration = 0
    try:
        current_iteration = int(gate.get("current_iteration") or 0)
    except Exception:
        current_iteration = 0
    origin_text = ""
    if source_iteration > 0:
        if current_iteration > 0 and source_iteration == current_iteration:
            origin_text = f"IT{source_iteration} | bieżąca iteracja"
        elif current_iteration > 0 and source_iteration < current_iteration:
            origin_text = f"IT{source_iteration} | wcześniejsza iteracja"
        else:
            origin_text = f"IT{source_iteration}"

    if ok:
        source = _campaign_dataset_display_id(ready_dataset, target_hint="char") if ready_dataset else "Dataset znaków YOLO"
        if origin_text:
            source = f"{source} | {origin_text}"
        if reason == "source_dataset_ready_for_split":
            detail = (
                "Gotowe: praca „Przygotuj dataset znaków w Z3” utworzyła źródłowy dataset znaków YOLO Detect. "
                f"{CHAR_WORK_GATE_DISPLAY_ID} można zatwierdzić i przejść do przygotowania treningu znaków."
            )
        else:
            detail = (
                "Gotowe: istnieje dataset znaków YOLO Detect z obrazami i etykietami. "
                f"{CHAR_WORK_GATE_DISPLAY_ID} może prowadzić do E4Z, czyli treningu modelu znaków."
            )
        if char_count > 0:
            detail += f" Etykiety znaków: {char_count}."
        if perfect_count > 0:
            detail += f" Tablice perfect: {perfect_count}."
        if origin_text:
            detail += f" Pochodzenie gotowości: {origin_text}."
        return source, detail, "success", counter

    if reason == "missing_char_boxes":
        detail = (
            f"Brakuje etykiet znaków w datasecie. W modalu Praca {CHAR_WORK_GATE_DISPLAY_ID} wybierz "
            "„Przygotuj dataset znaków w Z3”, dokończ oznaczanie znaków i wyeksportuj dataset znaków."
        )
    elif reason == "missing_perfect_plates":
        detail = (
            f"Brakuje tablic ze statusem perfect. W modalu Praca {CHAR_WORK_GATE_DISPLAY_ID} wybierz "
            "„Przygotuj dataset znaków w Z3” i popraw tablice używane do znaków. "
            "Jeżeli brakuje samych ramek tablic, użyj „Uzupełnij anotacje tablic”."
        )
    elif reason == "invalid_char_dataset":
        detail = (
            f"Wskazany dataset nie jest właściwym datasetem znaków. W modalu Praca {CHAR_WORK_GATE_DISPLAY_ID} wybierz "
            "„Przygotuj dataset znaków w Z3” i utwórz dataset znaków YOLO Detect."
        )
    elif reason == "stale_char_dataset":
        detail = (
            message
            or f"Eksport datasetu znaków nie obejmuje najnowszej pracy {CHAR_WORK_GATE_DISPLAY_ID}. W modalu Praca {CHAR_WORK_GATE_DISPLAY_ID} wybierz "
            "„Przygotuj dataset znaków w Z3” i ponownie wykonaj eksport w PZ3."
        )
    else:
        detail = (
            f"Brakuje datasetu znaków wymaganego do otwarcia {CHAR_WORK_GATE_DISPLAY_ID}. W modalu Praca {CHAR_WORK_GATE_DISPLAY_ID} wybierz "
            "„Przygotuj dataset znaków w Z3”. Jeżeli najpierw trzeba dopisać lub poprawić anotacje tablic, "
            "wybierz „Uzupełnij anotacje tablic”."
        )
    return "Nie wskazano", detail, "warning", ""


def _show_project_loading_overlay(
    self,
    *,
    title: str = "Ładuję projekt",
    body: str = "",
    eyebrow: str = "ODTWARZANIE PROJEKTU",
    tone: str = "info",
    progress: float | None = None,
) -> None:
    progress_value = progress
    try:
        finalizing_progress = bool(progress_value is not None and float(progress_value) >= 99.5)
    except Exception:
        finalizing_progress = False
    determinate_progress = progress_value is not None
    overlay = getattr(self, "project_loading_overlay", None)
    card = getattr(self, "project_loading_card", None)
    accent_bar = getattr(self, "project_loading_accent_bar", None)
    content = getattr(self, "project_loading_content", None)
    eyebrow_lbl = getattr(self, "project_loading_eyebrow_lbl", None)
    title_lbl = getattr(self, "project_loading_title_lbl", None)
    body_lbl = getattr(self, "project_loading_body_lbl", None)
    step_lbl = getattr(self, "project_loading_step_lbl", None)
    progress_bar = getattr(self, "project_loading_progress", None)
    host = getattr(self, "main_container", None)
    if overlay is None or card is None or title_lbl is None or body_lbl is None or progress_bar is None or host is None:
        return

    palette = getattr(self.app, "palette", {})
    panel_bg = palette["panel"]
    fg = palette["fg"]
    tone_key = str(tone or "info").strip().lower()
    # Loading overlays should not change personality mid-flight.  A final
    # "success" state used to repaint the whole splash green, which looked like
    # a second, unrelated component. Keep loading visually steady.
    visual_tone_key = "info" if tone_key == "success" else tone_key
    if visual_tone_key == "error":
        accent = palette["error"]
    elif visual_tone_key == "warning":
        accent = palette["warning"]
    else:
        accent = palette["accent"]

    muted = palette["muted"]
    overlay_bg = blend_hex_colors(panel_bg, palette["blend_dark"], 0.18)
    card_bg = blend_hex_colors(panel_bg, accent, 0.045)
    border_color = blend_hex_colors(accent, palette["panel_border"], 0.28)

    try:
        try:
            host_w = int(host.winfo_width() or host.winfo_reqwidth() or 620)
            card_width = max(460, min(620, host_w - 112))
            body_length = len(str(body or "").strip())
            card_height = 190 if body_length > 110 else 176
            card.place_configure(relx=0.5, rely=0.16, anchor="n", width=card_width, height=card_height)
            body_lbl.configure(wraplength=max(320, card_width - 96))
        except Exception:
            pass
        overlay.configure(bg=overlay_bg, highlightbackground=overlay_bg, highlightcolor=overlay_bg)
        card.configure(bg=card_bg, highlightbackground=border_color, highlightcolor=border_color)
        if accent_bar is not None:
            accent_bar.configure(bg=accent)
        if content is not None:
            content.configure(bg=card_bg)
        if eyebrow_lbl is not None:
            eyebrow_lbl.configure(
                text=campaign_ui_helpers._repair_polish_text(str(eyebrow or "").strip() or "PRZYGOTOWANIE WIDOKU"),
                bg=card_bg,
                fg=blend_hex_colors(accent, fg, 0.12),
            )
        title_lbl.configure(
            text=campaign_ui_helpers._repair_polish_text(str(title or "").strip()),
            bg=card_bg,
            fg=blend_hex_colors(accent, fg, 0.06),
        )
        body_lbl.configure(text=campaign_ui_helpers._repair_polish_text(str(body or "").strip()), bg=card_bg, fg=fg)
        if step_lbl is not None:
            if progress_value is None:
                step_text = "Trwa przygotowanie widoku..."
            else:
                try:
                    visible_progress = max(0.0, min(99.0, float(progress_value)))
                    step_text = f"Postęp ładowania: {visible_progress:.0f}%"
                except Exception:
                    step_text = "Trwa przygotowanie widoku..."
            step_lbl.configure(text=campaign_ui_helpers._repair_polish_text(step_text), bg=card_bg, fg=muted)
            try:
                if progress_value is None:
                    if finalizing_progress:
                        step_text = "Finalizuję widok. Za chwilę pokażę gotowy panel..."
                    else:
                        step_text = "Przygotowuję widok. Dłuższe kroki mogą chwilę potrwać..."
                    step_lbl.configure(text=campaign_ui_helpers._repair_polish_text(step_text), bg=card_bg, fg=muted)
            except Exception:
                pass
        if hasattr(self.app, "ensure_adaptive_wrap"):
            self.app.ensure_adaptive_wrap(body_lbl, container=card, padding=44, min_wrap=240)
    except Exception:
        pass

    try:
        progress_bar.stop()
        if not determinate_progress:
            progress_bar.configure(mode="indeterminate", maximum=100.0, value=0.0)
            progress_bar.start(24)
        else:
            progress_bar.configure(
                mode="determinate",
                maximum=100.0,
                value=max(0.0, min(99.0, float(progress_value))),
            )
    except Exception:
        pass
    try:
        overlay.place(in_=host, relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
        overlay.lift()
    except Exception:
        pass
    self._project_loading_overlay_visible = True
    try:
        self.frame.update_idletasks()
    except Exception:
        pass


def _hide_project_loading_overlay(self) -> None:
    overlay = getattr(self, "project_loading_overlay", None)
    progress = getattr(self, "project_loading_progress", None)
    try:
        if progress is not None:
            progress.stop()
    except Exception:
        pass
    try:
        if overlay is not None:
            overlay.place_forget()
    except Exception:
        pass
    self._project_loading_overlay_visible = False


def _refresh_wizard_empty_state(self, *, projects_available: bool):
    try:
        self._set_pack_visibility(self.wizard_header_shell, True, fill=tk.X, pady=(0, 8))
        self._set_pack_visibility(self.wizard_header_title_lbl, False)
        self.wizard_header_title_lbl.config(text="")
        self.wizard_header_summary_lbl.config(text=campaign_ui_helpers._repair_polish_text("Utworz albo otwórz projekt w panelu Projekt."))
        self._set_pack_visibility(self.wizard_header_summary_lbl, True, anchor=tk.W, fill=tk.X, pady=(2, 0))
    except Exception:
        pass
    if not bool(getattr(self, "_project_exit_in_progress", False)):
        try:
            self._hide_project_loading_overlay()
        except Exception:
            pass
    self._set_pack_visibility(self.wizard_empty_state_card.get("shell"), False)
    self._set_pack_visibility(getattr(self, "wizard_transition_graph_shell", None), False)
    try:
        graph_host = getattr(self, "right_graph_host", None)
        if graph_host is not None:
            graph_host.grid_remove()
    except Exception:
        pass
    self._set_pack_visibility(self.wizard_stage_cards_host, False)
    self._refresh_wizard_stage_metro([])
    return


def _build_active_project_dashboard_state(self) -> dict:
    state_started = perf_counter()
    active_proj = str(CAMPAIGN.get_active_project_name() or "").strip()
    if not active_proj:
        return {}

    lightweight_open = bool(getattr(self, "_project_open_lightweight_refresh", False))
    curr_step = int(CAMPAIGN.get_current_step() or 1)
    step1_status = str(CAMPAIGN.get_step1_status() or "").strip().lower() or "pending"
    step2_status = str(CAMPAIGN.get_step2_status() or "").strip().lower() or "pending"
    step3_status = str(CAMPAIGN.get_step3_status() or "").strip().lower() or "pending"
    iteration_target = self._get_iteration_target()
    has_saved_step3_progress = self._has_saved_step3_progress()
    project_status = str(CAMPAIGN.get_project_status() or "active").strip().lower() or "active"
    project_paused_at = CAMPAIGN.get_project_paused_at()
    project_completed_at = CAMPAIGN.get_project_completed_at()

    step1_approved = step1_status == "approved"
    if (
        curr_step == 2
        and step1_approved
        and not iteration_target
        and step2_status == "pending"
        and step3_status == "pending"
    ):
        try:
            CAMPAIGN.reset_step1()
            CAMPAIGN.set_current_step(1)
            curr_step = 1
            step1_status = "pending"
            step1_approved = False
            logger.debug(
                "[CampaignTab] Naprawiono półstan nowej iteracji: E1 było zatwierdzone bez toru. "
                "Przywrócono E1 jako bieżący etap wyboru toru."
            )
        except Exception as e:
            logger.debug(f"Nie udało się naprawić półstanu E1 bez toru: {e}")

    try:
        selected_iteration_path = normalize_iteration_path(CAMPAIGN.get_iteration_path())
    except Exception:
        selected_iteration_path = ""
    step2_char_review_pending = bool(
        curr_step == 2
        and step1_approved
        and iteration_target == "char"
        and selected_iteration_path == "char_from_images"
        and step2_status == "generated"
        and step3_status == "pending"
    )
    if step2_char_review_pending:
        # T03 is an explicit gate decision. Old Z3 artifacts must not advance it
        # during project restore before the user confirms this gate.
        has_saved_step3_progress = False
        try:
            if not str(CAMPAIGN.get_graph_selected_edge_key() or "").strip():
                CAMPAIGN.set_graph_selected_edge_key("e2_to_e3")
        except Exception:
            pass
    if (
        selected_iteration_path == "char_from_ready_plates"
        and iteration_target == "char"
        and curr_step < 3
        and step1_approved
        and step3_status == "pending"
    ):
        try:
            char_ready_state = dict(self._get_step1_char_route_preflight_state() or {})
        except Exception:
            char_ready_state = {}
        if bool(char_ready_state.get("material_ready")):
            try:
                if step2_status != "approved":
                    CAMPAIGN.approve_step2()
                    step2_status = "approved"
                CAMPAIGN.set_current_step(3)
                curr_step = 3
                logger.debug(
                    "[CampaignTab] Naprawiono półstan T03: ścieżka E1->E3 miała current_step=2. "
                    "Gotowe tablice są dostępne, więc ustawiono E3 jako bieżący etap."
                )
            except Exception as e:
                logger.debug(f"Nie udało się przesunąć półstanu T03 do E3: {e}")
        else:
            try:
                CAMPAIGN.reset_step1()
                CAMPAIGN.set_current_step(1)
                curr_step = 1
                step1_status = "pending"
                step1_approved = False
                logger.debug(
                    "[CampaignTab] Naprawiono półstan T03: bramka była zatwierdzona bez wymaganego źródła AT. "
                    "Przywrócono E1, aby użytkownik mógł uzupełnić zasoby T03."
                )
            except Exception as e:
                logger.debug(f"Nie udało się cofnąć półstanu T03 do E1: {e}")

    if curr_step >= 2 and not step1_approved:
        try:
            CAMPAIGN.set_current_step(1)
        except Exception:
            pass
        curr_step = 1

    if (
        not lightweight_open
        and self._should_reset_stale_char_iteration_state(
            current_step=curr_step,
            step2_status=step2_status,
            step3_status=step3_status,
            iteration_target=iteration_target,
        )
    ):
        try:
            CAMPAIGN.reset_step3()
            CAMPAIGN.reset_step2()
            CAMPAIGN.set_current_step(2)
            CAMPAIGN.set_iteration_target("")
            logger.debug(
                "[CampaignTab] Wykryto przestarzały stan toru znaków dla nowej iteracji. "
                "Zresetowano E2/E3 do czystego wejścia iteracji."
            )
        except Exception as e:
            logger.debug(f"Nie udało się zresetować przestarzałego stanu toru znaków: {e}")
        curr_step = 2
        step2_status = "pending"
        step3_status = "pending"
        iteration_target = ""

    default_iteration_target = self._get_default_step2_iteration_target(
        current_step=curr_step,
        step1_status=step1_status,
        step2_status=step2_status,
        step3_status=step3_status,
        iteration_target=iteration_target,
    )
    if default_iteration_target in {"plate", "char"} and default_iteration_target != iteration_target:
        CAMPAIGN.set_iteration_target(default_iteration_target)
        iteration_target = default_iteration_target

    if (
        curr_step == 2
        and step1_approved
        and iteration_target == "char"
        and step2_status == "pending"
        and step3_status == "pending"
        and not lightweight_open
    ):
        try:
            ready_source = self._get_char_route_ready_source()
        except Exception:
            ready_source = {}
        if ready_source:
            logger.debug(
                "[CampaignTab] E2 ma gotowe źródło tablic dla toru znaków. "
                "Nie zatwierdzam automatycznie; decyzję obsługuje wyłącznie badge E2."
            )

    if (
        curr_step <= 2
        and step2_status == "pending"
        and step3_status == "pending"
        and not iteration_target
        and has_saved_step3_progress
    ):
        try:
            CAMPAIGN.reset_step3()
            has_saved_step3_progress = False
        except Exception as e:
            logger.debug(f"Nie udało się wyczyscic przestarzalego stanu Z3 przy starcie iteracji: {e}")

    active_step3_state = bool(curr_step >= 3 or step3_status != "pending")

    if not iteration_target and active_step3_state:
        CAMPAIGN.set_iteration_target("char")
        iteration_target = "char"

    if iteration_target == "char" and active_step3_state:
        if step2_status != "approved":
            try:
                CAMPAIGN.approve_step2()
                step2_status = "approved"
            except Exception as e:
                logger.debug(f"Nie udało się znormalizować E2 do approved dla aktywnego E3: {e}")

    if iteration_target == "plate" and curr_step >= 4:
        if step2_status != "approved":
            try:
                CAMPAIGN.approve_step2()
                step2_status = "approved"
            except Exception as e:
                logger.debug(f"Nie udało się znormalizować E2 do approved dla aktywnego E4T: {e}")

    if iteration_target == "char" and curr_step < 3 and step2_status == "approved" and has_saved_step3_progress:
        if step2_status != "approved":
            CAMPAIGN.approve_step2()
            step2_status = "approved"
        CAMPAIGN.set_current_step(3)
        curr_step = 3

    if iteration_target == "plate" and curr_step == 3 and step2_status == "approved":
        CAMPAIGN.set_current_step(4)
        curr_step = 4

    if (
        iteration_target == "char"
        and curr_step == 3
        and not lightweight_open
    ):
        try:
            readiness = self._detect_campaign_char_ready_dataset_state()
            ready_dataset_ok = bool(readiness.get("ok")) and bool(
                str(readiness.get("ready_dataset") or readiness.get("dataset_hint") or "").strip()
            )
            if step3_status in {"pending", "needs_rework"} and ready_dataset_ok:
                CAMPAIGN.set_step3_ready()
                step3_status = "ready"
            elif step3_status == "ready" and not ready_dataset_ok:
                CAMPAIGN.set_step3_pending()
                step3_status = "pending"
        except Exception as e:
            logger.debug(f"Nie udało się zaktualizować stanu gotowosci E3 z datasetu znaków: {e}")

    self._log_perf(
        "build_active_dashboard_state",
        state_started,
        threshold_ms=20.0,
        extra=f"step={curr_step}, target={iteration_target or '-'}",
    )
    return {
        "active_project": active_proj,
        "current_step": int(curr_step),
        "step1_status": step1_status,
        "step2_status": step2_status,
        "step3_status": step3_status,
        "iteration_target": iteration_target,
        "project_status": project_status,
        "project_paused_at": project_paused_at,
        "project_completed_at": project_completed_at,
    }


def _refresh_active_project_wizard_only(self) -> None:
    refresh_started = perf_counter()
    self._clear_dashboard_perf_cache()
    active_state = self._build_active_project_dashboard_state()
    active_project = str(active_state.get("active_project") or "").strip()
    if not active_project:
        self._refresh_dashboard()
        return

    try:
        self._ensure_wizard_stage_ui_ready()
    except Exception:
        pass

    palette = getattr(self.app, "palette", {})
    header_bg = palette["panel"]
    accent = palette["accent"]
    success = palette["success"]
    warning = palette["warning"]
    surface_info = palette["surface_info"]
    surface_success = palette["surface_success"]
    surface_warning = palette["surface_warning"]

    curr_step = int(active_state.get("current_step", 1) or 1)
    step1_status = str(active_state.get("step1_status", "pending") or "pending")
    step2_status = str(active_state.get("step2_status", "pending") or "pending")
    step3_status = str(active_state.get("step3_status", "pending") or "pending")
    iteration_target = str(active_state.get("iteration_target", "") or "").strip().lower()
    project_status = str(active_state.get("project_status", "active") or "active").strip().lower()
    project_paused_at = str(active_state.get("project_paused_at", "") or "").strip()
    project_completed_at = str(active_state.get("project_completed_at", "") or "").strip()
    project_paused = project_status == "paused"
    project_completed = project_status == "completed"
    iter_num = int(CAMPAIGN.get_current_iteration_num() or 1)

    project_title = self._format_project_iteration_title(active_project, iter_num)
    banner_bg = surface_success
    if project_completed:
        banner_bg = surface_warning
    elif project_paused:
        banner_bg = surface_info

    self._configure_campaign_banner(bg=banner_bg)
    self._set_icon_button_enabled("exit_project", True)
    self._refresh_wizard_active_dashboard(
        active_project=active_project,
        current_step=curr_step,
        iteration_target=iteration_target,
        project_status=project_status,
        project_paused_at=project_paused_at,
        project_completed_at=project_completed_at,
        step1_status=step1_status,
        step2_status=step2_status,
        step3_status=step3_status,
    )
    try:
        if bool(getattr(self, "_project_loading_overlay_visible", False)):
            self._show_project_loading_overlay(
                title="Ładuję projekt",
                body="Kończę odświeżanie i ustawiam docelowy widok projektu.",
                tone="info",
                progress=100.0,
            )
            self.frame.after(90, self._hide_project_loading_overlay)
        else:
            self._hide_project_loading_overlay()
    except Exception:
        pass
    self._update_main_tabs_highlight(curr_step=curr_step, has_project=True)
    self.app.update_campaign_tab_access()
    if not bool(getattr(self, "_project_open_lightweight_refresh", False)):
        try:
            self._stabilize_wizard_stage_badges()
        except Exception as e:
            logger.debug(f"Nie udało się natychmiast ustabilizować badge'y wizarda: {e}")
    self.frame.after_idle(self._sync_right_panel_scrollregion)
    self._schedule_pending_wizard_stage_focus()
    self._log_perf(
        "refresh_active_project_wizard_only",
        refresh_started,
        threshold_ms=20.0,
        extra=f"step={curr_step}, target={iteration_target or '-'}",
    )


def _cancel_deferred_project_open_tasks(self) -> None:
    for attr_name in (
        "_project_open_refresh_after_id",
        "_project_open_context_after_id",
        "_project_open_post_refresh_after_id",
        "_wizard_stage_badge_stabilize_after_id",
    ):
        pending = getattr(self, attr_name, None)
        if not pending:
            continue
        try:
            self.frame.after_cancel(pending)
        except Exception:
            pass
        setattr(self, attr_name, None)


def _get_lightweight_wizard_stage_statuses(
    self,
    *,
    active_project: str,
    current_step: int,
    iteration_target: str,
    project_status: str,
    project_paused_at: str,
    project_completed_at: str,
    step1_status: str,
    step2_status: str,
    step3_status: str,
) -> list[WizardStageStatus]:
    """Build startup-safe wizard statuses without touching heavy tab state.

    Opening a large project must not instantiate/refresh Z2, Z3 or Z4. The
    graph can validate deeply when the user opens a gate, but the first paint
    should use persisted campaign state and small artifact snapshots only.
    """

    status_started = perf_counter()
    try:
        current_step = max(1, min(4, int(current_step or CAMPAIGN.get_current_step() or 1)))
    except Exception:
        current_step = 1
    target = str(iteration_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
    step_status = {
        "step1": str(step1_status or CAMPAIGN.get_step1_status() or "pending").strip().lower(),
        "step2": str(step2_status or CAMPAIGN.get_step2_status() or "pending").strip().lower(),
        "step3": str(step3_status or CAMPAIGN.get_step3_status() or "pending").strip().lower(),
        "step4": str(CAMPAIGN.get_step4_status() or "pending").strip().lower(),
    }
    project_status_norm = str(project_status or "active").strip().lower()
    suspended = project_status_norm in {"completed", "paused"}

    try:
        iter_count = int(self._get_iteration_image_count() or 0)
    except Exception:
        iter_count = 0
    try:
        plan_summary = dict(CAMPAIGN.load_latest_ingest_plan_summary() or {})
    except Exception:
        plan_summary = {}
    try:
        summary_count = int(plan_summary.get("selected_total", 0) or 0)
    except Exception:
        summary_count = 0
    image_count = max(iter_count, summary_count)

    registry_package = {}
    try:
        current_iteration = int(CAMPAIGN.get_current_iteration_num() or 1)
        registry = CAMPAIGN.load_artifact_registry()
        packages = registry.get("packages", {}) if isinstance(registry, dict) else {}
        iteration_index = registry.get("iteration_index", {}) if isinstance(registry, dict) else {}
        package_id = str((iteration_index or {}).get(str(current_iteration), "") or "").strip()
        registry_package = packages.get(package_id) if isinstance(packages, dict) else {}
    except Exception:
        registry_package = {}

    route_hints = dict(registry_package.get("route_hints") or {}) if isinstance(registry_package, dict) else {}
    char_effective = dict(registry_package.get("char_effective_source") or {}) if isinstance(registry_package, dict) else {}
    plate_source = dict(registry_package.get("plate_source") or {}) if isinstance(registry_package, dict) else {}
    step2_active_run = dict(registry_package.get("step2_active_run") or {}) if isinstance(registry_package, dict) else {}
    try:
        plate_count = max(
            int(route_hints.get("total_plates", 0) or 0),
            int(char_effective.get("total_plates", 0) or 0),
            int(plate_source.get("total_plates", 0) or 0),
            int(step2_active_run.get("total_plates", 0) or 0),
        )
    except Exception:
        plate_count = 0
    try:
        min_plates = int(getattr(self, "STEP3_CHAR_MIN_PLATES", 10) or 10)
    except Exception:
        min_plates = 10

    def _base_state(step_num: int, status_key: str) -> str:
        saved = str(step_status.get(status_key, "") or "").strip().lower()
        if saved == "approved" or current_step > step_num:
            return "done"
        if suspended:
            return "locked"
        if current_step == step_num:
            return "in_progress"
        if current_step < step_num:
            return "locked"
        return "ready"

    step1_ready = bool(
        not suspended
        and current_step == 1
        and step_status["step1"] != "approved"
        and target in {"plate", "char"}
        and image_count > 0
    )
    step2_ready = bool(
        not suspended
        and current_step == 2
        and step_status["step1"] == "approved"
        and step_status["step2"] != "approved"
        and target in {"plate", "char"}
        and plate_count >= min_plates
    )
    step3_ready = bool(
        not suspended
        and current_step == 3
        and target == "char"
        and step_status["step3"] in {"ready", "approved"}
    )

    statuses = [
        WizardStageStatus(
            key="step1",
            title="E1. Wejście i tor iteracji",
            state=("done" if step_status["step1"] == "approved" else _base_state(1, "step1")),
            summary=(
                "Źródła wejściowe są zapisane w projekcie."
                if step_status["step1"] == "approved"
                else "Wybierz katalog zdjęć i ścieżkę pracy."
            ),
            details=(
                f"Zapisany licznik katalogu zdjęć: {image_count}."
                if image_count > 0
                else "Brak zapisanej liczby zdjęć w bieżącej iteracji."
            ),
            badge_action_label=("Zatwierdź etap" if step1_ready else ""),
            badge_action_command=(
                (lambda: campaign_graph_actions.execute_campaign_graph_action(self, "approve_step1"))
                if step1_ready
                else None
            ),
            body_mode=("step1_ingest" if current_step == 1 and step_status["step1"] != "approved" else ""),
            body_visible=bool(current_step == 1 and step_status["step1"] != "approved"),
            is_current=bool(current_step == 1 and not suspended),
        ),
        WizardStageStatus(
            key="step2",
            title="E2. Tablice",
            state=("done" if step_status["step2"] == "approved" or current_step > 2 else _base_state(2, "step2")),
            summary=(
                "Tablice są zatwierdzone dla dalszej pracy."
                if step_status["step2"] == "approved" or current_step > 2
                else "Praca nad tablicami jest bieżącą bramką."
                if current_step == 2
                else "E2 odblokuje się po zamknięciu E1."
            ),
            details=(
                f"Lekki rejestr projektu widzi {plate_count} tablic."
                if plate_count > 0
                else "Szczegóły tablic zostaną sprawdzone po wejściu w bramkę lub Z2."
            ),
            primary_label=("Otwórz Z2" if current_step == 2 and step_status["step1"] == "approved" else ""),
            primary_command=(
                (lambda: campaign_graph_actions.execute_campaign_graph_action(self, "open_z2_campaign_context"))
                if current_step == 2 and step_status["step1"] == "approved"
                else None
            ),
            badge_action_label=("Zatwierdź etap" if step2_ready else ""),
            badge_action_command=(
                (lambda: campaign_graph_actions.execute_campaign_graph_action(self, "approve_step2"))
                if step2_ready
                else None
            ),
            is_current=bool(current_step == 2 and not suspended),
        ),
        WizardStageStatus(
            key="step3",
            title="E3. Znaki",
            state=("done" if step_status["step3"] == "approved" or current_step > 3 else _base_state(3, "step3")),
            summary=(
                "Znaki są zatwierdzone dla treningu."
                if step_status["step3"] == "approved" or current_step > 3
                else "Bieżąca bramka prowadzi do przygotowania datasetu znaków."
                if current_step == 3 and target == "char"
                else "E3 dotyczy toru znaków."
            ),
            details=f"Pełna gotowość datasetu znaków jest sprawdzana dopiero w bramce {CHAR_WORK_GATE_DISPLAY_ID} lub w Z3.",
            primary_label=("Przygotuj dataset znaków w Z3" if current_step == 3 and target == "char" else ""),
            primary_command=(
                (lambda: campaign_graph_actions.execute_campaign_graph_action(self, "continue_z3"))
                if current_step == 3 and target == "char"
                else None
            ),
            badge_action_label=("Zatwierdź etap" if step3_ready else ""),
            badge_action_command=(
                (lambda: campaign_graph_actions.execute_campaign_graph_action(self, "approve_step3"))
                if step3_ready
                else None
            ),
            is_current=bool(current_step == 3 and target == "char" and not suspended),
        ),
        WizardStageStatus(
            key="step4",
            title=(
                "E4T. Trening modelu tablic"
                if target == "plate"
                else "E4Z. Trening modelu znaków"
                if target == "char"
                else "E4T/E4Z. Trening"
            ),
            state=_base_state(4, "step4"),
            summary=(
                "Budowa datasetu i trening modelu tablic są bieżącą bramką."
                if current_step == 4 and target == "plate"
                else "Budowa datasetu i trening modelu znaków są bieżącą bramką."
                if current_step == 4 and target == "char"
                else "Budowa datasetu i trening są bieżącą bramką."
                if current_step == 4
                else "Właściwy węzeł treningu odblokuje się po zamknięciu wcześniejszej bramki."
            ),
            details=f"Szczegóły wariantu datasetu i wyniku treningu są walidowane po wejściu w {CHAR_WORK_GATE_DISPLAY_ID} lub Z4.",
            primary_label=("Otwórz Z4" if current_step == 4 else ""),
            primary_command=(
                (lambda: campaign_graph_actions.execute_campaign_graph_action(self, "open_z4"))
                if current_step == 4
                else None
            ),
            badge_action_label=("Zakończ etap bez treningu" if current_step == 4 and not suspended else ""),
            badge_action_command=(
                (lambda: campaign_graph_actions.execute_campaign_graph_action(self, "approve_step4_without_training"))
                if current_step == 4 and not suspended
                else None
            ),
            is_current=bool(current_step == 4 and not suspended),
        ),
    ]
    try:
        self._log_perf(
            "lightweight_wizard_stage_statuses",
            status_started,
            threshold_ms=20.0,
            extra=f"step={current_step}, target={target or '-'}, images={image_count}, plates={plate_count}",
        )
    except Exception:
        pass
    return statuses


def _refresh_wizard_active_dashboard(
    self,
    *,
    active_project: str,
    current_step: int,
    iteration_target: str,
    project_status: str,
    project_paused_at: str,
    project_completed_at: str,
    step1_status: str,
    step2_status: str,
    step3_status: str,
):
    empty_card = getattr(self, "wizard_empty_state_card", {}) or {}
    if isinstance(empty_card, dict):
        self._set_pack_visibility(empty_card.get("shell"), False)
    self._set_pack_visibility(getattr(self, "wizard_stage_cards_host", None), False)

    iter_num = int(CAMPAIGN.get_current_iteration_num() or 1)
    project_status_norm = str(project_status or "active").strip().lower()
    project_completed = project_status_norm == "completed"
    project_paused = project_status_norm == "paused"
    project_suspended = bool(project_completed or project_paused)

    try:
        self._set_pack_visibility(self.wizard_header_shell, False)
        self._set_pack_visibility(self.wizard_header_title_lbl, False)
        self._set_pack_visibility(self.wizard_header_summary_lbl, False)
        self.wizard_header_title_lbl.config(text="")
        self.wizard_header_summary_lbl.config(text="")
    except Exception:
        pass

    statuses = self._get_wizard_stage_statuses(
        active_project=active_project,
        current_step=current_step,
        iteration_target=iteration_target,
        project_status=project_status_norm,
        project_paused_at=project_paused_at,
        project_completed_at=project_completed_at,
        step1_status=step1_status,
        step2_status=step2_status,
        step3_status=step3_status,
    )
    try:
        self._campaign_graph_stage_statuses_snapshot = list(statuses or [])
    except Exception:
        self._campaign_graph_stage_statuses_snapshot = []
    self._show_wizard_transition_graph()
    if not bool(getattr(self, "_project_open_lightweight_refresh", False)):
        try:
            campaign_ui_helpers._repair_polish_widget_texts(getattr(self, "right_content", None))
        except Exception:
            pass


def _choose_step1_iteration_target(self, target: str):
    switch_started = perf_counter()
    target = self._normalize_iteration_target(target)
    if target not in {"plate", "char"}:
        return

    previous_target = self._normalize_iteration_target(CAMPAIGN.get_iteration_target())
    if previous_target == target:
        try:
            self._wizard_step2_target_var.set(target)
        except Exception:
            pass
        return

    if previous_target in {"plate", "char"} and previous_target != target:
        lock_reason = self._get_iteration_target_lock_reason()
        if lock_reason:
            try:
                self.app.update_status(lock_reason, "info")
            except Exception:
                pass
            return

    plate_model_ready = False
    if target == "char":
        try:
            plate_source_state = self._get_annotation_step2_source_state("plate")
        except Exception:
            plate_source_state = {}
        plate_model_ready = bool(plate_source_state.get("plate_model_ready"))

    last_target = self._get_last_iteration_target()
    route_changed = previous_target in {"plate", "char"} and previous_target != target
    continuing_previous_iteration_route = bool(last_target and last_target == target and not route_changed)
    lightweight_route_reset = bool(
        route_changed
        and int(CAMPAIGN.get_current_step() or 0) <= 2
        and str(CAMPAIGN.get_step2_status() or "").strip().lower() in {"", "pending"}
        and str(CAMPAIGN.get_step3_status() or "").strip().lower() in {"", "pending"}
        and not str(CAMPAIGN.get_step2_staging_run() or "").strip()
    )

    CAMPAIGN.set_iteration_target(target)
    try:
        if str(CAMPAIGN.get_step1_status() or "").strip().lower() != "approved":
            CAMPAIGN.set_current_step(1)
    except Exception:
        pass
    try:
        self._wizard_step2_target_var.set(target)
    except Exception:
        pass

    pending_after = getattr(self, "_iteration_target_change_after_id", None)
    if pending_after is not None:
        try:
            self.frame.after_cancel(pending_after)
        except Exception:
            pass
        self._iteration_target_change_after_id = None

    def _finish_target_switch():
        finish_started = perf_counter()
        self._iteration_target_change_after_id = None
        if route_changed:
            cleanup_started = perf_counter()
            try:
                annotation_tab = getattr(self.app, "tabs", {}).get("annotation")
                if annotation_tab is not None:
                    annotation_tab.reset_campaign_iteration_route_state(
                        new_target=target,
                        remove_persisted_runs=not lightweight_route_reset,
                    )
            except Exception as e:
                logger.debug(f"Nie udało się wyczyscic stanu Z2 po zmianie toru iteracji: {e}")

            if str(CAMPAIGN.get_step1_status() or "").strip().lower() != "approved":
                CAMPAIGN.set_current_step(1)
            elif int(CAMPAIGN.get_current_step() or 0) >= 2:
                CAMPAIGN.set_current_step(2)
            CAMPAIGN.reset_step2()
            CAMPAIGN.reset_step3()
            self._log_perf(
                "iteration_target_cleanup",
                cleanup_started,
                threshold_ms=20.0,
                extra=(
                    f"from={previous_target or '-'} to={target} "
                    f"lightweight={1 if lightweight_route_reset else 0}"
                ),
            )

        self._refresh_active_project_wizard_only()
        self.app.update_campaign_tab_access()
        jump_label = self._get_step2_jump_button_text(target)
        try:
            step1_pending = str(CAMPAIGN.get_step1_status() or "").strip().lower() != "approved"
            if target == "plate":
                if step1_pending:
                    status_text = "Wybrano tor tablic w E1. Zatwierdź E1, aby odblokować E2/Z2."
                elif continuing_previous_iteration_route:
                    status_text = f"Wybrano tor tablic. Kontynuujesz tor z poprzedniej iteracji; użyj przycisku '{jump_label}', gdy chcesz przejść dalej."
                elif not route_changed:
                    status_text = f"Wybrano tor tablic. Użyj przycisku '{jump_label}', gdy chcesz przejść dalej."
                else:
                    status_text = f"Wybrano tor tablic. Poprzedni stan Z2 tej iteracji został zresetowany; przejdź dalej przyciskiem '{jump_label}'."
                self.app.update_status(status_text, "info")
            else:
                if step1_pending:
                    status_text = "Wybrano tor znaków w E1. Zatwierdź E1, aby odblokować E2 jako etap przygotowania tablic."
                elif continuing_previous_iteration_route:
                    status_text = f"Wybrano tor znaków. Kontynuujesz tor z poprzedniej iteracji; użyj przycisku '{jump_label}', gdy chcesz przejść dalej."
                elif not route_changed:
                    status_text = (
                        f"Wybrano tor znaków. Model tablic projektu jest już dostępny i nie trzeba go dodawać ponownie w E1; użyj przycisku '{jump_label}', aby przygotować tablice."
                        if plate_model_ready and not self._get_char_route_ready_source()
                        else f"Wybrano tor znaków. Użyj przycisku '{jump_label}', gdy chcesz przejść dalej."
                    )
                else:
                    status_text = f"Wybrano tor znaków. Poprzedni stan Z2 tej iteracji został zresetowany; przejdź dalej przyciskiem '{jump_label}'."
                self.app.update_status(status_text, "info")
        except Exception:
            pass
        self._log_perf(
            "iteration_target_switch",
            finish_started,
            threshold_ms=20.0,
            extra=f"route_changed={route_changed}, target={target}",
        )
        self._log_perf(
            "iteration_target_switch_total",
            switch_started,
            threshold_ms=20.0,
            extra=f"from={previous_target or '-'} to={target}",
        )

    try:
        self._iteration_target_change_after_id = self.frame.after_idle(_finish_target_switch)
    except Exception:
        _finish_target_switch()


def _render_step1_route_actions(self, frame, *, allow_pending_actions: bool = True):
    """Render the new campaign transition graph.

    Stages are abstract nodes. Every edge owns a gate badge with three fields:
    resources, actions and approval. Solid edges represent the standard cycle,
    dashed edges represent conditional jumps.
    """
    if frame is None:
        return

    palette = getattr(self.app, "palette", {})
    card_bg = str(frame.cget("bg") or palette["panel"])
    fg = palette["fg"]
    muted = palette["muted"]
    muted_dim = palette["muted_dim"]
    success = palette["success"]
    warning = palette["warning"]
    error = palette["error"]
    accent = palette["accent"]
    graph_canvas_bg = palette["campaign_graph_bg"]
    edge_route_color = palette["campaign_edge"]
    active_edge_color = palette["campaign_active_edge"]
    border = palette["panel_border"]
    field_bg = palette["field"]

    for widget in frame.winfo_children():
        widget.destroy()
    frame.configure(bg=card_bg)
    try:
        pending_blink = getattr(self, "_campaign_graph_approve_blink_after_id", None)
        if pending_blink:
            self.frame.after_cancel(pending_blink)
    except Exception:
        pass
    self._campaign_graph_approve_blink_after_id = None
    self._campaign_graph_approve_blink_phase = False
    self._campaign_graph_approve_blink_started_at = 0.0
    approve_blink_seen = getattr(self, "_campaign_graph_approve_blink_seen_keys", None)
    if not isinstance(approve_blink_seen, set):
        approve_blink_seen = set()
        self._campaign_graph_approve_blink_seen_keys = approve_blink_seen
    attention_seen = getattr(self, "_campaign_graph_attention_seen_keys", None)
    if not isinstance(attention_seen, set):
        attention_seen = set()
        self._campaign_graph_attention_seen_keys = attention_seen
    attention_state = getattr(self, "_campaign_graph_attention_state", None)
    if not isinstance(attention_state, dict):
        attention_state = {"after_id": None, "defer_after_id": None, "token": 0, "running_key": ""}
        self._campaign_graph_attention_state = attention_state
    attention_state.setdefault("after_id", None)
    attention_state.setdefault("defer_after_id", None)
    attention_state.setdefault("running_key", "")

    try:
        current_step = max(1, min(4, int(CAMPAIGN.get_current_step() or 1)))
    except Exception:
        current_step = 1
    try:
        current_iteration = max(1, int(CAMPAIGN.get_current_iteration_num() or 1))
    except Exception:
        current_iteration = 1
    try:
        active_project_name = str(CAMPAIGN.get_active_project_name() or "").strip()
    except Exception:
        active_project_name = ""

    if active_project_name and current_step == 1 and bool(getattr(self, "_campaign_graph_allow_e1_resource_sync", False)):
        try:
            master_pool_token = str(CAMPAIGN.get_master_pool_dir() or "")
        except Exception:
            master_pool_token = ""
        try:
            iteration_image_count = int(CAMPAIGN.get_iteration_image_count() or 0)
        except Exception:
            iteration_image_count = 0
        try:
            plan = getattr(self, "current_ingest_plan", None)
            plan_count = int((plan or {}).get("selected_total", 0) or 0) if isinstance(plan, dict) else 0
        except Exception:
            plan_count = 0
        resource_sync_signature = (
            active_project_name,
            int(current_iteration or 1),
            master_pool_token,
            iteration_image_count,
            plan_count > 0,
        )
        if getattr(self, "_campaign_graph_e1_resource_sync_signature", None) != resource_sync_signature:
            self._campaign_graph_e1_resource_sync_signature = resource_sync_signature
            ensure_plan = getattr(self, "_ensure_current_ingest_plan_from_master_pool", None)
            if callable(ensure_plan):
                try:
                    ensure_plan()
                except Exception as e:
                    logger.debug(f"Nie udało się odtworzyć zasobów E1 przed renderem grafu: {e}")

    try:
        char_state = dict(self._get_step1_char_route_preflight_state() or {})
    except Exception:
        char_state = {}
    image_count = int(char_state.get("image_count", 0) or 0)
    min_images = int(char_state.get("min_images", getattr(self, "STEP1_CHAR_MIN_IMAGES", 10)) or 10)
    plate_count = int(char_state.get("plate_material_count", 0) or 0)
    min_plates = int(char_state.get("min_plates", getattr(self, "STEP3_CHAR_MIN_PLATES", 10)) or 10)
    material_ready = bool(char_state.get("material_ready"))
    image_potential = bool(char_state.get("image_potential"))
    try:
        current_target = self._get_iteration_target()
    except Exception:
        current_target = ""
    try:
        explicit_getter = getattr(CAMPAIGN, "get_explicit_iteration_path", None)
        if callable(explicit_getter):
            explicit_selected_path = normalize_iteration_path(explicit_getter())
        else:
            explicit_selected_path = normalize_iteration_path(CAMPAIGN.get_iteration_path())
    except Exception:
        explicit_selected_path = ""
    if explicit_selected_path and iteration_path_target(explicit_selected_path) != current_target:
        explicit_selected_path = ""
    selected_path = explicit_selected_path
    try:
        step1_status_for_selection = str(CAMPAIGN.get_step1_status() or "").strip().lower()
    except Exception:
        step1_status_for_selection = ""
    infer_path_from_target = bool(
        int(current_step or 1) > 1
        or step1_status_for_selection == "approved"
    )
    if not selected_path and infer_path_from_target and current_target in {"plate", "char"}:
        selected_path = (
            "char_from_ready_plates"
            if current_target == "char" and material_ready
            else default_iteration_path_for_target(current_target)
        )
    try:
        t02_review_committed_current_iteration = bool(CAMPAIGN.is_t02_at_review_committed_current_iteration())
    except Exception:
        t02_review_committed_current_iteration = False
    try:
        t01_entry_committed_current_iteration = bool(CAMPAIGN.is_t01_entry_committed_current_iteration())
    except Exception:
        t01_entry_committed_current_iteration = False

    def _current_t07_graph_edge_key() -> str:
        normalized_path = normalize_iteration_path(selected_path)
        if normalized_path:
            return _t07_graph_edge_for_path(normalized_path)
        target = str(current_target or "").strip().lower()
        if not target:
            try:
                target = str(CAMPAIGN.get_iteration_target() or "").strip().lower()
            except Exception:
                target = ""
        if not target:
            try:
                target = str(CAMPAIGN.get_last_iteration_target() or "").strip().lower()
            except Exception:
                target = ""
        if target == "plate":
            return "e4t_to_e1"
        if target == "char":
            return "e4z_to_e1"
        return "e4z_to_e1"

    def _t07_edge_visible(edge_key: str | None) -> bool:
        normalized = str(edge_key or "").strip()
        if not _is_t07_graph_edge(normalized):
            return True
        return normalized == _current_t07_graph_edge_key()

    def _active_master_pool_image_snapshot() -> CampaignResourceSnapshot | None:
        try:
            image_source = dict(self._get_project_start_effective_images_source() or {})
        except Exception:
            image_source = {}
        effective_dir = image_source.get("effective_dir")
        effective_count = 0
        for count_key in ("effective_count", "iteration_count", "master_count"):
            try:
                effective_count = max(effective_count, int(image_source.get(count_key, 0) or 0))
            except Exception:
                continue
        if effective_dir is None:
            for dir_key in ("iteration_dir", "master_dir"):
                candidate = image_source.get(dir_key)
                if candidate is not None:
                    effective_dir = candidate
                    break
        try:
            effective_path = Path(effective_dir) if effective_dir is not None else None
        except Exception:
            effective_path = None
        try:
            effective_exists = bool(effective_path is not None and effective_path.exists() and effective_path.is_dir())
        except Exception:
            effective_exists = False
        if effective_count <= 0 and effective_path is not None:
            try:
                effective_count = int(CAMPAIGN.get_iteration_image_count(current_iteration, active_project_name or None) or 0)
            except Exception:
                effective_count = 0
        if effective_count <= 0 and effective_exists:
            try:
                effective_count = int(CAMPAIGN.count_images_in_dir(effective_path, recursive=True) or 0)
            except Exception:
                try:
                    effective_count = int(self._count_images_in_dir(effective_path, recursive=True) or 0)
                except Exception:
                    effective_count = 0
        if effective_path is None and effective_count <= 0:
            return None
        try:
            source_text = self._format_project_start_asset_source(effective_path) if effective_path is not None else "Nie wskazano"
        except Exception:
            source_text = str(effective_path or "Nie wskazano")
        try:
            min_images_value = int(min_images or getattr(self, "STEP1_CHAR_MIN_IMAGES", 10) or 10)
        except Exception:
            min_images_value = 10
        if effective_count > 0:
            if selected_path == "char_from_images":
                validation_text = f"Warunek T01 | OK | {effective_count}/{min_images_value} obrazów do przygotowania tablic."
            elif selected_path == "plate_training":
                validation_text = f"Warunek T01 | OK | {effective_count} obrazów dla anotacji tablic."
            else:
                validation_text = f"Wybrano katalog obrazów: {effective_count} pozycji."
            tone = "success"
        elif effective_exists:
            validation_text = "Wskazany katalog nie zawiera obrazów."
            tone = "error"
        else:
            validation_text = "Nie wskazano katalogu obrazów."
            tone = "warning"
        return CampaignResourceSnapshot(
            key="images",
            canonical_key="images",
            code="O",
            label=campaign_resource_label("images", "O - obrazy"),
            requirement="required",
            source=source_text,
            validation=validation_text,
            tone=tone,
            counter_text=str(effective_count) if effective_count > 0 else "",
            meta={
                "contract_kind": "O",
                "contract_ready": bool(tone == "success" and effective_count > 0 and effective_exists),
                "image_count": int(effective_count or 0),
                "image_dir": str(effective_path or ""),
                "iteration_path": selected_path,
            },
        )

    stage_status = {}
    for step_num, getter_name in (
        (1, "get_step1_status"),
        (2, "get_step2_status"),
        (3, "get_step3_status"),
        (4, "get_step4_status"),
    ):
        try:
            getter = getattr(CAMPAIGN, getter_name)
            stage_status[f"E{step_num}"] = str(getter() or "").strip().lower()
        except Exception:
            stage_status[f"E{step_num}"] = ""

    def _selection_stage_num(stage_key: str) -> int:
        return campaign_stage_step(stage_key)

    def _selection_edge_spec(edge):
        specs = get_transition_specs_for_edge(getattr(edge, "key", ""))
        return specs[0] if specs else None

    def _selection_edge_visible(edge) -> bool:
        spec = _selection_edge_spec(edge)
        if not _t07_edge_visible(getattr(edge, "key", "")):
            return False
        if current_step != _selection_stage_num(getattr(edge, "source", "")):
            return False
        if (
            int(current_step or 0) == 1
            and str(getattr(edge, "source", "") or "").strip().upper() == "E1"
            and step1_status_for_selection != "approved"
        ):
            return True
        path_key = str(getattr(spec, "path_key", "") or "").strip() if spec is not None else ""
        if path_key and selected_path and path_key != selected_path:
            return False
        edge_paths = tuple(getattr(edge, "paths", ()) or ())
        if not path_key and edge_paths and selected_path and selected_path not in edge_paths:
            return False
        return True

    active_gate_keys = [
        str(getattr(edge, "key", "") or "").strip()
        for edge in CAMPAIGN_TRANSITION_GRAPH.edges
        if _selection_edge_visible(edge)
    ]
    attention_scope = (
        str(active_project_name or ""),
        int(current_iteration or 1),
        int(current_step or 1),
        str(selected_path or ""),
        tuple(active_gate_keys),
    )
    if getattr(self, "_campaign_graph_attention_scope", None) != attention_scope:
        self._campaign_graph_attention_scope = attention_scope
        try:
            attention_seen.clear()
        except Exception:
            attention_seen = set()
            self._campaign_graph_attention_seen_keys = attention_seen
        try:
            for pending_key in ("after_id", "defer_after_id"):
                pending_after = attention_state.get(pending_key)
                if pending_after:
                    self.frame.after_cancel(pending_after)
                attention_state[pending_key] = None
            attention_state["running_key"] = ""
            attention_state["token"] = int(attention_state.get("token", 0) or 0) + 1
        except Exception:
            attention_state["after_id"] = None
            attention_state["defer_after_id"] = None
            attention_state["running_key"] = ""

    selected_edge_key = str(getattr(self, "_campaign_graph_selected_edge_key", "") or "").strip()
    if not selected_edge_key:
        try:
            selected_edge_key = str(CAMPAIGN.get_graph_selected_edge_key() or "").strip()
        except Exception:
            selected_edge_key = ""
    if selected_edge_key in {"e1_to_e2_plate_training", "e1_to_e2_char_from_images"}:
        selected_edge_key = "e1_to_e2"
        try:
            self._campaign_graph_selected_edge_key = selected_edge_key
        except Exception:
            pass
    if selected_edge_key == "e4_to_e1":
        selected_edge_key = _t07_graph_edge_for_path(selected_path)
    if _is_t07_graph_edge(selected_edge_key) and not _t07_edge_visible(selected_edge_key):
        selected_edge_key = _current_t07_graph_edge_key()
    if selected_edge_key:
        selected_edge_for_state = CAMPAIGN_TRANSITION_GRAPH.get_edge(selected_edge_key)
        selected_spec_for_state = _selection_edge_spec(selected_edge_for_state) if selected_edge_for_state is not None else None
        selected_spec_path = str(getattr(selected_spec_for_state, "path_key", "") or "").strip()
        selected_edge_paths = tuple(getattr(selected_edge_for_state, "paths", ()) or ()) if selected_edge_for_state is not None else ()
        if selected_spec_path and selected_spec_path != explicit_selected_path:
            selected_edge_key = ""
        elif selected_edge_paths and explicit_selected_path and explicit_selected_path not in selected_edge_paths:
            selected_edge_key = ""
    if selected_edge_key not in active_gate_keys:
        selected_edge_key = ""
        try:
            if hasattr(CAMPAIGN, "clear_graph_selected_edge_key"):
                CAMPAIGN.clear_graph_selected_edge_key()
        except Exception:
            pass
    if not selected_edge_key:
        if len(active_gate_keys) == 1:
            selected_edge_key = active_gate_keys[0]
        elif selected_path:
            for edge in CAMPAIGN_TRANSITION_GRAPH.edges:
                spec = _selection_edge_spec(edge)
                path_key = str(getattr(spec, "path_key", "") or "").strip() if spec is not None else ""
                edge_key = str(getattr(edge, "key", "") or "").strip()
                if edge_key in active_gate_keys and path_key and path_key == selected_path:
                    selected_edge_key = edge_key
                    break
    try:
        self._campaign_graph_selected_edge_key = selected_edge_key
    except Exception:
        pass
    try:
        refresh_menu_badge = getattr(self.app, "_refresh_menu_badge", None)
        if callable(refresh_menu_badge):
            refresh_menu_badge()
    except Exception:
        pass

    canvas = tk.Canvas(
        frame,
        height=700,
        bg=graph_canvas_bg,
        bd=0,
        highlightthickness=0,
        highlightbackground=border,
        highlightcolor=border,
    )
    graph_view = getattr(self, "_campaign_graph_view", None)
    if not isinstance(graph_view, dict):
        graph_view = {"zoom": 1.0, "pan_x": 0.0, "pan_y": 0.0}
        self._campaign_graph_view = graph_view
    canvas.pack(fill=tk.X)
    from .campaign_graph_presentation import (
        GraphToolbar, CanvasWorkflowFocus, resolve_workflow_focus, close_graph_dialogs,
        GraphSignalMotion, gate_electrode_style, graph_signal_color,
    )
    toolbar_commands = {}
    graph_toolbar = GraphToolbar(canvas, palette, toolbar_commands)
    workflow_focus_style = CanvasWorkflowFocus(canvas, palette)
    self.campaign_transition_graph_canvas = canvas
    try:
        if bool(getattr(self, "_campaign_graph_fullscreen", False)):
            self.frame.after_idle(self._apply_campaign_graph_fullscreen_layout)
    except Exception:
        pass
    gate_offsets = getattr(self, "_campaign_graph_gate_offsets", None)
    if not isinstance(gate_offsets, dict):
        gate_offsets = {}
        self._campaign_graph_gate_offsets = gate_offsets
    auto_gate_positions = getattr(self, "_campaign_graph_auto_gate_positions", None)
    if not isinstance(auto_gate_positions, dict):
        auto_gate_positions = {}
        self._campaign_graph_auto_gate_positions = auto_gate_positions
    node_offsets = getattr(self, "_campaign_graph_node_offsets", None)
    if not isinstance(node_offsets, dict):
        node_offsets = {}
        self._campaign_graph_node_offsets = node_offsets
    gate_zoom_scales = getattr(self, "_campaign_graph_gate_zoom_scales", None)
    if not isinstance(gate_zoom_scales, dict):
        gate_zoom_scales = {}
        self._campaign_graph_gate_zoom_scales = gate_zoom_scales
    gate_zoom_anim_state = {"after_id": None}
    gate_drag_state = {
        "edge_key": "",
        "start_x": 0,
        "start_y": 0,
        "last_x": 0,
        "last_y": 0,
        "orig_x": 0.0,
        "orig_y": 0.0,
        "anchor_screen_x": None,
        "anchor_screen_y": None,
        "anchor_world_x": None,
        "anchor_world_y": None,
    }
    node_drag_state = {"stage_key": "", "start_x": 0, "start_y": 0, "orig_x": 0.0, "orig_y": 0.0}
    graph_focus_state = {"kind": "", "key": ""}
    graph_pan_state = {
        "active": False,
        "start_x": 0,
        "start_y": 0,
        "orig_x": 0.0,
        "orig_y": 0.0,
        "pending_x": 0,
        "pending_y": 0,
        "after_id": None,
    }
    graph_redraw_state = {"after_id": None}
    graph_drag_redraw_state = {"after_id": None}
    graph_zoom_preview_state = {"after_id": None, "factor": 1.0, "x": 0.0, "y": 0.0}
    graph_zoom_text_preview_cache: dict[int, dict[str, object]] = {}
    graph_zoom_preview_delay_ms = 8
    graph_zoom_redraw_delay_ms = 120
    gate_geometry: dict[str, dict[str, float]] = {}
    gate_field_geometry: dict[str, dict[str, float | str]] = {}
    gate_selector_geometry: dict[str, dict[str, float | str | bool]] = {}
    gate_selector_hover: dict[str, object] = {}
    node_geometry: dict[str, dict[str, float]] = {}
    edge_line_items: dict[str, int] = {}
    edge_arrow_items: dict[str, int] = {}
    node_connector_items: dict[str, int] = {}
    gate_connector_items: dict[str, int] = {}
    gate_selector_arc_geometry: dict[str, dict[str, float]] = {}
    graph_render_helpers: dict[str, object] = {}
    approve_blink_active_keys: set[str] = set()
    graph_wizard_stage_status_cache: dict[str, object] = {}
    def _graph_zoom() -> float:
        try:
            return max(0.65, min(2.4, float(graph_view.get("zoom", 1.0) or 1.0)))
        except Exception:
            return 1.0

    def _graph_pan() -> tuple[float, float]:
        try:
            return (
                float(graph_view.get("pan_x", 0.0) or 0.0),
                float(graph_view.get("pan_y", 0.0) or 0.0),
            )
        except Exception:
            return (0.0, 0.0)

    def _screen_x(world_x: float, width_value: float | None = None) -> float:
        current_width = float(width_value if width_value is not None else max(int(canvas.winfo_width() or 840), 720))
        zoom = _graph_zoom()
        pan_x, _pan_y = _graph_pan()
        center_x = current_width / 2
        return center_x + (float(world_x) - center_x) * zoom + pan_x

    def _screen_y(world_y: float, height_value: float | None = None) -> float:
        current_height = float(height_value if height_value is not None else max(int(canvas.winfo_height() or 520), 420))
        zoom = _graph_zoom()
        _pan_x, pan_y = _graph_pan()
        center_y = current_height / 2
        return center_y + (float(world_y) - center_y) * zoom + pan_y

    def _world_x(screen_x: float, width_value: float | None = None) -> float:
        current_width = float(width_value if width_value is not None else max(int(canvas.winfo_width() or 840), 720))
        zoom = _graph_zoom()
        pan_x, _pan_y = _graph_pan()
        center_x = current_width / 2
        return center_x + (float(screen_x) - pan_x - center_x) / max(0.001, zoom)

    def _world_y(screen_y: float, height_value: float | None = None) -> float:
        current_height = float(height_value if height_value is not None else max(int(canvas.winfo_height() or 520), 420))
        zoom = _graph_zoom()
        _pan_x, pan_y = _graph_pan()
        center_y = current_height / 2
        return center_y + (float(screen_y) - pan_y - center_y) / max(0.001, zoom)

    def _apply_graph_view(width_value: float, height_value: float) -> None:
        zoom = _graph_zoom()
        pan_x, pan_y = _graph_pan()
        if abs(zoom - 1.0) > 0.001:
            canvas.scale("!graph_overlay_fixed", width_value / 2, height_value / 2, zoom, zoom)
        if abs(pan_x) > 0.001 or abs(pan_y) > 0.001:
            canvas.move("!graph_overlay_fixed", pan_x, pan_y)

    def _rect_border_contact_from_external_point(
        rect_x0: float,
        rect_y0: float,
        rect_x1: float,
        rect_y1: float,
        external_x: float,
        external_y: float,
    ) -> tuple[float, float]:
        left = min(float(rect_x0), float(rect_x1))
        right = max(float(rect_x0), float(rect_x1))
        top = min(float(rect_y0), float(rect_y1))
        bottom = max(float(rect_y0), float(rect_y1))
        center_x = (left + right) / 2.0
        center_y = (top + bottom) / 2.0
        dx = float(external_x) - center_x
        dy = float(external_y) - center_y
        if abs(dx) <= 0.001 and abs(dy) <= 0.001:
            return center_x, top
        scale_x = ((right - left) / 2.0) / abs(dx) if abs(dx) > 0.001 else float("inf")
        scale_y = ((bottom - top) / 2.0) / abs(dy) if abs(dy) > 0.001 else float("inf")
        scale = min(scale_x, scale_y)
        return (
            max(left, min(right, center_x + dx * scale)),
            max(top, min(bottom, center_y + dy * scale)),
        )

    def _connector_coords_for_edge(
        _edge,
        anchor_x: float,
        anchor_y: float,
        gate_cx: float,
        gate_cy: float,
        *,
        screen_coords: bool = False,
    ) -> tuple[float, float, float, float]:
        edge_key = str(getattr(_edge, "key", "") or "").strip()
        anchor_x = float(anchor_x)
        anchor_y = float(anchor_y)
        gate_cx = float(gate_cx)
        gate_cy = float(gate_cy)
        geom = gate_geometry.get(edge_key) if edge_key else None
        if not isinstance(geom, dict):
            return anchor_x, anchor_y, gate_cx, gate_cy
        try:
            world_x = float(geom.get("x", 0.0) or 0.0)
            world_y = float(geom.get("y", 0.0) or 0.0)
            gate_w = float(geom.get("gate_w", 0.0) or 0.0)
            gate_h = float(geom.get("gate_h", 0.0) or 0.0)
        except Exception:
            return anchor_x, anchor_y, gate_cx, gate_cy
        if gate_w <= 0.0 or gate_h <= 0.0:
            return anchor_x, anchor_y, gate_cx, gate_cy

        world_cx = world_x + gate_w / 2.0
        world_cy = world_y + gate_h / 2.0
        if bool(screen_coords):
            x0 = _screen_x(world_x)
            y0 = _screen_y(world_y)
            x1 = _screen_x(world_x + gate_w)
            y1 = _screen_y(world_y + gate_h)
        else:
            x0 = world_x
            y0 = world_y
            x1 = world_x + gate_w
            y1 = world_y + gate_h
        contact_x, contact_y = _rect_border_contact_from_external_point(
            x0,
            y0,
            x1,
            y1,
            anchor_x,
            anchor_y,
        )
        return anchor_x, anchor_y, contact_x, contact_y

    def _set_gate_connector_coords(edge_key: str, coords: tuple[float, float, float, float]) -> None:
        normalized_key = str(edge_key or "").strip()
        if not normalized_key:
            return
        connector_id = gate_connector_items.get(normalized_key)
        try:
            if connector_id and canvas.type(connector_id):
                canvas.coords(connector_id, *coords)
                return
        except Exception:
            gate_connector_items.pop(normalized_key, None)
        try:
            connector_tag = f"gate-connector:{normalized_key}"
            matches = canvas.find_withtag(connector_tag)
            if matches:
                gate_connector_items[normalized_key] = int(matches[0])
                canvas.coords(matches[0], *coords)
        except Exception:
            pass

    def _edge_for_key(edge_key: str):
        normalized = str(edge_key or "").strip()
        for graph_edge in CAMPAIGN_TRANSITION_GRAPH.edges:
            if str(getattr(graph_edge, "key", "")) == normalized:
                return graph_edge
        return None

    def _stop_gate_approve_blink() -> None:
        try:
            after_id = getattr(self, "_campaign_graph_approve_blink_after_id", None)
            if after_id:
                canvas.after_cancel(after_id)
        except Exception:
            pass
        try:
            card_success = palette["campaign_card_success"]
            card_surface = palette["campaign_gate_surface"]
            card_text = palette["campaign_card_text"]
            canvas.itemconfigure(
                "gate_approve_blink_rect",
                fill=blend_hex_colors(card_surface, card_success, 0.16),
                outline=blend_hex_colors(card_success, card_bg, 0.18),
            )
            canvas.itemconfigure("gate_approve_blink_text", fill=card_text)
        except Exception:
            pass
        self._campaign_graph_approve_blink_after_id = None
        self._campaign_graph_approve_blink_phase = False
        self._campaign_graph_approve_blink_started_at = 0.0

    def _graph_modal_activity_active() -> bool:
        try:
            checker = getattr(getattr(self, "app", None), "_has_active_dialog", None)
            if callable(checker) and checker():
                return True
        except Exception:
            pass
        try:
            return bool(getattr(self, "_project_loading_overlay_visible", False))
        except Exception:
            return False

    def _pulse_gate_approve_fields() -> None:
        try:
            if not bool(canvas.winfo_exists()):
                _stop_gate_approve_blink()
                return
            if not canvas.find_withtag("gate_approve_blink_rect"):
                _stop_gate_approve_blink()
                return
            if _graph_modal_activity_active():
                self._campaign_graph_approve_blink_after_id = canvas.after(650, _pulse_gate_approve_fields)
                return
            started_at = float(getattr(self, "_campaign_graph_approve_blink_started_at", 0.0) or 0.0)
            if started_at > 0.0 and (perf_counter() - started_at) >= 5.0:
                try:
                    seen = getattr(self, "_campaign_graph_approve_blink_seen_keys", None)
                    if isinstance(seen, set):
                        seen.update(approve_blink_active_keys)
                except Exception:
                    pass
                _stop_gate_approve_blink()
                return
            phase = not bool(getattr(self, "_campaign_graph_approve_blink_phase", False))
            self._campaign_graph_approve_blink_phase = phase
            card_success = palette["campaign_card_success"]
            card_surface = palette["campaign_gate_surface"]
            card_text = palette["campaign_card_text"]
            card_text_inverse = palette["campaign_graph_bg"]
            if phase:
                rect_fill = blend_hex_colors(card_surface, card_success, 0.34)
                rect_outline = blend_hex_colors(card_success, card_bg, 0.10)
                text_fill = card_text_inverse
            else:
                rect_fill = blend_hex_colors(card_surface, card_success, 0.16)
                rect_outline = blend_hex_colors(card_success, card_bg, 0.18)
                text_fill = card_text
            canvas.itemconfigure("gate_approve_blink_rect", fill=rect_fill, outline=rect_outline)
            canvas.itemconfigure("gate_approve_blink_text", fill=text_fill)
            self._campaign_graph_approve_blink_after_id = canvas.after(520, _pulse_gate_approve_fields)
        except tk.TclError:
            self._campaign_graph_approve_blink_after_id = None
        except Exception:
            self._campaign_graph_approve_blink_after_id = None

    def _sync_gate_approve_blink() -> None:
        try:
            if not canvas.find_withtag("gate_approve_blink_rect"):
                _stop_gate_approve_blink()
                return
            if getattr(self, "_campaign_graph_approve_blink_after_id", None):
                return
            self._campaign_graph_approve_blink_phase = False
            self._campaign_graph_approve_blink_started_at = perf_counter()
            _pulse_gate_approve_fields()
        except Exception:
            _stop_gate_approve_blink()

    def _raise_graph_overlay_layers() -> None:
        workflow_focus_style.apply(_workflow_focus_scope(), refresh_links=True)
        # Signals belong under every card, including inactive and dragged cards.
        # Keep the cards' existing stacking order when placing a new frame.
        for item in canvas.find_all():
            if any(tag.startswith(("gate-group:", "node-group:")) for tag in canvas.gettags(item)):
                canvas.tag_lower("graph_attention_flow", item)
                break
        for tag in (
            "gate_selector_arc_anim",
            "gate_approve_blink_rect",
            "gate_approve_blink_text",
            "gate_field_hover",
            "gate_selector_tooltip",
            "graph_overlay_fixed",
        ):
            try:
                canvas.tag_raise(tag)
            except Exception:
                pass
        _sync_graph_toolbar()

    def _raise_graph_gate_bundle(edge_key: str) -> None:
        normalized_key = str(edge_key or "").strip()
        if not normalized_key:
            return
        for tag in (
            f"gate-connector:{normalized_key}",
            f"gate-group:{normalized_key}",
            f"gate_selector_arc_anim:{normalized_key}",
        ):
            try:
                canvas.tag_raise(tag)
            except Exception:
                pass

    def _raise_graph_stage_bundle(stage_key: str) -> None:
        normalized_stage_key = str(stage_key or "").strip().upper()
        if not normalized_stage_key:
            return
        try:
            for graph_edge in CAMPAIGN_TRANSITION_GRAPH.edges:
                edge_key = str(getattr(graph_edge, "key", "") or "").strip()
                if not edge_key:
                    continue
                source_key = str(getattr(graph_edge, "source", "") or "").strip().upper()
                target_key = str(getattr(graph_edge, "target", "") or "").strip().upper()
                if source_key != normalized_stage_key and target_key != normalized_stage_key:
                    continue
                for tag in (
                    f"edge-line:{edge_key}",
                    f"graph_edge_arrow:{edge_key}",
                    f"gate-connector:{edge_key}",
                ):
                    try:
                        canvas.tag_raise(tag)
                    except Exception:
                        pass
            if normalized_stage_key in {"E1", "E4T", "E4Z"}:
                for tag in ("graph_return_trunk", "graph_edge_arrow:return_trunk", "graph_return_junction"):
                    try:
                        canvas.tag_raise(tag)
                    except Exception:
                        pass
        except Exception:
            pass
        for tag in (f"node-output-connector:{normalized_stage_key}", f"node-group:{normalized_stage_key}"):
            try:
                canvas.tag_raise(tag)
            except Exception:
                pass

    def _raise_drag_target_layers() -> None:
        """The element grabbed by the user must visually sit above the graph."""

        _raise_graph_stage_bundle(str(node_drag_state.get("stage_key") or ""))
        _raise_graph_gate_bundle(str(gate_drag_state.get("edge_key") or ""))

    def _raise_graph_interactive_layers() -> None:
        """Keep graph controls clickable after overlays and timer animations repaint."""

        try:
            canvas.tag_lower("edge_line")
        except Exception:
            pass
        for tag_spec in (
            ("graph_return_trunk",),
            ("graph_edge_arrow", "edge_line"),
            ("graph_node_junction",),
            ("graph_node_output_connector",),
            ("gate_connector",),
        ):
            try:
                canvas.tag_raise(*tag_spec)
            except Exception:
                pass
        try:
            for stage_key in CAMPAIGN_GRAPH_STAGE_ORDER:
                canvas.tag_raise(f"node-group:{stage_key}")
        except Exception:
            pass
        placeholder_gate_keys: list[str] = []
        expanded_gate_keys: list[str] = []
        try:
            for graph_edge in CAMPAIGN_TRANSITION_GRAPH.edges:
                edge_key = str(getattr(graph_edge, "key", "") or "").strip()
                if not edge_key:
                    continue
                if _edge_gate_active(graph_edge):
                    expanded_gate_keys.append(edge_key)
                else:
                    placeholder_gate_keys.append(edge_key)
            for edge_key in placeholder_gate_keys:
                canvas.tag_raise(f"gate-group:{edge_key}")
            for edge_key in expanded_gate_keys:
                canvas.tag_raise(f"gate-group:{edge_key}")
        except Exception:
            pass
        workflow_focus_style.raise_scope(_workflow_focus_scope())
        focus_kind = str(graph_focus_state.get("kind") or "").strip().lower()
        focus_key = str(graph_focus_state.get("key") or "").strip()
        if focus_kind == "node":
            _raise_graph_stage_bundle(focus_key)
        elif focus_kind == "gate":
            _raise_graph_gate_bundle(focus_key)
        _raise_drag_target_layers()
        _raise_graph_overlay_layers()

    def _stop_gate_selector_arc_animation(*, clear_items: bool = True) -> None:
        try:
            after_id = getattr(self, "_campaign_graph_selector_arc_after_id", None)
            if after_id:
                canvas.after_cancel(after_id)
        except Exception:
            pass
        self._campaign_graph_selector_arc_after_id = None
        if clear_items:
            try:
                canvas.delete("gate_selector_arc_anim")
            except Exception:
                pass

    def _draw_gate_selector_arc_animation() -> None:
        try:
            if not bool(canvas.winfo_exists()):
                _stop_gate_selector_arc_animation(clear_items=False)
                return
        except Exception:
            _stop_gate_selector_arc_animation(clear_items=False)
            return

        if not gate_selector_arc_geometry:
            _stop_gate_selector_arc_animation(clear_items=True)
            return

        try:
            if _graph_modal_activity_active():
                try:
                    canvas.delete("gate_selector_arc_anim")
                except Exception:
                    pass
                self._campaign_graph_selector_arc_after_id = canvas.after(650, _draw_gate_selector_arc_animation)
                return
            canvas.delete("gate_selector_arc_anim")
            width = max(int(canvas.winfo_width() or 840), 720)
            height = max(int(canvas.winfo_height() or 520), 420)
            zoom = _graph_zoom()
            phase = int(perf_counter() * 2.0) % 2
            for edge_key, geom in gate_selector_arc_geometry.items():
                e1_x = _screen_x(float(geom.get("e1_x", 0.0)), width)
                e2_x = _screen_x(float(geom.get("e2_x", 0.0)), width)
                mid_y = _screen_y(float(geom.get("mid_y", 0.0)), height)
                e_top = _screen_y(float(geom.get("e_top", 0.0)), height)
                e_bottom = _screen_y(float(geom.get("e_bottom", 0.0)), height)
                local_zoom = max(0.55, float(geom.get("local_zoom", 1.0) or 1.0) * zoom)
                gap = max(2.8 * local_zoom, abs(e2_x - e1_x))
                box_size = max(
                    4.0 * local_zoom,
                    min(gap * 0.86, abs(e_bottom - e_top) * 0.58, 7.4 * local_zoom),
                )
                box_cx = (e1_x + e2_x) / 2.0
                box_x0 = box_cx - box_size / 2.0
                box_x1 = box_cx + box_size / 2.0
                box_y0 = mid_y - box_size / 2.0
                box_y1 = mid_y + box_size / 2.0
                split_x = box_cx
                off_fill = blend_hex_colors(palette["campaign_electrode_off"], card_bg, 0.18)
                left_fill = palette["campaign_electrode_left"] if phase == 0 else off_fill
                right_fill = off_fill if phase == 0 else palette["campaign_electrode_right"]
                border = blend_hex_colors(palette["campaign_electrode_border"], card_bg, 0.34)
                canvas.create_rectangle(
                    box_x0,
                    box_y0,
                    box_x1,
                    box_y1,
                    fill=blend_hex_colors(off_fill, palette["blend_light"], 0.04),
                    outline=border,
                    width=max(1, int(round(0.8 * local_zoom))),
                    state=tk.DISABLED,
                    tags=("gate_selector_arc_anim", f"gate_selector_arc_anim:{edge_key}", f"gate-group:{edge_key}"),
                )
                canvas.create_rectangle(
                    box_x0 + 1,
                    box_y0 + 1,
                    split_x,
                    box_y1 - 1,
                    fill=left_fill,
                    outline="",
                    state=tk.DISABLED,
                    tags=("gate_selector_arc_anim", f"gate_selector_arc_anim:{edge_key}", f"gate-group:{edge_key}"),
                )
                canvas.create_rectangle(
                    split_x,
                    box_y0 + 1,
                    box_x1 - 1,
                    box_y1 - 1,
                    fill=right_fill,
                    outline="",
                    state=tk.DISABLED,
                    tags=("gate_selector_arc_anim", f"gate_selector_arc_anim:{edge_key}", f"gate-group:{edge_key}"),
                )
                canvas.create_line(
                    split_x,
                    box_y0 + 0.8 * local_zoom,
                    split_x,
                    box_y1 - 0.8 * local_zoom,
                    fill=blend_hex_colors(border, card_bg, 0.18),
                    width=max(1, int(round(0.7 * local_zoom))),
                    state=tk.DISABLED,
                    tags=("gate_selector_arc_anim", f"gate_selector_arc_anim:{edge_key}", f"gate-group:{edge_key}"),
                )
            _raise_graph_interactive_layers()
            self._campaign_graph_selector_arc_after_id = canvas.after(500, _draw_gate_selector_arc_animation)
        except tk.TclError:
            self._campaign_graph_selector_arc_after_id = None
        except Exception:
            self._campaign_graph_selector_arc_after_id = None

    def _sync_gate_selector_arc_animation() -> None:
        if not gate_selector_arc_geometry:
            _stop_gate_selector_arc_animation(clear_items=True)
            return
        try:
            after_id = getattr(self, "_campaign_graph_selector_arc_after_id", None)
            if after_id:
                canvas.after_cancel(after_id)
        except Exception:
            pass
        self._campaign_graph_selector_arc_after_id = None
        _draw_gate_selector_arc_animation()

    def _gate_local_zoom(edge_key: str) -> float:
        try:
            return max(1.0, min(1.55, float(gate_zoom_scales.get(edge_key, 1.0) or 1.0)))
        except Exception:
            return 1.0

    def _animate_gate_local_zoom(edge_key: str, target: float) -> None:
        try:
            after_id = gate_zoom_anim_state.get("after_id")
            if after_id:
                canvas.after_cancel(after_id)
        except Exception:
            pass
        target = max(1.0, min(1.42, float(target)))
        try:
            if target <= 1.001:
                gate_zoom_scales.pop(edge_key, None)
            else:
                gate_zoom_scales[edge_key] = target
            gate_zoom_anim_state["after_id"] = None
            _request_graph_redraw(delay_ms=1, restart=True)
        except tk.TclError:
            gate_zoom_anim_state["after_id"] = None
        except Exception:
            gate_zoom_anim_state["after_id"] = None

    def _toggle_gate_local_zoom(edge_key: str) -> None:
        current = _gate_local_zoom(edge_key)
        target = 1.0 if current > 1.12 else 1.42
        for other_key in list(gate_zoom_scales.keys()):
            if other_key != edge_key:
                gate_zoom_scales.pop(other_key, None)
        _animate_gate_local_zoom(edge_key, target)

    def _stage_num(stage_key: str) -> int:
        return campaign_stage_step(stage_key)

    def _stage_status_value(stage_key: str) -> str:
        normalized = str(stage_key or "").strip().upper()
        status_key = campaign_stage_status_key(normalized)
        return str(stage_status.get(status_key, "") or stage_status.get(normalized, "") or "").strip().lower()

    def _collect_active_step2_run_approved_delta(project_approved_image_names: set[str]) -> tuple[int, int, str]:
        """Return [OK] images/plates from the active Z2 run that are not yet in ApprovedSet."""
        try:
            annotation_tab = self.app.tabs.get("annotation") if getattr(self.app, "tabs", None) else None
        except Exception:
            annotation_tab = None

        def _safe_run_dir(candidate) -> Path | None:
            if candidate is None:
                return None
            resolver = getattr(annotation_tab, "_resolve_safe_annotation_run_dir", None) if annotation_tab is not None else None
            if callable(resolver):
                try:
                    resolved = resolver(candidate, require_xml=True)
                    if resolved is not None:
                        return Path(resolved)
                except Exception:
                    pass
            try:
                path = Path(candidate)
            except Exception:
                return None
            try:
                if path.exists() and path.is_dir() and (path / "annotations.xml").exists():
                    return path
            except Exception:
                return None
            return None

        try:
            campaign_step2_run = CAMPAIGN.get_step2_staging_run()
        except Exception:
            campaign_step2_run = ""
        candidates = [
            getattr(annotation_tab, "current_annotation_run_dir", None) if annotation_tab is not None else None,
            getattr(annotation_tab, "last_staging_run_dir", None) if annotation_tab is not None else None,
            campaign_step2_run,
        ]

        seen_run_keys: set[str] = set()
        for candidate in candidates:
            run_dir = _safe_run_dir(candidate)
            if run_dir is None:
                continue
            try:
                run_key = str(run_dir.resolve()).strip().lower()
            except Exception:
                run_key = str(run_dir).strip().lower()
            if not run_key or run_key in seen_run_keys:
                continue
            seen_run_keys.add(run_key)

            paths_equivalent = getattr(annotation_tab, "_paths_equivalent", None) if annotation_tab is not None else None
            is_current_run = False
            try:
                current_run = getattr(annotation_tab, "current_annotation_run_dir", None) if annotation_tab is not None else None
                is_current_run = bool(
                    current_run is not None
                    and callable(paths_equivalent)
                    and paths_equivalent(current_run, run_dir)
                    and getattr(annotation_tab, "current_annotations", None)
                )
            except Exception:
                is_current_run = False

            if is_current_run:
                try:
                    annotations = list(getattr(annotation_tab, "current_annotations", []) or [])
                except Exception:
                    annotations = []
                approved_getter = getattr(annotation_tab, "_get_preview_approved_filenames", None)
                try:
                    approved_filenames = set(approved_getter() or set()) if callable(approved_getter) else set()
                except Exception:
                    approved_filenames = set()
            else:
                parser = getattr(annotation_tab, "_parse_cvat_preview_annotations", None) if annotation_tab is not None else None
                approved_loader = (
                    getattr(annotation_tab, "_load_annotation_run_approved_filenames", None)
                    if annotation_tab is not None
                    else None
                )
                try:
                    annotations = list(parser(run_dir / "annotations.xml") or []) if callable(parser) else []
                except Exception:
                    annotations = []
                try:
                    approved_filenames = set(approved_loader(run_dir) or set()) if callable(approved_loader) else set()
                except Exception:
                    approved_filenames = set()

            if not annotations or not approved_filenames:
                try:
                    manifest = CAMPAIGN._load_annotation_run_manifest_file(run_dir)
                except Exception:
                    manifest = {}
                approved_payload = manifest.get("approved_filenames") if isinstance(manifest, dict) else None
                approved_lookup = {
                    str(name or "").strip().lower()
                    for name in set(approved_payload or set())
                    if str(name or "").strip()
                }
                if approved_lookup:
                    try:
                        counts_by_image = CAMPAIGN._load_run_plate_counts_by_image(run_dir, image_names=approved_lookup)
                    except Exception:
                        counts_by_image = {}
                    delta_images = 0
                    delta_plates = 0
                    for image_key, plate_count in dict(counts_by_image or {}).items():
                        normalized_key = str(image_key or "").strip().lower()
                        if not normalized_key or normalized_key in project_approved_image_names:
                            continue
                        try:
                            safe_count = int(plate_count or 0)
                        except Exception:
                            safe_count = 0
                        if safe_count <= 0:
                            continue
                        delta_images += 1
                        delta_plates += safe_count
                    if delta_images > 0 or delta_plates > 0:
                        return int(delta_images), int(delta_plates), str(run_dir.name or "")
                continue

            approved_lookup = {
                str(name or "").strip().lower()
                for name in approved_filenames
                if str(name or "").strip()
            }
            if not approved_lookup:
                continue

            plate_detector = getattr(annotation_tab, "_get_plate_detections", None) if annotation_tab is not None else None
            delta_images = 0
            delta_plates = 0
            for ann in annotations:
                image_name = str(getattr(ann, "filename", "") or "").strip()
                image_key = image_name.lower()
                if not image_key or image_key not in approved_lookup:
                    continue
                if image_key in project_approved_image_names:
                    continue
                try:
                    plate_count = len(plate_detector(ann)) if callable(plate_detector) else 0
                except Exception:
                    plate_count = 0
                if plate_count <= 0:
                    continue
                delta_images += 1
                delta_plates += int(plate_count)

            if delta_images > 0 or delta_plates > 0:
                return int(delta_images), int(delta_plates), str(run_dir.name or "")

        return 0, 0, ""

    def _current_step4_without_training_decision_ready() -> bool:
        try:
            decision = dict(CAMPAIGN.get_step4_without_training_decision() or {})
        except Exception:
            decision = {}
        if not bool(decision.get("ready")):
            return False
        try:
            decision_iteration = int(decision.get("iteration", 0) or 0)
        except Exception:
            decision_iteration = 0
        decision_target = str(decision.get("target", "") or "").strip().lower()
        active_target = str(current_target or "").strip().lower()
        return bool(
            decision_iteration == int(current_iteration or 0)
            and (not decision_target or not active_target or decision_target == active_target)
        )

    def _current_iteration_step4_training_record() -> dict:
        try:
            iteration_num = int(current_iteration or 0)
        except Exception:
            iteration_num = 0
        if iteration_num <= 0:
            return {}

        try:
            synced = dict(CAMPAIGN.sync_step4_training_record_from_history(iteration_num=iteration_num) or {})
            if synced:
                synced.setdefault("iteration", iteration_num)
                synced.setdefault("trained_iteration", iteration_num)
                return synced
        except Exception:
            pass

        def _declared_training_iteration(record: dict) -> int:
            if not isinstance(record, dict):
                return 0
            for field in ("trained_iteration", "source_iteration", "iteration"):
                try:
                    value = int(record.get(field, 0) or 0)
                except Exception:
                    value = 0
                if value > 0:
                    return value
            return 0

        try:
            iteration_state = dict(CAMPAIGN.get_iteration_state(iteration_num=iteration_num) or {})
            record = dict(iteration_state.get("step4_training") or {})
        except Exception:
            record = {}
        if record:
            record.setdefault("iteration", iteration_num)
            record.setdefault("trained_iteration", iteration_num)
            return record
        try:
            bundle = dict(CAMPAIGN.get_iteration_artifact_bundle(iteration_num=iteration_num) or {})
            bundle_record = dict(bundle.get("step4_training") or {})
            if _declared_training_iteration(bundle_record) == iteration_num:
                record = bundle_record
            else:
                record = {}
        except Exception:
            record = {}
        return record

    def _current_iteration_step4_dataset_record() -> dict:
        try:
            iteration_num = int(current_iteration or 0)
        except Exception:
            iteration_num = 0
        if iteration_num <= 0:
            return {}

        def _declared_dataset_iteration(record: dict) -> int:
            if not isinstance(record, dict):
                return 0
            for field in ("dataset_iteration", "created_iteration", "iteration"):
                try:
                    value = int(record.get(field, 0) or 0)
                except Exception:
                    value = 0
                if value > 0:
                    return value
            return 0

        try:
            iteration_state = dict(CAMPAIGN.get_iteration_state(iteration_num=iteration_num) or {})
            record = dict(iteration_state.get("step4_dataset") or {})
        except Exception:
            record = {}
        if record:
            record.setdefault("iteration", iteration_num)
            return record
        try:
            bundle = dict(CAMPAIGN.get_iteration_artifact_bundle(iteration_num=iteration_num) or {})
            bundle_record = dict(bundle.get("step4_dataset") or {})
            if _declared_dataset_iteration(bundle_record) == iteration_num:
                record = bundle_record
            else:
                record = {}
        except Exception:
            record = {}
        return record

    def _current_t07_training_finish_state() -> dict:
        try:
            target = str(current_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
        except Exception:
            target = str(current_target or "").strip().lower()
        try:
            training_tab = self.app.tabs.get("training") if getattr(self.app, "tabs", None) else None
            getter = getattr(training_tab, "get_campaign_step4_finish_state", None)
            finish_state = (
                dict(getter(iteration_target=target) or {})
                if callable(getter)
                else dict(CAMPAIGN.get_step4_finish_state() or {})
            )
        except Exception:
            try:
                finish_state = dict(CAMPAIGN.get_step4_finish_state() or {})
            except Exception:
                finish_state = {}
        if not bool(finish_state.get("ready")):
            return {}
        if not str(finish_state.get("run_id", "") or "").strip():
            return {}
        try:
            finish_iteration = int(finish_state.get("iteration", 0) or 0)
        except Exception:
            finish_iteration = 0
        finish_target = str(finish_state.get("target", "") or "").strip().lower()
        active_target = str(target or current_target or "").strip().lower()
        if finish_iteration != int(current_iteration or 0):
            return {}
        if finish_target and active_target and finish_target != active_target:
            return {}
        selected_model_path = str(finish_state.get("model_path", "") or "").strip()
        if bool(finish_state.get("selection_confirmed", True)) and selected_model_path:
            try:
                selected_model_ready = bool(Path(selected_model_path).exists() and Path(selected_model_path).is_file())
            except Exception:
                selected_model_ready = bool(selected_model_path)
            if selected_model_ready:
                finish_state["iteration"] = finish_iteration
                finish_state["target"] = finish_target or active_target
                return dict(finish_state)
        run_id = str(finish_state.get("run_id", "") or "").strip()
        training_record = _current_iteration_step4_training_record()
        if not training_record:
            return {}
        record_run_id = str(training_record.get("run_id", "") or "").strip()
        if not record_run_id or record_run_id != run_id:
            return {}
        record_target = str(training_record.get("target", "") or "").strip().lower()
        if record_target and active_target and record_target != active_target:
            return {}
        record_status = str(training_record.get("status", "") or "").strip().lower()
        if record_status and record_status != "completed":
            return {}
        best_weights = str(training_record.get("best_weights", "") or "").strip()
        if not best_weights:
            return {}
        try:
            if not Path(best_weights).exists():
                return {}
        except Exception:
            return {}
        finish_state["iteration"] = finish_iteration
        finish_state["target"] = finish_target or record_target or active_target
        return dict(finish_state)

    def _current_t07_training_finish_ready() -> bool:
        return bool(_current_t07_training_finish_state())

    step4_training_candidate_cache: dict | None = None

    def _current_t07_training_candidate_state() -> dict:
        """Completed current-iteration training that still waits for explicit model choice."""

        nonlocal step4_training_candidate_cache
        if step4_training_candidate_cache is not None:
            return dict(step4_training_candidate_cache)
        step4_training_candidate_cache = {}
        if _current_t07_training_finish_state():
            return {}
        training_record = _current_iteration_step4_training_record()
        if not training_record:
            return {}
        record_status = str(training_record.get("status", "") or "").strip().lower()
        if record_status != "completed":
            return {}
        try:
            target = str(current_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
        except Exception:
            target = str(current_target or "").strip().lower()
        record_target = str(training_record.get("target", "") or "").strip().lower()
        if record_target and target and record_target != target:
            return {}
        best_weights = str(training_record.get("best_weights", "") or "").strip()
        if not best_weights:
            return {}
        try:
            if not Path(best_weights).exists():
                return {}
        except Exception:
            return {}
        try:
            record_iteration = int(training_record.get("trained_iteration", 0) or training_record.get("iteration", 0) or 0)
        except Exception:
            record_iteration = 0
        try:
            active_iteration = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 0)
        except Exception:
            active_iteration = 0
        if record_iteration > 0 and active_iteration > 0 and record_iteration != active_iteration:
            return {}
        result = dict(training_record)
        result.setdefault("target", record_target or target)
        result.setdefault("iteration", record_iteration or active_iteration)
        step4_training_candidate_cache = dict(result)
        return result

    step4_work_interruption_cache: dict | None = None

    def _current_t07_training_failure_state() -> dict:
        training_record = _current_iteration_step4_training_record()
        if not training_record:
            return {}
        record_status = str(training_record.get("status", "") or "").strip().lower()
        if record_status not in {"failed", "cancelled", "paused"}:
            return {}
        try:
            target = str(current_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
        except Exception:
            target = str(current_target or "").strip().lower()
        record_target = str(training_record.get("target", "") or "").strip().lower()
        if record_target and target and record_target != target:
            return {}
        return dict(training_record)

    def _current_step4_work_interruption_state() -> dict:
        nonlocal step4_work_interruption_cache
        if step4_work_interruption_cache is not None:
            return dict(step4_work_interruption_cache)
        step4_work_interruption_cache = {}
        if (
            _current_t07_training_finish_state()
            or _current_t07_training_candidate_state()
            or _current_step4_without_training_decision_ready()
        ):
            return {}
        training_failure = _current_t07_training_failure_state()
        try:
            current_iteration_value = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 0)
        except Exception:
            current_iteration_value = 0
        if current_iteration_value <= 0:
            return {}
        try:
            state = dict(CAMPAIGN.get_iteration_state(iteration_num=current_iteration_value) or {})
            session = dict(state.get("step4_work_session") or {})
        except Exception:
            session = {}
        if not session:
            if training_failure:
                result = dict(training_failure)
                fallback_target = str(current_target or "").strip().lower()
                if not fallback_target:
                    try:
                        fallback_target = str(CAMPAIGN.get_iteration_target() or "").strip().lower()
                    except Exception:
                        fallback_target = ""
                result.update(
                    {
                        "active": True,
                        "state": "interrupted",
                        "work_area": "z4",
                        "substep": "train",
                    }
                )
                result.setdefault("iteration", current_iteration_value)
                result.setdefault("target", fallback_target)
                step4_work_interruption_cache = dict(result)
                return result
            return {}
        session_state = str(session.get("state", "") or "").strip().lower()
        if not bool(session.get("active")) and session_state != "interrupted":
            return {}
        if session_state not in {
            "interrupted",
            "active",
            "paused",
            "training_failed",
            "training_paused",
            "training_cancelled",
            "training_pending",
            "training_running",
        }:
            return {}
        session_target = str(session.get("target", "") or "").strip().lower()
        active_target = str(current_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
        if session_target and active_target and session_target != active_target:
            return {}
        try:
            session_iteration = int(session.get("iteration", 0) or 0)
        except Exception:
            session_iteration = 0
        if session_iteration and session_iteration != current_iteration_value:
            return {}
        result = dict(session)
        result.setdefault("state", session_state or "interrupted")
        result.setdefault("iteration", current_iteration_value)
        result.setdefault("target", session_target or active_target)
        step4_work_interruption_cache = dict(result)
        return result

    def _training_artifact_label(target: str) -> str:
        normalized = str(target or "").strip().lower()
        if normalized == "plate":
            return "WYTRENOWANO MODEL TABLIC"
        if normalized == "char":
            return "WYTRENOWANO MODEL ZNAKÓW"
        return "WYTRENOWANO MODEL"

    def _effective_project_model_state(model_type: str) -> dict:
        normalized_type = str(model_type or "").strip().lower()
        if normalized_type not in {"plate", "char"}:
            return {}
        try:
            return dict(
                CAMPAIGN.get_effective_project_model(
                    normalized_type,
                    before_iteration=int(current_iteration or 1),
                    project_name=active_project_name or None,
                )
                or {}
            )
        except Exception:
            return {}

    def _effective_project_model_present(model_type: str) -> bool:
        model_info = _effective_project_model_state(model_type)
        model_path = str(model_info.get("path", "") or "").strip()
        if not model_path:
            return False
        try:
            return bool(Path(model_path).exists())
        except Exception:
            return True

    def _transition_resource_snapshot(resource_key: str) -> CampaignResourceSnapshot | None:
        key = str(resource_key or "").strip()
        if not key:
            return None
        snapshots = {}
        try:
            snapshots = dict(getattr(transition_eval_ctx, "resource_snapshots", {}) or {})
        except Exception:
            snapshots = {}
        candidates = [key]
        if key == "plate_run":
            candidates.append("approved_plates")
        for candidate in candidates:
            snapshot = None
            try:
                snapshot = transition_eval_ctx.resource_snapshot(candidate)
            except Exception:
                snapshot = snapshots.get(candidate)
            if snapshot is None:
                snapshot = snapshots.get(candidate)
            if snapshot is not None:
                return snapshot
        return None

    def _transition_resource_present(resource_key: str) -> bool:
        snapshot = _transition_resource_snapshot(resource_key)
        normalized_key = normalize_campaign_resource_key(resource_key)
        return resource_contract_ready(
            snapshot,
            required=normalized_key in {"plate_run", "char_run", "char_dataset", "training_result"},
        )

    def _project_start_plate_run_contract_snapshot(
        fallback_label: str | None = None,
    ) -> CampaignResourceSnapshot | None:
        try:
            source_info = dict(self._get_project_start_plate_source_info() or {})
        except Exception:
            source_info = {}
        run_path = str(source_info.get("run_path") or "").strip()
        xml_path = str(source_info.get("xml_path") or "").strip()
        images_path = str(source_info.get("images_path") or "").strip()
        source_mode = str(source_info.get("source_mode") or "").strip().lower()
        if not (run_path or xml_path):
            return None

        run_dir = None
        xml_file = None
        try:
            if run_path:
                candidate = Path(run_path)
                if candidate.exists() and candidate.is_dir():
                    run_dir = candidate
                    xml_file = candidate / "annotations.xml"
            if xml_path:
                candidate_xml = Path(xml_path)
                if candidate_xml.exists() and candidate_xml.is_file():
                    xml_file = candidate_xml
                    if run_dir is None:
                        run_dir = candidate_xml.parent
        except Exception:
            run_dir = None
            xml_file = None

        source_raw = xml_path or run_path
        try:
            source_text = self._format_project_start_asset_source(source_raw)
        except Exception:
            source_text = str(source_raw or "").strip() or "Nie wskazano"

        images_count = 0
        plates_count = 0
        if run_dir is not None:
            try:
                annotation_tab = getattr(self.app, "tabs", {}).get("annotation")
                counter = getattr(annotation_tab, "_get_run_plate_annotation_counts", None)
                if callable(counter):
                    images_count, plates_count = counter(run_dir)
            except Exception:
                images_count, plates_count = 0, 0

        try:
            image_source = dict(self._get_project_start_effective_images_source() or {})
        except Exception:
            image_source = {}
        effective_dir = image_source.get("effective_dir")
        effective_exists = bool(image_source.get("effective_exists"))
        try:
            effective_count = int(image_source.get("effective_count", 0) or 0)
        except Exception:
            effective_count = 0

        compatibility = {}
        if run_dir is not None and xml_file is not None and effective_dir is not None and effective_exists:
            try:
                compatibility = dict(
                    self._check_project_start_run_compatibility(
                        run_dir,
                        effective_dir,
                        adoptable_only=True,
                    )
                    or {}
                )
            except Exception:
                compatibility = {}

        try:
            required_min_plates = int(min_plates or getattr(CONFIG, "CAMPAIGN_MIN_PLATE_ANNOTATIONS", 10) or 10)
        except Exception:
            required_min_plates = 10

        checked = bool(compatibility.get("checked"))
        matched_images = int(compatibility.get("matched", images_count) or 0) if checked else int(images_count or 0)
        matched_plates = int(compatibility.get("matched_plate_count", plates_count) or 0) if checked else int(plates_count or 0)
        adoptable_images = int(compatibility.get("adoptable_matched", 0) or 0) if checked else 0
        adoptable_plates = int(compatibility.get("adoptable_matched_plate_count", 0) or 0) if checked else 0
        approved_overlap_images = int(compatibility.get("approved_overlap", 0) or 0) if checked else 0
        approved_overlap_plates = int(compatibility.get("approved_overlap_plates", 0) or 0) if checked else 0
        missing_images = int(compatibility.get("missing", 0) or 0) if checked else 0
        incomplete_images = int(compatibility.get("incomplete", 0) or 0) if checked else 0
        controlled_ready = bool(int(approved_overlap_plates or 0) >= int(required_min_plates or 0))

        if run_dir is None or xml_file is None or not xml_file.exists():
            validation_text = "Nie znaleziono pliku annotations.xml."
            tone = "error"
            contract_ready = False
            requires_rematch = False
        elif effective_dir is None or not effective_exists or effective_count <= 0:
            validation_text = "Najpierw wskaż aktualny zbiór obrazów O."
            tone = "warning"
            contract_ready = False
            requires_rematch = True
        elif checked and int(compatibility.get("total", 0) or 0) <= 0:
            validation_text = "XML nie zawiera anotacji tablic do importu."
            tone = "warning"
            contract_ready = False
            requires_rematch = False
        elif checked and bool(compatibility.get("ok")):
            if source_mode == "approved":
                contract_ready = bool(matched_plates >= required_min_plates)
                tone = "success" if contract_ready else "warning"
                validation_text = (
                    f"AT zatwierdzone i zgodne z O | {matched_images} obrazów / {matched_plates} tablic."
                    if contract_ready
                    else f"AT zgodne z O, ale za mało tablic: {matched_plates}/{required_min_plates}."
                )
            else:
                contract_ready = controlled_ready
                tone = "success" if controlled_ready else "warning"
                validation_text = (
                    f"Kontrola AT spełnia minimum | [OK]: {approved_overlap_images} obrazów / "
                    f"{approved_overlap_plates} tablic."
                    if controlled_ready
                    else (
                        f"AT do kontroli | pasuje {matched_images} obrazów / {matched_plates} tablic. "
                        f"[OK]: {approved_overlap_plates}/{required_min_plates} tablic."
                    )
                )
            requires_rematch = False
        elif checked and matched_images > 0:
            contract_ready = controlled_ready
            tone = "success" if controlled_ready else "warning"
            validation_text = (
                f"Kontrola AT spełnia minimum | [OK]: {approved_overlap_images} obrazów / "
                f"{approved_overlap_plates} tablic. Część importu nadal wymaga dopasowania."
                if controlled_ready
                else (
                    f"Komplet O-AT wymaga kontroli | pasuje {matched_images} obrazów / {matched_plates} tablic, "
                    f"braki: {missing_images + incomplete_images}. [OK]: {approved_overlap_plates}/{required_min_plates} tablic."
                )
            )
            requires_rematch = not controlled_ready
        elif checked:
            validation_text = (
                f"Komplet O-AT nie pasuje do aktualnego zbioru O | brak {missing_images} "
                f"z {int(compatibility.get('total', 0) or 0)} anotowanych obrazów."
            )
            tone = "error"
            contract_ready = False
            requires_rematch = True
        elif source_mode == "approved":
            contract_ready = bool(matched_plates >= required_min_plates)
            tone = "success" if contract_ready else "warning"
            validation_text = (
                f"AT zatwierdzone | {matched_images} obrazów / {matched_plates} tablic."
                if contract_ready
                else f"AT zatwierdzone, ale za mało tablic: {matched_plates}/{required_min_plates}."
            )
            requires_rematch = False
        else:
            validation_text = (
                f"AT do kontroli | {matched_images} obrazów / {matched_plates} tablic. "
                "Sprawdź zgodność z aktualnym zbiorem O."
            )
            tone = "warning"
            contract_ready = False
            requires_rematch = bool(source_mode != "draft")

        return CampaignResourceSnapshot(
            key="plate_run",
            canonical_key="plate_run",
            code="AT",
            label=campaign_resource_label("plate_run", fallback_label or campaign_resource_label("plate_run")),
            requirement="optional",
            source=source_text,
            validation=validation_text,
            tone=tone,
            counter_text=(
                f"{matched_images} obrazów / {matched_plates} tablic"
                if matched_images > 0 or matched_plates > 0
                else ""
            ),
            description=campaign_resource_description("plate_run"),
            meta=build_resource_contract_meta(
                "O->AT",
                contract_ready=bool(contract_ready),
                contract_enforced=True,
                requires_rematch=bool(requires_rematch),
                source_mode=source_mode,
                source_run_path=run_path,
                source_xml_path=xml_path,
                source_input_path=images_path,
                expected_images_dir=str(effective_dir or ""),
                expected_images_count=int(effective_count or 0),
                checked=bool(checked),
                matched_images=int(matched_images or 0),
                matched_plates=int(matched_plates or 0),
                adoptable_images=int(adoptable_images or 0),
                adoptable_plates=int(adoptable_plates or 0),
                approved_overlap_images=int(approved_overlap_images or 0),
                approved_overlap_plates=int(approved_overlap_plates or 0),
                missing_images=int(missing_images or 0),
                incomplete_images=int(incomplete_images or 0),
                min_plates=int(required_min_plates or 0),
                contract_message=validation_text,
                review_required=bool(
                    source_mode != "approved"
                    and not contract_ready
                    and not requires_rematch
                    and (matched_images > 0 or matched_plates > 0)
                ),
                pending_compact_status="AT do kontroli",
                pending_action_text=(
                    "AT jest zaimportowane, ale wymaga kontroli. "
                    "W polu Praca bramki T02 wybierz „Kontroluj import AT w Z2”, "
                    "oznacz poprawne pozycje jako [OK], a potem wróć do T02."
                ),
            ),
        )

    def _t06_exported_char_dataset_state() -> dict:
        missing = {
            "ok": False,
            "reason": "missing_char_dataset",
            "message": (
                f"{CHAR_WORK_GATE_DISPLAY_ID} wymaga realnego eksportu datasetu znaków z PZ3. "
                "Wróć do pracy bramki i wybierz „Przygotuj dataset znaków w Z3”."
            ),
            "ready_dataset": "",
            "dataset_hint": "",
        }
        try:
            contracts = dict((CAMPAIGN.get_iteration_state() or {}).get("t06_contracts") or {})
            pz2_contract = dict(contracts.get("pz2_char_boxes") or {})
            pz3_contract = dict(contracts.get("pz3_char_dataset") or {})
            session = dict((CAMPAIGN.get_iteration_state() or {}).get("t06_work_session") or {})
        except Exception:
            pz2_contract = {}
            pz3_contract = {}
            session = {}
        dataset_raw = str(pz3_contract.get("dataset_path") or "").strip()
        pz3_reason = str(pz3_contract.get("reason") or "").strip().lower()
        try:
            active_project_root = CAMPAIGN.get_active_project_root_dir()
        except Exception:
            active_project_root = None
        try:
            active_project_value = str(CAMPAIGN.get_active_project_name() or active_project_name or "").strip()
        except Exception:
            active_project_value = str(active_project_name or "").strip()
        t06_backfill_reasons = {
            "approve_step3_backfill",
            "graph_backfill_from_pz3_summary",
            "summary_backfill",
            "summary_backfill_after_pz3_session",
            "replace_approve_backfill_with_pz3_export",
        }

        def _is_t06_backfill_reason(reason_value: object) -> bool:
            normalized = str(reason_value or "").strip().lower()
            return bool(
                normalized in t06_backfill_reasons
                or normalized.startswith("graph_backfill")
                or normalized.startswith("summary_backfill")
            )

        def _path_inside_active_project(path_like) -> bool:
            raw = str(path_like or "").strip()
            if not raw or not active_project_root:
                return True
            try:
                Path(raw).resolve().relative_to(Path(active_project_root).resolve())
                return True
            except Exception:
                return False

        def _payload_belongs_to_active_project(payload: dict | None, *paths: object) -> bool:
            if not active_project_value:
                return True
            data = dict(payload or {})
            payload_project = str(data.get("project", "") or "").strip()
            if payload_project and payload_project != active_project_value:
                return False
            path_values = list(paths or [])
            for key in ("dataset_path", "gold_dataset_path", "summary_path", "summary_dir", "_summary_path", "_summary_dir"):
                raw = str(data.get(key) or "").strip()
                if raw:
                    path_values.append(raw)
            for raw in path_values:
                if raw and not _path_inside_active_project(raw):
                    return False
            return True

        def _summary_int(summary: dict, *keys: str) -> int:
            for key in keys:
                try:
                    value = int((summary or {}).get(key, 0) or 0)
                except Exception:
                    value = 0
                if value > 0:
                    return value
            return 0

        def _summary_char_dataset_path(summary: dict | None) -> Path | None:
            data = dict(summary or {})
            if not (bool(data.get("gold_dataset_created")) and bool(data.get("gold_dataset_valid", True))):
                return None
            raw_path = str(
                data.get("gold_dataset_path")
                or data.get("ready_dataset")
                or data.get("dataset_path")
                or ""
            ).strip()
            if not raw_path:
                return None
            try:
                dataset_path = Path(raw_path)
                if not dataset_path.is_absolute():
                    summary_dir = str(data.get("_summary_dir") or "").strip()
                    summary_file = str(data.get("_summary_path") or "").strip()
                    if summary_dir:
                        dataset_path = Path(summary_dir) / dataset_path
                    elif summary_file:
                        dataset_path = Path(summary_file).parent / dataset_path
                if (
                    dataset_path.exists()
                    and dataset_path.is_dir()
                    and self._looks_like_campaign_char_dataset_dir(dataset_path)
                    and _payload_belongs_to_active_project(
                        data,
                        dataset_path,
                        data.get("_summary_path"),
                        data.get("_summary_dir"),
                    )
                ):
                    return dataset_path
            except Exception:
                return None
            return None

        def _positive_int(value) -> int:
            try:
                number = int(value or 0)
            except Exception:
                number = 0
            return number if number > 0 else 0

        def _summary_iteration(summary: dict | None) -> int:
            data = dict(summary or {})
            for field in ("source_iteration", "created_iteration", "produced_iteration", "iteration"):
                number = _positive_int(data.get(field))
                if number > 0:
                    return number
            return 0

        def _path_token(path_like) -> str:
            raw = str(path_like or "").strip()
            if not raw:
                return ""
            try:
                return str(Path(raw).resolve()).casefold()
            except Exception:
                try:
                    return str(Path(raw)).replace("\\", "/").casefold()
                except Exception:
                    return raw.replace("\\", "/").casefold()

        def _contract_path_matches(payload: dict, dataset_path: Path | str | None, summary_path: str | None) -> bool:
            if not isinstance(payload, dict):
                return False
            dataset_token = _path_token(dataset_path)
            summary_token = _path_token(summary_path)
            payload_dataset = _path_token(payload.get("dataset_path") or payload.get("gold_dataset_path"))
            payload_summary = _path_token(payload.get("summary_path"))
            return bool(
                (dataset_token and payload_dataset and dataset_token == payload_dataset)
                or (summary_token and payload_summary and summary_token == payload_summary)
            )

        def _infer_pz3_source_iteration(
            payload: dict | None,
            dataset_path: Path | str | None,
            summary: dict | None = None,
        ) -> int:
            summary_data = dict(summary or {})
            direct = _summary_iteration(summary_data)
            if direct > 0:
                return direct

            summary_path = str(
                summary_data.get("_summary_path")
                or summary_data.get("summary_path")
                or (payload or {}).get("summary_path")
                or ""
            ).strip()
            candidates: list[int] = []
            try:
                registry = CAMPAIGN.load_artifact_registry(active_project_name or None)
            except Exception:
                registry = {}
            for state_key, entry in dict((registry or {}).get("iteration_state") or {}).items():
                if not isinstance(entry, dict):
                    continue
                contract = dict((entry.get("t06_contracts") or {}).get("pz3_char_dataset") or {})
                if not _contract_path_matches(contract, dataset_path, summary_path):
                    continue
                if _is_t06_backfill_reason(contract.get("reason")):
                    found = (
                        _positive_int(contract.get("source_iteration"))
                        or _positive_int(contract.get("created_iteration"))
                        or _positive_int(contract.get("produced_iteration"))
                    )
                    if found <= 0:
                        continue
                else:
                    found = _summary_iteration(contract)
                if found <= 0:
                    found = _positive_int(contract.get("iteration"))
                if found <= 0:
                    found = _positive_int(state_key)
                if found > 0:
                    candidates.append(found)
            if candidates:
                return min(candidates)
            return 0

        def _close_t06_z3_session_from_graph(reason: str) -> None:
            nonlocal session
            try:
                current = dict((CAMPAIGN.get_iteration_state() or {}).get("t06_work_session") or session or {})
            except Exception:
                current = dict(session or {})
            if str(current.get("working_gate_id") or "").strip().upper() not in CHAR_WORK_GATE_SESSION_IDS:
                return
            if str(current.get("work_area") or "").strip().lower() != "z3":
                return
            current_substep = str(current.get("substep") or current.get("target_substep") or "").strip().lower()
            if current_substep in {"2", "detect", "pz2", "z3_pz2"}:
                def _event_time(payload: dict) -> float:
                    for field in ("fulfilled_at", "updated_at", "interrupted_at", "started_at"):
                        raw = str((payload or {}).get(field) or "").strip()
                        if not raw:
                            continue
                        try:
                            return float(datetime.fromisoformat(raw.replace("Z", "+00:00")).timestamp())
                        except Exception:
                            continue
                    return 0.0

                pz3_event_time = _event_time(pz3_contract)
                session_event_time = _event_time(current)
                if pz3_event_time > 0.0 and session_event_time > pz3_event_time + 0.001:
                    return
            current_state = str(current.get("state") or "").strip().lower()
            if (
                not bool(current.get("active"))
                and current_state in {"resolved", "closed", "complete", "completed"}
            ):
                return
            now = datetime.now().isoformat(timespec="seconds")
            previous_interrupted_at = str(current.pop("interrupted_at", "") or "").strip()
            current.update(
                {
                    "active": False,
                    "state": "completed",
                    "working_gate_id": CHAR_WORK_GATE_DISPLAY_ID,
                    "reason": str(reason or "pz3_dataset_ready").strip() or "pz3_dataset_ready",
                    "closed_at": now,
                    "updated_at": now,
                }
            )
            if previous_interrupted_at:
                current.setdefault("resolved_interrupted_at", previous_interrupted_at)
            try:
                CAMPAIGN.upsert_iteration_state(updates={"t06_work_session": current})
                session = dict(current)
            except Exception as exc:
                logger.debug(f"Nie udało się domknąć sesji T06/Z3 po eksporcie PZ3: {exc}")

        def _backfill_pz3_contract_from_character_tab(reason: str) -> dict:
            nonlocal pz3_contract, dataset_raw
            try:
                tabs = getattr(self.app, "tabs", {}) or {}
                char_tab = tabs.get("characters")
            except Exception:
                char_tab = None
            summary_getter = getattr(char_tab, "_read_step3_export_summary", None)
            if not callable(summary_getter):
                return {}
            try:
                summary = dict(summary_getter() or {})
            except Exception:
                summary = {}
            dataset_path = _summary_char_dataset_path(summary)
            if dataset_path is None:
                return {}
            now = datetime.now().isoformat(timespec="seconds")
            source_iteration = _infer_pz3_source_iteration({}, dataset_path, summary)
            try:
                current_iter_for_session = int(CAMPAIGN.get_current_iteration_num() or current_iteration or 1)
            except Exception:
                current_iter_for_session = 1
            if (
                source_iteration <= 0
                or source_iteration != current_iter_for_session
                or not _payload_belongs_to_active_project(
                    summary,
                    dataset_path,
                    summary.get("_summary_path"),
                    summary.get("_summary_dir"),
                )
            ):
                return {}
            contract = {
                "fulfilled": True,
                "project": active_project_value,
                "product": "char_yolo_dataset",
                "source": "PZ3",
                "reason": str(reason or "pz3_export_summary").strip() or "pz3_export_summary",
                "dataset_path": str(dataset_path),
                "exportable_plate_count": _summary_int(summary, "exportable_plate_count", "perfect_count"),
                "exportable_char_count": _summary_int(summary, "exportable_char_count", "char_count"),
                "perfect_count": _summary_int(summary, "perfect_count", "exportable_plate_count"),
                "gold_dataset_valid": True,
                "summary_path": str(summary.get("_summary_path") or ""),
                "summary_dir": str(summary.get("_summary_dir") or ""),
                "iteration": int(source_iteration or 0),
                "source_iteration": int(source_iteration or 0),
                "created_iteration": int(source_iteration or 0),
                "fulfilled_at": now,
                "updated_at": now,
            }
            try:
                CAMPAIGN.upsert_iteration_state(updates={"t06_contracts": {"pz3_char_dataset": contract}})
                pz3_contract = dict(contract)
                dataset_raw = str(dataset_path)
                if source_iteration > 0 and source_iteration == current_iter_for_session:
                    _close_t06_z3_session_from_graph(str(reason or "pz3_dataset_ready"))
                return dict(contract)
            except Exception as exc:
                logger.debug(f"Nie udało się odbudować kontraktu T06/PZ3 z aktywnego podsumowania: {exc}")
            return {}

        if dataset_raw and not _payload_belongs_to_active_project(pz3_contract, dataset_raw):
            foreign = dict(missing)
            foreign.update(
                reason="stale_char_dataset",
                message=(
                    f"Kontrakt PZ3 {CHAR_WORK_GATE_DISPLAY_ID} wskazuje dataset spoza bieżącego projektu. "
                    "Wróć do pracy bramki i utwórz dataset znaków w PZ3 dla aktualnego projektu."
                ),
                ready_dataset=dataset_raw,
                dataset_hint=dataset_raw,
            )
            return foreign

        if pz3_reason == "approve_step3_backfill":
            if _backfill_pz3_contract_from_character_tab("replace_approve_backfill_with_pz3_export"):
                pz3_reason = str(pz3_contract.get("reason") or "").strip().lower()
            else:
                invalid_source = dict(missing)
                invalid_source.update(
                    reason="stale_char_dataset",
                    message=(
                        "Wpis PZ3 powstał podczas próby zatwierdzenia, a nie podczas realnego eksportu datasetu. "
                        "Wróć do pracy bramki i utwórz dataset znaków w PZ3."
                    ),
                    ready_dataset=dataset_raw,
                    dataset_hint=dataset_raw,
                )
                return invalid_source
        if not (bool(pz3_contract.get("fulfilled")) and dataset_raw):
            session_state_raw = str(session.get("state") or "").strip().lower()
            session_gate_raw = str(session.get("working_gate_id") or "").strip().upper()
            session_substep_raw = str(session.get("substep") or session.get("target_substep") or "").strip().lower()
            session_targets_pz3_raw = session_substep_raw in {"3", "dataset", "pz3", "z3_pz3"}
            session_active_raw = bool(session.get("active")) or session_state_raw in {"active", "started", "interrupted", "dirty"}
            can_backfill_after_pz3_session = bool(
                session_gate_raw in CHAR_WORK_GATE_SESSION_IDS
                and session_targets_pz3_raw
                and session_active_raw
                and session_state_raw not in {"resolved", "closed", "complete", "completed"}
            )
            if can_backfill_after_pz3_session and _backfill_pz3_contract_from_character_tab("summary_backfill_after_pz3_session"):
                pz3_reason = str(pz3_contract.get("reason") or "").strip().lower()
            else:
                return dict(missing)

        def _contract_time(payload: dict) -> float:
            for field in ("fulfilled_at", "updated_at", "interrupted_at", "started_at"):
                raw = str((payload or {}).get(field) or "").strip()
                if not raw:
                    continue
                try:
                    return float(datetime.fromisoformat(raw.replace("Z", "+00:00")).timestamp())
                except Exception:
                    continue
            return 0.0

        pz3_time = _contract_time(pz3_contract)
        pz2_time = _contract_time(pz2_contract)
        session_time = _contract_time(session)
        session_state = str(session.get("state") or "").strip().lower()
        session_gate = str(session.get("working_gate_id") or "").strip().upper()
        session_substep = str(session.get("substep") or session.get("target_substep") or "").strip().lower()
        session_targets_pz2 = session_substep in {"2", "detect", "pz2", "z3_pz2"}
        session_targets_pz3 = session_substep in {"3", "dataset", "pz3", "z3_pz3"}
        session_active = bool(session.get("active")) or session_state in {"active", "started", "interrupted", "dirty"}

        def _contract_int(payload: dict, key: str) -> int:
            try:
                return int((payload or {}).get(key, 0) or 0)
            except Exception:
                return 0

        def _contract_iteration(payload: dict) -> int:
            if not isinstance(payload, dict):
                return 0
            for field in ("source_iteration", "created_iteration", "produced_iteration", "fulfilled_iteration", "iteration"):
                try:
                    iteration_num = int(payload.get(field, 0) or 0)
                except Exception:
                    iteration_num = 0
                if iteration_num > 0:
                    return iteration_num
            return 0

        pz2_reason = str(pz2_contract.get("reason") or "").strip().lower()
        pz2_marker_only = pz2_reason in {"enter_pz3", "return_ready_to_graph", "dataset_exported"}
        pz2_same_export_scope = bool(
            _contract_int(pz2_contract, "exportable_plate_count") <= _contract_int(pz3_contract, "exportable_plate_count")
            and _contract_int(pz2_contract, "exportable_char_count") <= _contract_int(pz3_contract, "exportable_char_count")
        )
        stale_after_pz2 = bool(
            pz2_time
            and pz3_time
            and pz2_time > pz3_time + 0.001
            and not (session_gate in CHAR_WORK_GATE_SESSION_IDS and session_active and session_targets_pz2)
            and not pz2_marker_only
        )
        stale_after_session = bool(
            session_gate in CHAR_WORK_GATE_SESSION_IDS
            and session_active
            and session_state not in {"resolved", "closed", "complete", "completed"}
            and not session_targets_pz2
            and session_targets_pz3
            and (not pz3_time or not session_time or session_time > pz3_time + 0.001)
        )
        if stale_after_pz2 or stale_after_session:
            if stale_after_session and not stale_after_pz2:
                if _backfill_pz3_contract_from_character_tab("graph_resolve_interrupted_pz3_export"):
                    pz3_time = _contract_time(pz3_contract)
                    session_time = _contract_time(session)
                    session_state = str(session.get("state") or "").strip().lower()
                    session_gate = str(session.get("working_gate_id") or "").strip().upper()
                    session_substep = str(session.get("substep") or session.get("target_substep") or "").strip().lower()
                    session_targets_pz2 = session_substep in {"2", "detect", "pz2", "z3_pz2"}
                    session_targets_pz3 = session_substep in {"3", "dataset", "pz3", "z3_pz3"}
                    session_active = bool(session.get("active")) or session_state in {"active", "started", "interrupted", "dirty"}
                    stale_after_session = bool(
                        session_gate in CHAR_WORK_GATE_SESSION_IDS
                        and session_active
                        and session_state not in {"resolved", "closed", "complete", "completed"}
                        and not session_targets_pz2
                        and session_targets_pz3
                        and (not pz3_time or not session_time or session_time > pz3_time + 0.001)
                    )
                    if not stale_after_session:
                        stale_after_pz2 = False
            if stale_after_pz2 or stale_after_session:
                stale = dict(missing)
                stale.update(
                    reason="stale_char_dataset",
                    message=(
                        f"Eksport datasetu znaków nie obejmuje najnowszej pracy {CHAR_WORK_GATE_DISPLAY_ID}. "
                        "Wróć do pracy bramki i ponownie utwórz dataset znaków w PZ3."
                    ),
                    ready_dataset=dataset_raw,
                    dataset_hint=dataset_raw,
                )
                return stale
        try:
            dataset_path = Path(dataset_raw)
            looks_valid = bool(
                dataset_path.exists()
                and dataset_path.is_dir()
                and self._looks_like_campaign_char_dataset_dir(dataset_path)
            )
        except Exception:
            looks_valid = False
        if not looks_valid:
            invalid = dict(missing)
            invalid.update(
                reason="invalid_char_dataset",
                message=(
                    f"Kontrakt PZ3 {CHAR_WORK_GATE_DISPLAY_ID} wskazuje dataset, ale katalog nie wygląda jak poprawny dataset znaków. "
                    "Wróć do pracy bramki i ponownie wykonaj eksport w PZ3."
                ),
                ready_dataset=dataset_raw,
                dataset_hint=dataset_raw,
            )
            return invalid
        try:
            current_iter_for_origin = int(CAMPAIGN.get_current_iteration_num() or current_iteration or 1)
        except Exception:
            current_iter_for_origin = 1
        inferred_pz3_iteration = _infer_pz3_source_iteration(pz3_contract, dataset_path)
        if inferred_pz3_iteration <= 0 and not _is_t06_backfill_reason(pz3_reason):
            inferred_pz3_iteration = _contract_iteration(pz3_contract)
        pz3_iteration = inferred_pz3_iteration
        pz2_iteration = _contract_iteration(pz2_contract) or pz3_iteration
        if int(pz3_iteration or 0) == int(current_iter_for_origin or 0):
            _close_t06_z3_session_from_graph("pz3_dataset_ready")
        return {
            "ok": True,
            "reason": "source_dataset_ready_for_split",
            "message": "",
            "ready_dataset": str(dataset_path),
            "dataset_hint": str(dataset_path),
            "source_iteration": int(pz3_iteration or 0),
            "current_iteration": int(current_iter_for_origin or 0),
            "pz2_iteration": int(pz2_iteration or 0),
            "pz3_iteration": int(pz3_iteration or 0),
            "exportable_plate_count": int(pz3_contract.get("exportable_plate_count", 0) or 0),
            "exportable_char_count": int(pz3_contract.get("exportable_char_count", 0) or 0),
            "perfect_count": int(
                pz2_contract.get(
                    "perfect_count",
                    pz3_contract.get("perfect_count", pz3_contract.get("exportable_plate_count", 0)),
                )
                or 0
            ),
            "validation_message": f"Kontrakt PZ3 {CHAR_WORK_GATE_DISPLAY_ID} potwierdza wyeksportowany dataset znaków.",
        }

    def _extract_iteration_number_from_text(*texts: object) -> int:
        for text in texts:
            value = str(text or "").strip()
            if not value:
                continue
            for pattern in (r"\bIT\s*0*(\d{1,4})\b", r"Iteracja[_\s-]*0*(\d{1,4})"):
                try:
                    match = re.search(pattern, value, flags=re.IGNORECASE)
                except Exception:
                    match = None
                if match:
                    try:
                        iteration_num = int(match.group(1) or 0)
                    except Exception:
                        iteration_num = 0
                    if iteration_num > 0:
                        return iteration_num
        return 0

    def _artifact_iteration_from_mapping(payload: object) -> int:
        if not isinstance(payload, dict):
            return 0
        for field in (
            "artifact_iteration",
            "created_iteration",
            "produced_iteration",
            "trained_iteration",
            "first_approved_iteration",
            "approved_iteration",
            "source_iteration",
            "iteration",
        ):
            try:
                iteration_num = int(payload.get(field, 0) or 0)
            except Exception:
                iteration_num = 0
            if iteration_num > 0:
                return iteration_num
        return _extract_iteration_number_from_text(
            payload.get("source", ""),
            payload.get("validation", ""),
            payload.get("display_name", ""),
            payload.get("run_name", ""),
        )

    def _latest_iteration(iterations: list[int]) -> int:
        clean = []
        for value in list(iterations or []):
            try:
                iteration_num = int(value or 0)
            except Exception:
                iteration_num = 0
            if iteration_num > 0:
                clean.append(iteration_num)
        if not clean:
            return 0
        try:
            current_iter = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            current_iter = 1
        eligible = [value for value in clean if value <= max(1, current_iter)]
        return max(eligible or clean)

    def _plate_run_artifact_iteration() -> int:
        try:
            pending_t05 = _step2_unpromoted_t05_state()
        except Exception:
            pending_t05 = {}
        try:
            pending_images = int(pending_t05.get("unpromoted_approved_images", 0) or 0)
            pending_plates = int(pending_t05.get("unpromoted_approved_plates", 0) or 0)
        except Exception:
            pending_images, pending_plates = 0, 0
        if pending_images > 0 or pending_plates > 0:
            try:
                return int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
            except Exception:
                return 1

        try:
            start_source = dict(CAMPAIGN.get_project_start_plate_source(active_project_name or None) or {})
        except Exception:
            start_source = {}
        try:
            start_source_iteration = int(start_source.get("source_iteration", 0) or 0)
        except Exception:
            start_source_iteration = 0
        if start_source_iteration > 0 and _transition_resource_present("plate_run"):
            return start_source_iteration

        iterations: list[int] = []
        try:
            entries = list(CAMPAIGN.list_plate_approved_entries(active_project_name or None) or [])
        except Exception:
            entries = []
        for entry in entries:
            iteration_num = _artifact_iteration_from_mapping(entry)
            if iteration_num > 0:
                iterations.append(iteration_num)
        latest = _latest_iteration(iterations)
        if latest > 0:
            return latest

        snapshot = _transition_resource_snapshot("plate_run") or _transition_resource_snapshot("approved_plates")
        if snapshot is not None:
            return _extract_iteration_number_from_text(snapshot.source, snapshot.validation)
        return 0

    def _char_run_artifact_iteration() -> int:
        snapshot = _transition_resource_snapshot("char_run")
        if snapshot is not None:
            parsed = _extract_iteration_number_from_text(snapshot.source, snapshot.validation)
            if parsed > 0:
                return parsed

        iterations: list[int] = []
        try:
            registry = CAMPAIGN.load_artifact_registry(active_project_name or None)
        except Exception:
            registry = {}
        if isinstance(registry, dict):
            for state_key, entry in dict(registry.get("iteration_state") or {}).items():
                if not isinstance(entry, dict):
                    continue
                try:
                    state_iteration = int(entry.get("iteration", state_key) or state_key or 0)
                except Exception:
                    state_iteration = 0
                for payload_key in ("char_run", "char_annotations", "char_source"):
                    payload = entry.get(payload_key)
                    iteration_num = _artifact_iteration_from_mapping(payload)
                    if iteration_num <= 0 and payload:
                        iteration_num = state_iteration
                    if iteration_num > 0:
                        iterations.append(iteration_num)
            for package in dict(registry.get("packages") or {}).values():
                if not isinstance(package, dict):
                    continue
                for payload_key in ("char_run", "char_annotations", "char_source"):
                    iteration_num = _artifact_iteration_from_mapping(package.get(payload_key))
                    if iteration_num > 0:
                        iterations.append(iteration_num)
        return _latest_iteration(iterations)

    def _image_resource_origin_iteration() -> int:
        try:
            current_iter = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            current_iter = 1
        try:
            selected_iter = int(CAMPAIGN.get_master_pool_selected_iteration(active_project_name or None) or 0)
        except Exception:
            selected_iter = 0
        if selected_iter == current_iter:
            try:
                master_pool = CAMPAIGN.get_master_pool_dir(active_project_name or None)
            except Exception:
                master_pool = None
            try:
                image_source = dict(self._get_project_start_effective_images_source() or {})
            except Exception:
                image_source = {}
            effective_dir = image_source.get("effective_dir")
            if master_pool is not None and effective_dir is not None:
                try:
                    if Path(master_pool).resolve() == Path(effective_dir).resolve():
                        return max(1, current_iter)
                except Exception:
                    if str(master_pool or "").strip().lower() == str(effective_dir or "").strip().lower():
                        return max(1, current_iter)
        try:
            current_manifest = dict(CAMPAIGN.load_ingest_manifest(current_iter, active_project_name or None) or {})
        except Exception:
            current_manifest = {}
        current_token = str(current_manifest.get("image_set_token", "") or "").strip()
        if not current_token:
            try:
                current_token = str(CAMPAIGN.get_iteration_image_set_token(current_iter, active_project_name or None) or "").strip()
            except Exception:
                current_token = ""
        if current_token:
            for iteration_num in range(1, max(1, current_iter) + 1):
                try:
                    manifest = dict(CAMPAIGN.load_ingest_manifest(iteration_num, active_project_name or None) or {})
                except Exception:
                    manifest = {}
                token = str(manifest.get("image_set_token", "") or "").strip()
                if token and token == current_token:
                    return int(iteration_num)
        try:
            current_source = CAMPAIGN.get_iteration_image_source_dir(current_iter, active_project_name or None)
        except Exception:
            current_source = None
        if current_source is not None:
            try:
                current_source_resolved = Path(current_source).resolve()
            except Exception:
                current_source_resolved = Path(str(current_source))
            for iteration_num in range(1, max(1, current_iter) + 1):
                try:
                    source = CAMPAIGN.get_iteration_image_source_dir(iteration_num, active_project_name or None)
                except Exception:
                    source = None
                if source is None:
                    continue
                try:
                    if Path(source).resolve() == current_source_resolved:
                        return int(iteration_num)
                except Exception:
                    if str(source).strip().lower() == str(current_source).strip().lower():
                        return int(iteration_num)
        return max(1, current_iter)

    def _resource_iteration_number(resource_key: str) -> int:
        key = str(resource_key or "").strip()
        try:
            current_iter = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            current_iter = 1
        if key == "images":
            origin_iteration = _image_resource_origin_iteration()
            if origin_iteration > 0:
                return origin_iteration
            snapshot = _transition_resource_snapshot("images")
            if snapshot is not None:
                parsed = _extract_iteration_number_from_text(snapshot.source, snapshot.validation)
                if parsed > 0:
                    return parsed
            return max(1, current_iter)
        if key == "plate_model":
            model_info = _effective_project_model_state("plate")
            for field in ("trained_iteration", "source_iteration", "iteration"):
                try:
                    iteration_num = int(model_info.get(field, 0) or 0)
                except Exception:
                    iteration_num = 0
                if iteration_num > 0:
                    return iteration_num
            return _extract_iteration_number_from_text(model_info.get("source", ""), model_info.get("scope", ""))
        if key == "char_model":
            model_info = _effective_project_model_state("char")
            for field in ("trained_iteration", "source_iteration", "iteration"):
                try:
                    iteration_num = int(model_info.get(field, 0) or 0)
                except Exception:
                    iteration_num = 0
                if iteration_num > 0:
                    return iteration_num
            return _extract_iteration_number_from_text(model_info.get("source", ""), model_info.get("scope", ""))
        if key == "plate_run":
            return _plate_run_artifact_iteration()
        if key == "char_run":
            return _char_run_artifact_iteration()
        if key == "char_dataset":
            snapshot = _transition_resource_snapshot("char_dataset")
            if snapshot is not None:
                meta = resource_snapshot_meta(snapshot)
                for field in ("source_iteration", "pz3_iteration", "iteration"):
                    try:
                        iteration_num = int(meta.get(field, 0) or 0)
                    except Exception:
                        iteration_num = 0
                    if iteration_num > 0:
                        return iteration_num
                parsed = _extract_iteration_number_from_text(snapshot.source, snapshot.validation)
                if parsed > 0:
                    return parsed
                try:
                    if str(snapshot.tone or "").strip().lower() == "success":
                        return max(1, current_iter)
                except Exception:
                    pass
        return 0

    def _resource_marker(code: str, resource_key: str) -> str:
        iteration_num = _resource_iteration_number(resource_key)
        if iteration_num > 0:
            return f"{code}(IT{iteration_num})"
        return code

    _step2_unpromoted_t05_cache: dict | None = None

    def _step2_unpromoted_t05_state() -> dict:
        nonlocal _step2_unpromoted_t05_cache
        if _step2_unpromoted_t05_cache is not None:
            return dict(_step2_unpromoted_t05_cache)
        _step2_unpromoted_t05_cache = {}
        try:
            if int(current_step or 0) != 2 or str(current_target or "").strip().lower() != "plate":
                return {}
        except Exception:
            return {}
        try:
            plate_ready_source = dict(self._get_plate_route_ready_source() or {})
        except Exception:
            plate_ready_source = {}
        extra_run_dirs = []
        try:
            iteration_state = dict(CAMPAIGN.get_iteration_state() or {})
            session = dict(iteration_state.get("t05_work_session") or {})
            session_state = str(session.get("state") or "").strip().lower()
            session_result = dict(session.get("last_return_result") or {})
            session_resolved = bool(session_result.get("ok")) or session_state in {
                "resolved",
                "closed",
                "complete",
                "completed",
            }
            if session_resolved:
                try:
                    now = datetime.now().isoformat(timespec="seconds")
                    CAMPAIGN.upsert_iteration_state(
                        updates={
                            "t05_work_session": {
                                **session,
                                "active": False,
                                "state": "resolved",
                                "resolved_at": str(session.get("resolved_at") or now),
                                "updated_at": now,
                                "last_return_result": session_result,
                            }
                        }
                    )
                except Exception:
                    pass
                session_active = False
                session = {}
            else:
                session_active = bool(session.get("active")) or session_state in {"active", "started", "interrupted", "dirty"}
            session_run = str(session.get("run_dir", "") or "").strip()
            if session_active and session_run and session_state not in {"resolved", "closed", "complete", "completed"}:
                extra_run_dirs.append(session_run)
        except Exception:
            session = {}
        try:
            fallback = dict(
                self._get_step2_disk_approval_fallback(
                    iteration_target="plate",
                    plate_ready_source=plate_ready_source,
                    extra_run_dirs=extra_run_dirs,
                )
                or {}
            )
        except Exception:
            fallback = {}
        fallback_interrupted = bool(fallback.get("interrupted_work"))
        if fallback_interrupted:
            try:
                images = int(fallback.get("unpromoted_approved_images", 0) or 0)
                plates = int(fallback.get("unpromoted_approved_plates", 0) or 0)
            except Exception:
                images, plates = 0, 0
        else:
            images, plates = 0, 0
        if images <= 0 and plates <= 0:
            try:
                project_names = {
                    CAMPAIGN._normalize_image_set_name(entry.get("image_name", ""))
                    for entry in list(CAMPAIGN.list_plate_approved_entries() or [])
                    if isinstance(entry, dict) and CAMPAIGN._normalize_image_set_name(entry.get("image_name", ""))
                }
            except Exception:
                project_names = set()

            def _recent_project_run_dirs(limit: int = 12) -> list[Path]:
                roots = []
                for getter_name in ("get_step2_staging_run",):
                    try:
                        candidate = getattr(CAMPAIGN, getter_name)()
                        if candidate:
                            roots.append(Path(candidate).parent)
                    except Exception:
                        pass
                for dir_key in ("auto_ann",):
                    for getter_name in ("get_staging_dir", "get_dir"):
                        try:
                            candidate = getattr(CAMPAIGN, getter_name)(dir_key)
                            if candidate:
                                roots.append(Path(candidate))
                        except Exception:
                            pass
                run_dirs: list[Path] = []
                seen_paths: set[str] = set()
                for root in roots:
                    try:
                        if not root.exists() or not root.is_dir():
                            continue
                        children = [
                            child
                            for child in root.iterdir()
                            if child.is_dir() and (child / "annotations.xml").exists()
                        ]
                    except Exception:
                        continue
                    try:
                        children.sort(key=lambda path: path.stat().st_mtime, reverse=True)
                    except Exception:
                        children.sort(key=lambda path: path.name, reverse=True)
                    for child in children[:limit]:
                        try:
                            key = str(child.resolve()).lower()
                        except Exception:
                            key = str(child).lower()
                        if key in seen_paths:
                            continue
                        seen_paths.add(key)
                        run_dirs.append(child)
                        if len(run_dirs) >= limit:
                            return run_dirs
                return run_dirs

            for candidate_run in _recent_project_run_dirs():
                try:
                    manifest = CAMPAIGN._load_annotation_run_manifest_file(candidate_run)
                    approved_names = {
                        CAMPAIGN._normalize_image_set_name(name)
                        for name in list(manifest.get("approved_filenames") or [])
                        if CAMPAIGN._normalize_image_set_name(name)
                    }
                except Exception:
                    approved_names = set()
                unpromoted_names = set(approved_names or set()) - set(project_names or set())
                if not unpromoted_names:
                    continue
                try:
                    pending_counts = dict(
                        CAMPAIGN._load_run_plate_counts_by_image(
                            candidate_run,
                            image_names=set(unpromoted_names),
                        )
                        or {}
                    )
                except Exception:
                    pending_counts = {}
                pending_images = sum(1 for value in pending_counts.values() if int(value or 0) > 0)
                pending_plates = sum(max(0, int(value or 0)) for value in pending_counts.values())
                if pending_images <= 0 and pending_plates <= 0:
                    continue
                fallback = {
                    "ready": True,
                    "iteration_target": "plate",
                    "action": "approve_stage",
                    "run_dir": candidate_run,
                    "run_approved_images": int(pending_images),
                    "run_approved_plates": int(pending_plates),
                    "unpromoted_approved_images": int(pending_images),
                    "unpromoted_approved_plates": int(pending_plates),
                    "unpromoted_approved_names": sorted(set(unpromoted_names)),
                    "interrupted_work": True,
                    "t05_work_session": dict(session or {}),
                }
                try:
                    now = datetime.now().isoformat(timespec="seconds")
                    session_payload = {
                        "active": True,
                        "state": "interrupted",
                        "source_gate_id": "T04",
                        "working_gate_id": "T04",
                        "edge_key": "e2_to_e4",
                        "run_dir": str(candidate_run.resolve()),
                        "approved_images": int(pending_images),
                        "approved_plates": int(pending_plates),
                        "interrupted_at": now,
                        "updated_at": now,
                    }
                    CAMPAIGN.upsert_iteration_state(updates={"t05_work_session": session_payload})
                    fallback["t05_work_session"] = dict(session_payload)
                except Exception:
                    pass
                _step2_unpromoted_t05_cache = dict(fallback)
                return dict(_step2_unpromoted_t05_cache)
            if not fallback_interrupted:
                return {}
        try:
            fallback["t05_work_session"] = dict(session or {})
        except Exception:
            pass
        _step2_unpromoted_t05_cache = dict(fallback)
        return dict(_step2_unpromoted_t05_cache)

    _t06_interrupted_work_cache: dict | None = None
    _t06_interrupted_work_cache_key = None

    def _t06_interrupted_work_state() -> dict:
        nonlocal _t06_interrupted_work_cache, _t06_interrupted_work_cache_key
        latest_state = dict(CAMPAIGN.get_iteration_state() or {})
        cache_key = json.dumps([latest_state.get("t06_work_session"), latest_state.get("t06_contracts")],
                               sort_keys=True, default=str)
        if _t06_interrupted_work_cache is not None and cache_key == _t06_interrupted_work_cache_key:
            return dict(_t06_interrupted_work_cache)
        _t06_interrupted_work_cache_key = cache_key
        _t06_interrupted_work_cache = {}
        non_interrupted_z3_states = {
            "resolved",
            "closed",
            "complete",
            "completed",
            "abandoned",
            "ready_for_pz2",
            "waiting_for_pz2",
            "ready_for_pz3",
            "waiting_for_pz3",
        }
        context_is_char_step = False
        try:
            context_is_char_step = bool(
                int(current_step or 0) == 3
                and str(current_target or "").strip().lower() == "char"
            )
        except Exception:
            context_is_char_step = False

        session = {}
        session_state = ""
        session_active = False
        session_work_area = ""
        session_gate_id = ""
        extra_run_dirs = []
        try:
            iteration_state = dict(CAMPAIGN.get_iteration_state() or {})
            session = dict(iteration_state.get("t06_work_session") or {})
            session_state = str(session.get("state") or "").strip().lower()
            session_active = bool(session.get("active")) or session_state in {"active", "started", "interrupted", "dirty"}
            session_work_area = str(session.get("work_area") or "").strip().lower()
            session_gate_id = str(session.get("working_gate_id") or "").strip().upper()
            session_run = str(session.get("run_dir", "") or "").strip()
            if session_active and session_run and session_state not in {"resolved", "closed", "complete", "completed"}:
                extra_run_dirs.append(session_run)
        except Exception:
            session = {}

        session_touched_t05_z3 = bool(
            session_gate_id in CHAR_WORK_GATE_SESSION_IDS
            and session_work_area == "z3"
            and session_state not in non_interrupted_z3_states
        )
        if (session_gate_id in CHAR_WORK_GATE_SESSION_IDS and session_work_area == "z3"
                and session_state in {"ready_for_pz2", "waiting_for_pz2", "ready_for_pz3", "waiting_for_pz3"}
                and not session_active):
            return {}
        session_substep_hint = str(session.get("substep") or session.get("target_substep") or "").strip().lower()
        session_targets_pz2_hint = session_substep_hint in {"2", "detect", "pz2", "z3_pz2"}
        session_reason_hint = str(session.get("reason") or "").strip().lower()
        if (
            session_gate_id in CHAR_WORK_GATE_SESSION_IDS
            and session_work_area == "z3"
            and session_targets_pz2_hint
            and session_state in {"resolved", "closed", "complete", "completed"}
            and session_reason_hint in {"pz3_dataset_ready", "pz3_summary_ready"}
        ):
            now = datetime.now().isoformat(timespec="seconds")
            session["active"] = True
            session["state"] = "interrupted"
            session["reason"] = "pz2_closed_after_ready_export"
            session["updated_at"] = now
            session.setdefault("interrupted_at", now)
            try:
                CAMPAIGN.upsert_iteration_state(updates={"t06_work_session": session})
            except Exception as exc:
                logger.debug(f"Nie udało się przywrócić przerwanej sesji T05/PZ2: {exc}")
            session_state = "interrupted"
            session_active = True
            session_touched_t05_z3 = True
        if not context_is_char_step and not session_touched_t05_z3:
            return {}

        missing_z3_export_interrupted = False
        try:
            iteration_state = dict(CAMPAIGN.get_iteration_state() or {})
            contracts = dict(iteration_state.get("t06_contracts") or {})
            pz2_contract = dict(contracts.get("pz2_char_boxes") or {})
            try:
                legacy_pz2_done = bool(CAMPAIGN.is_step3_stage2_done())
            except Exception:
                legacy_pz2_done = False
            pz2_contract_ready = bool(pz2_contract.get("fulfilled") or legacy_pz2_done)
            pz3_contract = dict(contracts.get("pz3_char_dataset") or {})
            exported_gate = _t06_exported_char_dataset_state()
            ready_dataset = str(exported_gate.get("ready_dataset") or exported_gate.get("dataset_hint") or "").strip()
            pz3_export_ready = bool(exported_gate.get("ok") and ready_dataset)
            try:
                exported_gate_iteration = int(
                    exported_gate.get("source_iteration")
                    or exported_gate.get("pz3_iteration")
                    or exported_gate.get("iteration")
                    or 0
                )
            except Exception:
                exported_gate_iteration = 0
            try:
                current_iter_for_session = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
            except Exception:
                current_iter_for_session = 1
            pz3_export_ready_current = bool(
                pz3_export_ready
                and exported_gate_iteration > 0
                and exported_gate_iteration == current_iter_for_session
            )
            session_substep = str(session.get("substep") or session.get("target_substep") or "").strip().lower()
            session_targets_pz2 = session_substep in {"2", "detect", "pz2", "z3_pz2"}
            session_targets_pz3 = session_substep in {"3", "dataset", "pz3", "z3_pz3"}
            controlled_pz2_return = bool(
                session_gate_id in CHAR_WORK_GATE_SESSION_IDS
                and session_work_area == "z3"
                and session_targets_pz2
                and session_state in {"paused", "ready_for_pz3", "waiting_for_pz3"}
                and str(session.get("reason") or "").strip().lower()
                in {"return_to_graph_pz2_ready", "return_to_graph_pz2_pending"}
            )
            if (
                pz3_export_ready_current
                and session_gate_id in CHAR_WORK_GATE_SESSION_IDS
                and session_work_area == "z3"
                and session_targets_pz3
                and session_state not in {"resolved", "closed", "complete", "completed"}
            ):
                now = datetime.now().isoformat(timespec="seconds")
                previous_interrupted_at = str(session.pop("interrupted_at", "") or "").strip()
                session["active"] = False
                session["state"] = "completed"
                session["working_gate_id"] = CHAR_WORK_GATE_DISPLAY_ID
                session["reason"] = "pz3_dataset_ready"
                session["closed_at"] = now
                session["updated_at"] = now
                if previous_interrupted_at:
                    session.setdefault("resolved_interrupted_at", previous_interrupted_at)
                try:
                    CAMPAIGN.upsert_iteration_state(updates={"t06_work_session": session})
                except Exception as exc:
                    logger.debug(f"Nie udało się zapisać domknięcia sesji T06/Z3 w grafie: {exc}")
                session_active = False
                session_state = "completed"
            if pz3_export_ready_current:
                if (
                    session_active
                    and session_gate_id in CHAR_WORK_GATE_SESSION_IDS
                    and session_work_area == "z3"
                    and session_targets_pz2
                    and session_state not in {"resolved", "closed", "complete", "completed"}
                ):
                    def _event_time(payload: dict) -> float:
                        for field in ("fulfilled_at", "updated_at", "interrupted_at", "started_at"):
                            raw = str((payload or {}).get(field) or "").strip()
                            if not raw:
                                continue
                            try:
                                return float(datetime.fromisoformat(raw.replace("Z", "+00:00")).timestamp())
                            except Exception:
                                continue
                        return 0.0

                    pz3_time = _event_time(pz3_contract)
                    session_time = _event_time(session)
                    if pz3_time > 0.0 and (session_time <= 0.0 or session_time <= pz3_time + 0.001):
                        now = datetime.now().isoformat(timespec="seconds")
                        previous_interrupted_at = str(session.pop("interrupted_at", "") or "").strip()
                        session.update(
                            {
                                "active": False,
                                "state": "completed",
                                "working_gate_id": CHAR_WORK_GATE_DISPLAY_ID,
                                "reason": "pz3_dataset_ready",
                                "closed_at": now,
                                "updated_at": now,
                            }
                        )
                        if previous_interrupted_at:
                            session.setdefault("resolved_interrupted_at", previous_interrupted_at)
                        try:
                            CAMPAIGN.upsert_iteration_state(updates={"t06_work_session": session})
                            CAMPAIGN.invalidate_step3_char_source_state_cache()
                            CAMPAIGN.clear_project_iteration_ui_snapshots()
                        except Exception as exc:
                            logger.debug(f"Nie udaĹ‚o siÄ™ domknÄ…Ä‡ sesji T05/PZ2 po eksporcie PZ3: {exc}")
                        _t06_interrupted_work_cache = {}
                        return {}
                    _t06_interrupted_work_cache = {
                        "interrupted_work": True,
                        "interrupted_kind": "z3",
                        "work_area": "z3",
                        "substep": "pz2",
                        "valid_export_exists": True,
                        "ready_dataset": ready_dataset,
                        "dataset_hint": ready_dataset,
                        "source_iteration": int(exported_gate_iteration or 0),
                        "pz3_iteration": int(exported_gate_iteration or 0),
                        "current_iteration": int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1),
                        "t06_work_session": dict(session or {}),
                        "unpromoted_approved_images": 0,
                        "unpromoted_approved_plates": 0,
                        "interrupted_title": "Niedokończona korekta PZ2",
                        "interrupted_detail": (
                            "Gotowy eksport AZ nadal obowiązuje. Niedokończona korekta PZ2 jest szkicem roboczym: "
                            "możesz ją kontynuować albo zatwierdzić bramkę na podstawie ostatniego eksportu."
                        ),
                    }
                    return dict(_t06_interrupted_work_cache)
                _t06_interrupted_work_cache = {}
                return {}
            z3_session_touched = bool(
                session_gate_id in CHAR_WORK_GATE_SESSION_IDS
                and (
                    session_work_area == "z3"
                    or str(session.get("substep") or "").strip() in {"2", "3", "pz2", "pz3"}
                )
                and session_state not in non_interrupted_z3_states
            )
            missing_z3_export_interrupted = bool(
                not pz3_export_ready_current
                and not controlled_pz2_return
                and z3_session_touched
            )
        except Exception:
            missing_z3_export_interrupted = False

        try:
            char_ready_source = dict(self._get_char_route_ready_source() or {})
        except Exception:
            char_ready_source = {}
        try:
            fallback = dict(
                self._get_step2_disk_approval_fallback(
                    iteration_target="char",
                    char_ready_source=char_ready_source,
                    extra_run_dirs=extra_run_dirs,
                )
                or {}
            )
        except Exception:
            fallback = {}

        interrupted = bool(fallback.get("interrupted_work")) or bool(session.get("active")) or bool(missing_z3_export_interrupted)
        if not interrupted:
            return {}
        session_is_interrupted_z3 = bool(
            (
                session_active
                and session_gate_id in CHAR_WORK_GATE_SESSION_IDS
                and session_work_area == "z3"
                and session_state not in {"resolved", "closed", "complete", "completed", "paused"}
            )
            or missing_z3_export_interrupted
        )
        try:
            fallback_images = int(fallback.get("unpromoted_approved_images", 0) or 0)
            fallback_plates = int(fallback.get("unpromoted_approved_plates", 0) or 0)
        except Exception:
            fallback_images, fallback_plates = 0, 0
        try:
            session_images = 0 if session_is_interrupted_z3 else int(session.get("approved_images", 0) or 0)
            session_plates = 0 if session_is_interrupted_z3 else int(session.get("approved_plates", 0) or 0)
        except Exception:
            session_images, session_plates = 0, 0
        images = int(fallback_images or session_images or 0)
        plates = int(fallback_plates or session_plates or 0)
        if images <= 0 and plates <= 0 and not session_is_interrupted_z3:
            return {}
        fallback["t06_work_session"] = dict(session or {})
        fallback["unpromoted_approved_images"] = int(images or 0)
        fallback["unpromoted_approved_plates"] = int(plates or 0)
        if session_is_interrupted_z3:
            fallback["interrupted_work"] = True
            fallback["interrupted_kind"] = "z3"
            fallback["work_area"] = "z3"
            fallback["interrupted_title"] = "Przerwana praca w Z3"
            if missing_z3_export_interrupted:
                fallback["interrupted_title"] = "Brak eksportu datasetu znaków"
                fallback["interrupted_detail"] = (
                    "Ramki znaków zostały rozpoczęte lub rozliczone, ale nie ma gotowego eksportu AZ z PZ3."
                )
        _t06_interrupted_work_cache = dict(fallback)
        return dict(_t06_interrupted_work_cache)

    def _current_iteration_marker(code: str) -> str:
        try:
            iteration_num = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            iteration_num = 1
        return f"{code}(IT{max(1, iteration_num)})"

    def _approve_label_with_markers(*markers: str) -> str:
        clean_markers = [str(marker or "").strip() for marker in markers if str(marker or "").strip()]
        if clean_markers:
            return "ZATWIERDŹ\n" + "  ".join(clean_markers)
        return "ZATWIERDŹ"

    def _training_result_marker(target: str, finish_state: dict | None = None) -> str:
        normalized = str(target or "").strip().lower()
        code = "MODEL TABLIC" if normalized == "plate" else ("MODEL ZNAKÓW" if normalized == "char" else "MODEL")
        state = dict(finish_state or {})
        for field in ("iteration", "source_iteration", "trained_iteration"):
            try:
                iteration_num = int(state.get(field, 0) or 0)
            except Exception:
                iteration_num = 0
            if iteration_num > 0:
                return f"{code}(IT{iteration_num})"
        try:
            current_iter = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            current_iter = 1
        return f"{code}(IT{max(1, current_iter)})"

    def _no_training_decision_markers() -> list[str]:
        try:
            decision_iter = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            decision_iter = 1
        markers = [f"BEZ TRENINGU(IT{max(1, decision_iter)})"]
        target = str(current_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
        if target in {"plate", "char"}:
            model_info = _effective_project_model_state(target)
            try:
                model_iteration = int(model_info.get("iteration", 0) or 0)
            except Exception:
                model_iteration = 0
            if model_iteration > 0:
                model_code = "MT" if target == "plate" else "MZ"
                markers.append(f"{model_code}(IT{model_iteration})")
        return markers

    def _no_training_decision_summary() -> str:
        markers = _no_training_decision_markers()
        return " / ".join(markers) if markers else "BEZ TRENINGU"

    def _entry_gate_approve_label(edge_key: str) -> str:
        key = str(edge_key or "").strip()
        if key == "e1_to_e2":
            parts = [_resource_marker("O", "images")]
            normalized_path = normalize_iteration_path(selected_path)
            if _effective_project_model_present("plate"):
                parts.append(_resource_marker("MT", "plate_model"))
            if normalized_path == "char_from_images" and _effective_project_model_present("char"):
                parts.append(_resource_marker("MZ", "char_model"))
            if _transition_resource_present("plate_run"):
                parts.append(_resource_marker("AT", "plate_run"))
            if normalized_path == "char_from_images" and _transition_resource_present("char_run"):
                parts.append(_resource_marker("AZ", "char_run"))
            return _approve_label_with_markers(*parts)
        if key == "e1_to_e3":
            parts = [_resource_marker("AT", "plate_run")]
            if _effective_project_model_present("char"):
                parts.append(_resource_marker("MZ", "char_model"))
            if _transition_resource_present("char_run"):
                parts.append(_resource_marker("AZ", "char_run"))
            return _approve_label_with_markers(*parts)
        return _approve_label_with_markers("ZASOBY")

    def _edge_approve_label(edge) -> str:
        if not _edge_approve_enabled(edge):
            return "ZATWIERDŹ"
        key = str(getattr(edge, "key", "") or "").strip()
        if _is_t07_graph_edge(key):
            finish_state = _current_t07_training_finish_state()
            if finish_state:
                return _approve_label_with_markers(
                    _training_result_marker(str(finish_state.get("target", "") or current_target), finish_state)
                )
            if _current_step4_without_training_decision_ready():
                return _approve_label_with_markers(*_no_training_decision_markers())
            return "ZATWIERDŹ"
        if key == "e3_to_e4":
            return _approve_label_with_markers(_resource_marker("DATASET ZNAKÓW", "char_dataset"))
        if key == "e2_to_e3":
            return _approve_label_with_markers(_current_iteration_marker("AT"))
        if key == "e2_to_e4":
            pending_t05 = _step2_unpromoted_t05_state()
            if pending_t05:
                try:
                    pending_images = int(pending_t05.get("unpromoted_approved_images", 0) or 0)
                except Exception:
                    pending_images = 0
                if pending_images > 0:
                    return _approve_label_with_markers(_current_iteration_marker("AT"), f"+{pending_images} OK")
            return _approve_label_with_markers(_current_iteration_marker("AT"))
        if key == "e1_to_e3":
            return _entry_gate_approve_label(key)
        if key.startswith("e1_to_e2"):
            return _entry_gate_approve_label(key)
        if key.startswith("e1_to_"):
            return _entry_gate_approve_label(key)
        return "ZATWIERDŹ"

    def _build_transition_resource_snapshots() -> dict[str, object]:
        rows = getattr(self, "ingest_start_asset_row_widgets", {}) or {}
        snapshots: dict[str, object] = {}
        if isinstance(rows, dict):
            for row_key in ordered_campaign_resource_keys():
                row = rows.get(row_key)
                if row is None and row_key != "char_run":
                    continue
                snapshot = build_campaign_resource_snapshot(
                    row_key,
                    row if isinstance(row, dict) else None,
                    fallback_label=campaign_resource_label(row_key),
                    fallback_requirement="optional",
                    fallback_validation=(
                        "Opcjonalne | import anotacji znaków jest zasobem planowanym."
                        if row_key == "char_run" and row is None
                        else "Brak"
                    ),
                )
                snapshots[snapshot.canonical_key] = snapshot
        active_images_snapshot = _active_master_pool_image_snapshot()
        if active_images_snapshot is not None:
            snapshots[active_images_snapshot.canonical_key] = active_images_snapshot

        def _store_snapshot(snapshot: CampaignResourceSnapshot, *, prefer_success: bool = False) -> None:
            existing = snapshots.get(snapshot.canonical_key)
            if existing is None:
                snapshots[snapshot.canonical_key] = snapshot
                return
            try:
                existing_has_value = bool(existing.has_source or int(existing.counter_value or 0) > 0)
            except Exception:
                existing_has_value = False
            if prefer_success and snapshot.tone == "success":
                snapshots[snapshot.canonical_key] = snapshot
            elif not existing_has_value:
                snapshots[snapshot.canonical_key] = snapshot

        def _store_effective_project_model_snapshot(model_type: str) -> None:
            normalized_type = str(model_type or "").strip().lower()
            if normalized_type not in {"plate", "char"}:
                return
            try:
                model_info = dict(
                    CAMPAIGN.get_effective_project_model(
                        normalized_type,
                        before_iteration=int(current_iteration or 1),
                        project_name=active_project_name or None,
                    )
                    or {}
                )
            except Exception:
                model_info = {}
            model_path = str(model_info.get("path", "") or "").strip()
            if not model_path:
                return
            try:
                model_name = Path(model_path).name
            except Exception:
                model_name = model_path
            resource_key = "plate_model" if normalized_type == "plate" else "char_model"
            source_scope = str(model_info.get("scope", "") or "").strip()
            try:
                source_iteration = int(model_info.get("iteration", 0) or 0)
            except Exception:
                source_iteration = 0
            if source_scope == "trained_previous_iteration" and source_iteration > 0:
                source_text = f"Model wytrenowany w IT{source_iteration}: {model_name}"
            else:
                source_text = f"Model projektu: {model_name}"

            metric_parts: list[str] = []
            for metric_key, metric_label in (("best_map50", "mAP50"), ("best_map50_95", "mAP50-95")):
                raw_value = model_info.get(metric_key)
                if raw_value in (None, ""):
                    continue
                try:
                    metric_parts.append(f"{metric_label}: {float(raw_value) * 100:.1f}%")
                except Exception:
                    metric_parts.append(f"{metric_label}: {raw_value}")
            if metric_parts:
                validation_text = "Gotowy zasób projektu. " + " | ".join(metric_parts) + "."
            else:
                validation_text = "Gotowy zasób projektu."

            _store_snapshot(
                CampaignResourceSnapshot(
                    key=resource_key,
                    canonical_key=resource_key,
                    code=campaign_resource_short_label(resource_key, resource_key.upper()),
                    label=campaign_resource_label(resource_key),
                    requirement="optional",
                    source=source_text,
                    validation=validation_text,
                    tone="success",
                    description=campaign_resource_description(resource_key),
                    meta={
                        "contract_kind": "model",
                        "contract_ready": True,
                        "model_type": normalized_type,
                        "model_path": str(model_path or ""),
                        "model_iteration": int(source_iteration or 0),
                    },
                ),
                prefer_success=True,
            )

        _store_effective_project_model_snapshot("plate")
        _store_effective_project_model_snapshot("char")

        e2_approved = bool(str(stage_status.get("E2", "") or "").strip().lower() == "approved" or current_step > 2)
        plate_material_counter = max(int(plate_count or 0), 0)
        plate_material_present = bool(e2_approved or material_ready or plate_material_counter > 0)
        if plate_material_present:
            if e2_approved:
                plate_validation = "Gotowe: E2 zatwierdzone."
                plate_tone = "success"
            elif material_ready:
                plate_validation = f"Gotowe tablice spełniają minimum: {plate_material_counter}/{min_plates}."
                plate_tone = "success"
            else:
                plate_validation = f"Dostępne anotacje tablic: {plate_material_counter}/{min_plates}."
                plate_tone = "warning"
            _store_snapshot(
                CampaignResourceSnapshot(
                    key="approved_plates",
                    canonical_key="plate_run",
                    code="AT",
                    label=campaign_resource_label("approved_plates"),
                    requirement="required",
                    source="Pula anotacji tablic projektu",
                    validation=plate_validation,
                    tone=plate_tone,
                    counter_text=str(plate_material_counter) if plate_material_counter > 0 else "",
                    meta={
                        "contract_kind": "AT",
                        "contract_ready": bool(plate_tone == "success" and plate_material_counter >= int(min_plates or 10)),
                        "approved_plates": int(plate_material_counter or 0),
                        "min_plates": int(min_plates or 10),
                    },
                ),
                prefer_success=True,
            )

        project_start_plate_snapshot = _project_start_plate_run_contract_snapshot()
        if project_start_plate_snapshot is not None:
            snapshots[project_start_plate_snapshot.canonical_key] = project_start_plate_snapshot

        try:
            approved_stats = dict(CAMPAIGN.get_plate_approved_set_stats(active_project_name or None) or {})
        except Exception:
            approved_stats = {}
        try:
            approved_entries = list(CAMPAIGN.list_plate_approved_entries(active_project_name or None) or [])
        except Exception:
            approved_entries = []
        project_approved_image_names = {
            str(entry.get("image_name", "") or "").strip().lower()
            for entry in approved_entries
            if isinstance(entry, dict) and str(entry.get("image_name", "") or "").strip()
        }
        try:
            project_approved_images = int(approved_stats.get("images", 0) or 0)
        except Exception:
            project_approved_images = 0
        try:
            project_approved_plates = int(approved_stats.get("plates", 0) or 0)
        except Exception:
            project_approved_plates = 0
        run_approved_images, run_approved_plates, run_approved_name = _collect_active_step2_run_approved_delta(
            project_approved_image_names
        )
        pending_t05_state = {}
        try:
            if int(current_step or 0) == 2 and str(current_target or "").strip().lower() == "plate":
                pending_t05_state = _step2_unpromoted_t05_state()
        except Exception:
            pending_t05_state = {}
        if pending_t05_state:
            try:
                pending_t05_images = int(pending_t05_state.get("unpromoted_approved_images", 0) or 0)
                pending_t05_plates = int(pending_t05_state.get("unpromoted_approved_plates", 0) or 0)
            except Exception:
                pending_t05_images, pending_t05_plates = 0, 0
            if pending_t05_images > 0 or pending_t05_plates > 0:
                run_approved_images = max(int(run_approved_images or 0), pending_t05_images)
                run_approved_plates = max(int(run_approved_plates or 0), pending_t05_plates)
                try:
                    run_approved_name = (
                        _campaign_run_display_id({"run_dir": pending_t05_state.get("run_dir", "")}, kind_hint="annotation")
                        or run_approved_name
                    )
                except Exception:
                    run_approved_name = run_approved_name or "przerwana praca T05"
        approved_images = int(project_approved_images or 0) + int(run_approved_images or 0)
        approved_plates = int(project_approved_plates or 0) + int(run_approved_plates or 0)
        try:
            approved_min_plates = int(getattr(CONFIG, "CAMPAIGN_MIN_PLATE_ANNOTATIONS", 10) or 10)
        except Exception:
            approved_min_plates = 10
        approved_missing = max(0, int(approved_min_plates) - int(approved_plates))
        approved_ready = bool(approved_plates >= approved_min_plates)
        approved_source_parts = []
        if project_approved_images > 0 or project_approved_plates > 0:
            approved_source_parts.append(
                f"ApprovedSet projektu: {project_approved_images} zdjęć / {project_approved_plates} tablic"
            )
        if run_approved_images > 0 or run_approved_plates > 0:
            display_run_name = _campaign_run_display_id({"run_name": run_approved_name}, kind_hint="annotation") if run_approved_name else ""
            run_label = f" ({display_run_name or run_approved_name})" if run_approved_name else ""
            approved_source_parts.append(
                f"bieżący run Z2{run_label}: {run_approved_images} zdjęć / {run_approved_plates} tablic"
            )
        approved_validation = (
            f"Gotowe: {approved_images} zdjęć [OK] / {approved_plates} tablic [OK]."
            if approved_ready
            else (
                f"Brakuje {approved_missing} tablic [OK]. "
                f"Teraz: {approved_images} zdjęć [OK] / {approved_plates} tablic [OK]."
            )
        )
        snapshots["approved_plates"] = CampaignResourceSnapshot(
            key="approved_plates",
            canonical_key="approved_plates",
            code="AT",
            label=campaign_resource_label("approved_plates"),
            requirement="required",
            source=(" + ".join(approved_source_parts) if approved_source_parts else "Nie wskazano"),
            validation=approved_validation,
            tone=("success" if approved_ready else "warning"),
            counter_text=str(approved_plates) if approved_plates > 0 else "",
            description="Anotacje tablic zatwierdzone statusem [OK].",
            meta={
                "contract_kind": "AT",
                "contract_ready": bool(approved_ready),
                "approved_images": int(approved_images or 0),
                "approved_plates": int(approved_plates or 0),
                "min_plates": int(min_plates or 10),
            },
        )

        try:
            char_gate = dict(_t06_exported_char_dataset_state() or {})
        except Exception:
            char_gate = {}
        char_source, char_validation, char_tone, char_counter = _format_char_dataset_resource_status(char_gate)
        try:
            char_source_iteration = int(char_gate.get("source_iteration", char_gate.get("iteration", 0)) or 0)
        except Exception:
            char_source_iteration = 0
        try:
            char_current_iteration = int(char_gate.get("current_iteration", current_iteration or 0) or 0)
        except Exception:
            try:
                char_current_iteration = int(current_iteration or 0)
            except Exception:
                char_current_iteration = 0
        try:
            char_pz2_iteration = int(char_gate.get("pz2_iteration", 0) or 0)
        except Exception:
            char_pz2_iteration = 0
        try:
            char_pz3_iteration = int(char_gate.get("pz3_iteration", 0) or 0)
        except Exception:
            char_pz3_iteration = 0
        snapshots["char_dataset"] = CampaignResourceSnapshot(
            key="char_dataset",
            canonical_key="char_dataset",
            code="DZ",
            label=campaign_resource_label("char_dataset"),
            requirement="required",
            source=char_source,
            validation=char_validation,
            tone=char_tone,
            counter_text=char_counter,
            meta={
                "contract_kind": "AT->AZ",
                "contract_ready": bool(str(char_tone or "").strip().lower() == "success"),
                "dataset_state": dict(char_gate or {}),
                "source_iteration": int(char_source_iteration or 0),
                "current_iteration": int(char_current_iteration or 0),
                "pz2_iteration": int(char_pz2_iteration or 0),
                "pz3_iteration": int(char_pz3_iteration or 0),
                "origin_scope": (
                    "current"
                    if int(char_source_iteration or 0) > 0
                    and int(char_source_iteration or 0) == int(char_current_iteration or 0)
                    else "previous"
                ),
            },
        )

        training_ready = bool(_current_t07_training_finish_ready())
        training_candidate = _current_t07_training_candidate_state()
        no_training_ready = bool(_current_step4_without_training_decision_ready())
        step4_display_gate_id = "T06"
        if training_ready:
            training_source = "Wynik treningu"
            training_validation = (
                f"Wynik treningu jest dostępny. Użyj pola Zatwierdź na bramce {step4_display_gate_id}."
            )
            training_tone = "success"
        elif no_training_ready:
            training_source = f"Decyzja bez treningu: {_no_training_decision_summary()}"
            training_validation = (
                f"Zamkniesz tę iterację bez nowego treningu; model projektu pozostaje bez zmian. "
                f"Użyj pola Zatwierdź na bramce {step4_display_gate_id}."
            )
            training_tone = "success"
        elif training_candidate:
            candidate_target = str(training_candidate.get("target", "") or current_target).strip().lower()
            candidate_label = "model tablic" if candidate_target == "plate" else "model znaków" if candidate_target == "char" else "model"
            candidate_model_id = _campaign_model_display_id(training_candidate, target_hint=candidate_target or current_target)
            candidate_weights = str(training_candidate.get("best_weights", "") or "").strip()
            candidate_name = Path(candidate_weights).name if candidate_weights else "best.pt"
            training_source = f"Model do wyboru: {candidate_model_id or candidate_name}"
            training_validation = (
                f"Wynik treningu istnieje ({candidate_label}: {candidate_name}), ale nie został jeszcze wybrany "
                "jako wynik bramki. Wejdź w Praca -> Trenuj model i wybierz model projektu."
            )
            training_tone = "warning"
        else:
            training_source = "Nie wskazano"
            training_validation = (
                f"Użyj pola Praca na bramce {step4_display_gate_id}, aby rozpocząć trening albo świadomie "
                "zakończyć iterację bez treningu."
            )
            training_tone = "warning"
        _store_snapshot(
            CampaignResourceSnapshot(
                key="training_result",
                canonical_key="training_result",
                code="TR",
                label=campaign_resource_label("training_result"),
                requirement="required",
                source=training_source,
                validation=training_validation,
                tone=training_tone,
                meta={
                    "contract_kind": "training_result",
                    "contract_ready": bool(str(training_tone or "").strip().lower() == "success"),
                    "has_training_candidate": bool(training_candidate),
                    "no_training_ready": bool(no_training_ready),
                },
            ),
            prefer_success=True,
        )
        return snapshots

    transition_eval_ctx = CampaignTransitionEvalContext(
        selected_path=selected_path,
        explicit_selected_path=explicit_selected_path,
        current_step=current_step,
        current_iteration=current_iteration,
        stage_status=stage_status,
        image_count=image_count,
        min_images=min_images,
        plate_material_count=plate_count,
        min_plates=min_plates,
        material_ready=material_ready,
        image_potential=image_potential,
        resource_snapshots=_build_transition_resource_snapshots(),
    )
    try:
        graph_history_entries = list(CAMPAIGN.load_project_history(limit=300) or [])
    except Exception:
        graph_history_entries = []

    def _latest_history_entry_for_stage(stage_key: str) -> dict:
        normalized_stage = str(stage_key or "").strip().upper()
        stage_target_filter = ""
        if normalized_stage == "E4T":
            stage_target_filter = "plate"
        elif normalized_stage == "E4Z":
            stage_target_filter = "char"
        if stage_target_filter and str(current_target or "").strip().lower() not in {"", stage_target_filter}:
            return {}
        try:
            stage_num = _stage_num(normalized_stage)
        except Exception:
            stage_num = 0
        if stage_num <= 0:
            return {}
        for entry in reversed(graph_history_entries):
            if not isinstance(entry, dict):
                continue
            try:
                if int(entry.get("iteration", 0) or 0) != int(current_iteration or 1):
                    continue
            except Exception:
                continue
            try:
                if int(entry.get("step", 0) or 0) != stage_num:
                    continue
            except Exception:
                continue
            if stage_target_filter:
                details = entry.get("details") if isinstance(entry.get("details"), dict) else {}
                entry_target = str(details.get("target") or "").strip().lower()
                if entry_target not in {"plate", "char"}:
                    entry_target = iteration_path_target(str(details.get("path") or "").strip())
                if entry_target not in {"plate", "char"}:
                    entry_target = str(current_target or "").strip().lower()
                if entry_target != stage_target_filter:
                    continue
            return dict(entry)
        return {}

    def _stage_in_selected_path(stage_key: str) -> bool:
        normalized = str(stage_key or "").strip().upper()
        if not normalized:
            return False
        path_key = str(selected_path or "").strip()
        if not path_key:
            try:
                return int(current_step or 0) == _stage_num(normalized)
            except Exception:
                return normalized == "E1"
        for edge in CAMPAIGN_TRANSITION_GRAPH.edges:
            try:
                if path_key not in tuple(getattr(edge, "paths", ()) or ()):
                    continue
                if normalized in {str(edge.source or "").strip().upper(), str(edge.target or "").strip().upper()}:
                    return True
            except Exception:
                continue
        return normalized == "E1"

    def _stage_reached_in_current_iteration(stage_key: str) -> bool:
        normalized = str(stage_key or "").strip().upper()
        try:
            stage_num = _stage_num(normalized)
        except Exception:
            stage_num = 0
        if stage_num <= 0:
            return False
        if not _stage_in_selected_path(normalized):
            return False
        try:
            current_step_num = int(current_step or 0)
        except Exception:
            current_step_num = 0
        if current_step_num >= stage_num:
            return True
        if _stage_status_value(normalized) == "approved":
            return True
        return bool(_latest_history_entry_for_stage(normalized))

    def _stage_resource_effect(stage_key: str) -> str:
        normalized = str(stage_key or "").strip().upper()
        try:
            if normalized == "E1":
                image_snapshot = transition_eval_ctx.resource_snapshot("images")
                image_total = int(getattr(image_snapshot, "counter_value", 0) or image_count or 0)
                if image_total > 0:
                    return f"{image_total} obrazów"
                return "Wybierz zasoby"
            if normalized == "E2":
                approved_snapshot = transition_eval_ctx.resource_snapshot("approved_plates")
                approved_total = int(getattr(approved_snapshot, "counter_value", 0) or 0)
                if approved_total > 0:
                    return f"{approved_total} [OK]"
                return "Brak [OK]"
            if normalized == "E3":
                char_snapshot = transition_eval_ctx.resource_snapshot("char_dataset")
                char_tone = str(getattr(char_snapshot, "tone", "") or "").strip().lower()
                char_total = int(getattr(char_snapshot, "counter_value", 0) or 0)
                if char_tone == "success":
                    return "Dataset znaków gotowy"
                if char_total > 0:
                    return f"Znaki: {char_total}"
                return "Dataset znaków: brak"
            if normalized.startswith("E4"):
                training_snapshot = transition_eval_ctx.resource_snapshot("training_result")
                training_tone = str(getattr(training_snapshot, "tone", "") or "").strip().lower()
                training_source = str(getattr(training_snapshot, "source", "") or "").strip().lower()
                if training_tone == "success":
                    if "bez treningu" in training_source:
                        return "Decyzja bez treningu"
                    return "Wynik treningu gotowy"
                if training_tone == "warning" and getattr(training_snapshot, "has_source", False):
                    return "Wynik treningu do wyboru"
                return "Trening: brak wyniku"
        except Exception:
            pass
        return ""

    def _stage_effect_summary(stage_key: str) -> str:
        resource_effect = _stage_resource_effect(stage_key)
        latest = _latest_history_entry_for_stage(stage_key)
        prefix = "H | " if latest else ""
        return shorten(f"{prefix}{resource_effect or 'Brak historii'}", width=30, placeholder="...")

    def _visible_badge_id(badge_id: str | None) -> str:
        return campaign_visible_gate_id(badge_id)

    def _stage_history_event_label(stage_key: str) -> str:
        latest = _latest_history_entry_for_stage(stage_key)
        if not latest:
            return "Brak wpisów historii dla tego etapu w bieżącej iteracji."
        action = str(latest.get("action") or "").strip()
        title = str(latest.get("title") or "").strip()
        gate = _visible_badge_id(latest.get("gate_id") or latest.get("transition_id"))
        action_labels = {
            "set_iteration_path": "Wybrano ścieżkę iteracji.",
            "approve_step1": "Zatwierdzono wejście i wybraną ścieżkę.",
            "approve_step1_ready_plates": "Zatwierdzono skrót: pominięto oznaczanie tablic w Z2.",
            "approve_step2": "Zatwierdzono pulę tablic dla dalszej pracy.",
            "approve_step3": "Zatwierdzono materiał znaków dla treningu.",
            "prepare_step4_without_training": "Wybrano świadome zakończenie iteracji bez treningu.",
            "approve_step4": "Zamknięto iterację po pracy treningowej.",
            "approve_step4_without_training": "Zamknięto iterację bez treningu.",
            "open_z2_campaign_context": "Otwierano kartę pracy Z2.",
            "open_z2_step3_repair": "Otwierano Z2 do uzupełnienia anotacji tablic.",
            "continue_z3": "Otwierano kartę pracy Z3.",
            "open_z4": "Otwierano kartę treningu Z4.",
            "open_z4_dataset": "Otwierano tworzenie wariantu datasetu.",
        }
        label = action_labels.get(action) or title or action or "Zapisano zdarzenie grafu."
        return f"{gate}: {label}" if gate else label

    def _active_gate_label() -> str:
        edge = CAMPAIGN_TRANSITION_GRAPH.get_edge(selected_edge_key)
        spec = _edge_spec(edge) if edge is not None else None
        gate_id = _visible_badge_id(getattr(spec, "badge_id", ""))
        gate_label = str(getattr(spec, "badge_label", "") or "").strip()
        if gate_id and gate_label:
            return f"{gate_id} ({gate_label})"
        if gate_id:
            return gate_id
        return "aktywna bramka grafu"

    def _stage_modal_summary(stage_key: str) -> dict:
        normalized = str(stage_key or "").strip().upper()
        stage_num = _stage_num(normalized)
        if current_step == stage_num:
            state_text = "Bieżący etap."
        elif current_step > stage_num or _stage_status_value(normalized) == "approved":
            state_text = "Etap zamknięty w tej iteracji."
        else:
            state_text = "Etap jeszcze przed Tobą."

        active_gate = _active_gate_label()
        stage_titles = {
            "E1": "Karta etapu E1 | Wejście iteracji",
            "E2": "Karta etapu E2 | Tablice",
            "E3": "Karta etapu E3 | Znaki",
            "E4T": "Karta etapu E4T | Trening modelu tablic",
            "E4Z": "Karta etapu E4Z | Trening modelu znaków",
            "E4": "Karta treningu | E4T/E4Z",
        }
        path_labels = {
            "plate_training": "kompletowanie anotacji tablic",
            "char_from_images": "przygotowanie tablic pod znaki",
            "char_from_ready_plates": "przejście do znaków z istniejących tablic",
        }

        def _snapshot(key: str):
            try:
                return transition_eval_ctx.resource_snapshot(key)
            except Exception:
                return None

        def _counter(key: str, fallback: int = 0) -> int:
            snap = _snapshot(key)
            try:
                return int(getattr(snap, "counter_value", 0) or fallback or 0)
            except Exception:
                return int(fallback or 0)

        def _snapshot_text(key: str, attr: str, fallback: str = "") -> str:
            snap = _snapshot(key)
            try:
                return str(getattr(snap, attr, "") or fallback or "").strip()
            except Exception:
                return str(fallback or "").strip()

        def _source_or_default(key: str, fallback: str = "Nie wskazano źródła.") -> str:
            text = _snapshot_text(key, "source", fallback)
            return text if text and text.lower() not in {"nie wskazano", "brak", "-"} else fallback

        def _validation_or_default(key: str, fallback: str = "Brak walidacji.") -> str:
            text = _snapshot_text(key, "validation", fallback)
            return text if text and text.lower() not in {"brak", "-"} else fallback

        def _stage_edge_choices(stage_key_for_edges: str) -> str:
            labels: list[str] = []
            for graph_edge in CAMPAIGN_TRANSITION_GRAPH.edges:
                if str(getattr(graph_edge, "source", "") or "").strip().upper() != str(stage_key_for_edges or "").strip().upper():
                    continue
                spec = _edge_spec(graph_edge)
                gate_id = _visible_badge_id(getattr(spec, "badge_id", ""))
                gate_label = str(getattr(spec, "badge_label", "") or "").strip()
                if gate_id and gate_label:
                    labels.append(f"{gate_id} ({gate_label})")
                elif gate_id:
                    labels.append(gate_id)
            return ", ".join(labels) if labels else "bramki wychodzące z tego etapu"

        image_total = _counter("images", image_count)
        approved_total = _counter("approved_plates", 0)
        char_total = _counter("char_dataset", 0)
        selected_path_label = path_labels.get(selected_path, "nie wybrano ścieżki")
        last_event = _stage_history_event_label(normalized)

        if normalized == "E1":
            if image_total > 0:
                produced = f"Wybrano wejście iteracji: {image_total} obrazów dla ścieżki {selected_path_label}."
                scale = f"{image_total} obrazów w puli wejściowej tej iteracji."
            elif selected_path == "char_from_ready_plates" and approved_total > 0:
                produced = f"Wybrano skrót przez istniejące AT: {approved_total} anotacji tablic [OK]."
                scale = f"{approved_total} tablic opisanych anotacjami AT jako źródło dla E3."
            else:
                produced = "Nie wybrano jeszcze kompletnego wejścia iteracji."
                scale = "Brakuje zasobu wejściowego wymaganego przez wybraną ścieżkę."
            rows = [
                ("Wyprodukowano", produced),
                ("Skala", scale),
                ("Źródło", _source_or_default("images", "Źródło obrazów nie jest jeszcze wskazane.")),
                ("Co odblokowuje", "Poprawne wejście pozwala zamknąć T01 albo T03 i przejść do właściwej karty Z2 lub Z3."),
                ("Następny ruch", (
                    f"Wybierz krawędź wychodzącą z E1: {_stage_edge_choices('E1')}. "
                    f"Teraz aktywna jest {active_gate}; jej Zasoby, Praca i Zatwierdź dotyczą tylko tej ścieżki."
                    if current_step == 1
                    else "E1 jest już kontekstem iteracji; kolejne decyzje podejmuj na bieżącej bramce."
                )),
                ("Ostatnia praca", last_event),
            ]
        elif normalized == "E2":
            produced = (
                f"Przygotowano zatwierdzoną pulę tablic: {approved_total} tablic [OK]."
                if approved_total > 0
                else "Nie ma jeszcze zatwierdzonej puli tablic [OK]."
            )
            rows = [
                ("Wyprodukowano", produced),
                ("Skala", _validation_or_default("approved_plates", f"{approved_total} tablic [OK].")),
                ("Źródło", _source_or_default("approved_plates", "Pula tablic nie ma jeszcze źródła.")),
                ("Co odblokowuje", "Tablice [OK] są paliwem dla treningu modelu tablic albo dla wyodrębniania znaków w torze znaków."),
                ("Następny ruch", (
                    f"Wybierz krawędź wychodzącą z E2: {_stage_edge_choices('E2')}. "
                    f"Teraz aktywna jest {active_gate}; jej Zasoby, Praca i Zatwierdź dotyczą tylko tej ścieżki."
                    if current_step == 2
                    else "Jeśli tablice wymagają korekty, wróć do Z2 przez akcję naprawczą aktywnej bramki."
                )),
                ("Ostatnia praca", last_event),
            ]
        elif normalized == "E3":
            char_tone = _snapshot_text("char_dataset", "tone", "").lower()
            if char_tone == "success":
                produced = "Utworzono dataset znaków gotowy do treningu."
            elif char_total > 0:
                produced = f"Zebrano materiał znaków: {char_total} pozycji, ale dataset wymaga jeszcze domknięcia."
            else:
                produced = "Dataset znaków nie jest jeszcze gotowy."
            rows = [
                ("Wyprodukowano", produced),
                ("Skala", _validation_or_default("char_dataset", "Brak gotowego datasetu znaków.")),
                ("Źródło", _source_or_default("char_dataset", "Źródło datasetu znaków nie jest jeszcze wskazane.")),
                ("Co odblokowuje", f"Gotowy dataset znaków otwiera przejście {CHAR_WORK_GATE_DISPLAY_ID} do E4Z i trening modelu znaków."),
                ("Następny ruch", (
                    f"Wybierz krawędź wychodzącą z E3: {_stage_edge_choices('E3')}. "
                    f"Teraz aktywna jest {active_gate}; jej Zasoby, Praca i Zatwierdź dotyczą tylko tej ścieżki."
                    if current_step == 3
                    else "Jeśli dataset znaków jest gotowy, przejdź do E4Z i decyzji treningowej."
                )),
                ("Ostatnia praca", last_event),
            ]
        elif normalized.startswith("E4"):
            training_tone = _snapshot_text("training_result", "tone", "").lower()
            training_source = _source_or_default("training_result", "Wynik treningu nie jest jeszcze wskazany.")
            if normalized == "E4T":
                training_kind = "modelu tablic"
                stage_label = "E4T"
            elif normalized == "E4Z":
                training_kind = "modelu znaków"
                stage_label = "E4Z"
            else:
                training_kind = "modelu"
                stage_label = "E4T/E4Z"
            if training_tone == "success":
                if "bez treningu" in training_source.lower():
                    produced = "Zapisano świadomą decyzję zakończenia iteracji bez treningu."
                else:
                    produced = f"Uzyskano wynik treningu {training_kind} dla bieżącej iteracji."
            elif training_tone == "warning" and _transition_resource_present("training_result"):
                produced = (
                    f"Ukończono trening {training_kind}, ale wynik nie został jeszcze wybrany do zamknięcia bramki."
                )
            else:
                produced = f"Nie ma jeszcze wyniku treningu {training_kind} ani decyzji zamknięcia iteracji."
            rows = [
                ("Wyprodukowano", produced),
                ("Skala", _validation_or_default("training_result", f"Brak gotowego wyniku {stage_label}.")),
                ("Źródło", training_source),
                ("Co odblokowuje", f"Wynik treningu albo decyzja bez treningu pozwala zamknąć {CHAR_WORK_GATE_DISPLAY_ID} i rozpocząć kolejną iterację."),
                ("Następny ruch", (
                    f"Wybierz krawędź wychodzącą z {stage_label}: {_stage_edge_choices(normalized)}. "
                    f"Teraz aktywna jest {active_gate}; jej Zasoby, Praca i Zatwierdź dotyczą tylko tej ścieżki."
                    if current_step == 4
                    else f"{stage_label} będzie potrzebne dopiero po zamknięciu wcześniejszych etapów."
                )),
                ("Ostatnia praca", last_event),
            ]
        else:
            rows = [
                ("Wyprodukowano", "Brak podsumowania dla tego etapu."),
                ("Skala", state_text),
                ("Następny ruch", "Wróć do aktywnej bramki grafu."),
            ]

        return {
            "title": stage_titles.get(normalized, f"Karta etapu {normalized or '-'}"),
            "rows": rows,
            "current_effect": f"{state_text} {_stage_resource_effect(normalized) or ''}".strip(),
            "last_effect": _stage_history_event_label(normalized),
            "meaning": rows[3][1] if len(rows) > 3 else "Ten etap jest częścią przepływu kampanii.",
            "next_action": rows[4][1] if len(rows) > 4 else "Wróć do aktywnej bramki grafu.",
        }

    def _edge_spec(edge):
        specs = get_transition_specs_for_edge(getattr(edge, "key", ""))
        return specs[0] if specs else None

    def _edge_path_active(edge) -> bool:
        spec = _edge_spec(edge)
        if spec is not None:
            if not is_transition_path_active(spec, selected_path):
                return False
            spec_path = str(getattr(spec, "path_key", "") or "").strip()
            edge_paths = tuple(getattr(edge, "paths", ()) or ())
            if not spec_path and edge_paths and selected_path:
                return selected_path in edge_paths
            return True
        if not edge.paths:
            return True
        return bool(selected_path and selected_path in edge.paths)

    def _edge_gate_active(edge) -> bool:
        try:
            if t02_review_committed_current_iteration and str(getattr(edge, "key", "") or "").strip() == "e1_to_e2":
                return False
            if t01_entry_committed_current_iteration and str(getattr(edge, "key", "") or "").strip() == "e1_to_e3":
                return False
        except Exception:
            pass
        if current_step != _stage_num(edge.source):
            return False
        edge_paths = tuple(getattr(edge, "paths", ()) or ())
        if edge_paths and _stage_num(edge.source) > 1:
            return bool(selected_path and selected_path in edge_paths)
        return True

    def _edge_selected(edge) -> bool:
        if selected_edge_key and str(getattr(edge, "key", "") or "").strip() == selected_edge_key:
            return True
        spec = _edge_spec(edge)
        path_key = str(getattr(spec, "path_key", "") or "").strip()
        return bool(
            _edge_gate_active(edge)
            and path_key
            and selected_path
            and path_key == selected_path
        ) or bool(
            _edge_gate_active(edge)
            and not path_key
            and selected_path
            and selected_path in tuple(getattr(edge, "paths", ()) or ())
        )

    def _edge_in_selected_path(edge) -> bool:
        spec = _edge_spec(edge)
        path_key = str(getattr(spec, "path_key", "") or "").strip()
        if path_key:
            return bool(_edge_gate_active(edge) and selected_path and path_key == selected_path)
        edge_paths = tuple(getattr(edge, "paths", ()) or ())
        return bool(_edge_gate_active(edge) and selected_path and selected_path in edge_paths)

    def _edge_select_enabled(edge) -> bool:
        try:
            if t02_review_committed_current_iteration and str(getattr(edge, "key", "") or "").strip() == "e1_to_e2":
                return False
            if t01_entry_committed_current_iteration and str(getattr(edge, "key", "") or "").strip() == "e1_to_e3":
                return False
        except Exception:
            pass
        return bool(_edge_gate_active(edge))

    def _edge_dimmed_by_selection(edge) -> bool:
        if not _edge_gate_active(edge):
            return False
        current_key = str(getattr(edge, "key", "") or "").strip()
        if t02_review_committed_current_iteration and current_key == "e1_to_e2":
            return True
        selected_key = str(selected_edge_key or "").strip()
        if selected_key and selected_key != current_key:
            try:
                selected_edge = CAMPAIGN_TRANSITION_GRAPH.get_edge(selected_key)
            except Exception:
                selected_edge = None
            selected_source = str(getattr(selected_edge, "source", "") or "").strip().upper() if selected_edge is not None else ""
            current_source = str(getattr(edge, "source", "") or "").strip().upper()
            if selected_source == "E1" and current_source == "E1":
                return True
        if not selected_path:
            return False
        spec = _edge_spec(edge)
        path_key = str(getattr(spec, "path_key", "") or "").strip()
        if path_key:
            return bool(path_key != selected_path)
        edge_paths = tuple(getattr(edge, "paths", ()) or ())
        return bool(edge_paths and selected_path not in edge_paths)

    def _edge_operable(edge) -> bool:
        return bool(_edge_gate_active(edge) and not _edge_dimmed_by_selection(edge))

    def _workflow_focus_scope():
        return resolve_workflow_focus(
            CAMPAIGN_TRANSITION_GRAPH,
            current_step=current_step,
            selected_edge=selected_edge_key,
            selected_path=selected_path,
            operable_edges={edge.key for edge in CAMPAIGN_TRANSITION_GRAPH.edges if _edge_operable(edge)},
        )

    def _sync_graph_toolbar() -> None:
        scope = _workflow_focus_scope()
        if len(scope.edges) == 1:
            edge = CAMPAIGN_TRANSITION_GRAPH.get_edge(next(iter(scope.edges)))
            spec = _edge_spec(edge)
            badge = _visible_badge_id(getattr(spec, "badge_id", ""))
            context = f"{badge} | {edge.source} → {edge.target}"
        else:
            context = "Wybierz przejście"
        graph_toolbar.sync(_graph_zoom(), context)

    def _edge_requires_explicit_selection(edge) -> bool:
        return bool(_edge_select_enabled(edge))

    def _edge_fields_enabled(edge) -> bool:
        if not _edge_operable(edge):
            return False
        if _edge_requires_explicit_selection(edge):
            return bool(_edge_selected(edge))
        return True

    def _edge_completed(edge) -> bool:
        spec = _edge_spec(edge)
        if spec is not None:
            return is_transition_completed(spec, transition_eval_ctx)
        source_num = _stage_num(edge.source)
        source_status = _stage_status_value(edge.source)
        return bool(source_status == "approved" or current_step > source_num)

    def _edge_ready(edge) -> bool:
        spec = _edge_spec(edge)
        if spec is not None:
            source = str(getattr(spec, "source", "") or "").strip().upper()
            if (
                str(getattr(spec, "key", "") or "").strip() == "e1_to_e2_prepare_plate_annotations"
                and normalize_iteration_path(explicit_selected_path) not in {"plate_training", "char_from_images"}
            ):
                return False
            if str(getattr(spec, "key", "") or "").strip() == "e3_to_e4_chars":
                if not is_transition_path_active(spec, selected_path):
                    return False
                gate = _t06_exported_char_dataset_state()
                ready_dataset = str(gate.get("ready_dataset") or gate.get("dataset_hint") or "").strip()
                return bool(gate.get("ok") and ready_dataset)
            if (
                str(getattr(spec, "key", "") or "").strip() == "e4_to_e1_next_iteration"
                and _get_t07_pending_repair_approved_state()
            ):
                return False
            if (
                str(getattr(spec, "key", "") or "").strip() == "e4_to_e1_next_iteration"
                and _current_step4_work_interruption_state()
            ):
                return False
            transition_ready = is_transition_ready(spec, transition_eval_ctx)
            if (
                str(getattr(spec, "key", "") or "").strip() == "e4_to_e1_next_iteration"
                and _current_step4_without_training_decision_ready()
            ):
                return True
            if source in {"E2", "E3", "E4"} and is_transition_path_active(spec, selected_path):
                if not transition_ready:
                    return False
                status = _get_graph_wizard_stage_status(f"step{_stage_num(source)}")
                if bool(
                    status is not None
                    and str(getattr(status, "badge_action_label", "") or "").strip()
                    and callable(getattr(status, "badge_action_command", None))
                ):
                    # In legacy step 4 the old wizard exposes "finish without training" as a
                    # persistent badge. In the graph this is an explicit action,
                    # not a signal that the final gate should blink as ready immediately.
                    if source == "E4":
                        label = str(getattr(status, "badge_action_label", "") or "").strip().casefold()
                        if "bez treningu" in label:
                            return bool(
                                _current_step4_without_training_decision_ready()
                                or transition_ready
                            )
                    return True
                return transition_ready
            return transition_ready
        return False

    def _edge_pending_resource_review(edge) -> bool:
        specs = get_transition_specs_for_edge(getattr(edge, "key", ""))
        if not specs:
            return False
        try:
            report = build_transition_resource_report(
                specs,
                getattr(transition_eval_ctx, "resource_snapshots", None),
                selected_path=selected_path,
            )
            return any(bool(getattr(row, "review_required", False)) for row in report.missing_required)
        except Exception:
            return False

    def _edge_pending_resource_review_label(edge) -> str:
        specs = get_transition_specs_for_edge(getattr(edge, "key", ""))
        if not specs:
            return ""
        try:
            report = build_transition_resource_report(
                specs,
                getattr(transition_eval_ctx, "resource_snapshots", None),
                selected_path=selected_path,
            )
            for row in report.missing_required:
                if bool(getattr(row, "review_required", False)):
                    try:
                        meta = resource_snapshot_meta(getattr(row, "snapshot", None))
                    except Exception:
                        meta = {}
                    label = str(
                        meta.get("pending_action_compact_status")
                        or meta.get("pending_work_status")
                        or ""
                    ).strip()
                    if label:
                        return label
                    if str(getattr(row, "canonical_key", "") or getattr(row, "key", "") or "").strip() == "plate_run":
                        return "Kontroluj AT"
                    return f"Kontroluj {row.compact_label}"
        except Exception:
            return ""
        return ""

    def _edge_current_iteration_work_status(edge) -> str:
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key != "e3_to_e4":
            return ""
        try:
            if _t06_interrupted_work_state():
                return ""
        except Exception:
            pass
        try:
            if not _edge_ready(edge):
                return ""
        except Exception:
            return ""
        try:
            current_iter = max(1, int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1))
        except Exception:
            current_iter = 1
        if current_iter <= 1:
            return ""

        backfill_reasons = {
            "approve_step3_backfill",
            "graph_backfill_from_pz3_summary",
            "summary_backfill",
            "summary_backfill_after_pz3_session",
            "replace_approve_backfill_with_pz3_export",
        }

        def _is_backfill_reason(payload: dict) -> bool:
            reason = str((payload or {}).get("reason") or "").strip().lower()
            return bool(
                reason in backfill_reasons
                or reason.startswith("graph_backfill")
                or reason.startswith("summary_backfill")
            )

        def _payload_iteration(payload: dict) -> int:
            if not isinstance(payload, dict):
                return 0
            for field in ("source_iteration", "created_iteration", "produced_iteration", "fulfilled_iteration", "iteration"):
                try:
                    iteration_num = int(payload.get(field, 0) or 0)
                except Exception:
                    iteration_num = 0
                if iteration_num > 0:
                    return iteration_num
            return 0

        def _is_current_user_work(payload: dict) -> bool:
            if not isinstance(payload, dict):
                return False
            if not bool(payload.get("fulfilled")):
                return False
            if _is_backfill_reason(payload):
                return False
            return bool(_payload_iteration(payload) == current_iter)

        try:
            contracts = dict((CAMPAIGN.get_iteration_state() or {}).get("t06_contracts") or {})
        except Exception:
            contracts = {}
        pz2_contract = dict(contracts.get("pz2_char_boxes") or {})
        pz3_contract = dict(contracts.get("pz3_char_dataset") or {})
        current_products = []
        if _is_current_user_work(pz2_contract):
            current_products.append("PZ2")
        if _is_current_user_work(pz3_contract):
            current_products.append("PZ3")
        try:
            gate = dict(_t06_exported_char_dataset_state() or {})
        except Exception:
            gate = {}
        if not _is_backfill_reason(pz3_contract):
            for field, label in (("pz2_iteration", "PZ2"), ("pz3_iteration", "PZ3"), ("source_iteration", "PZ3")):
                try:
                    gate_iteration = int(gate.get(field, 0) or 0)
                except Exception:
                    gate_iteration = 0
                if gate_iteration == current_iter and label not in current_products:
                    current_products.append(label)
        if current_products:
            return ""
        return f"BEZ PRZYROSTU IT{current_iter}"

    def _edge_t01_work_compact_status(edge) -> str:
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key != "e1_to_e2":
            return ""
        try:
            if _edge_completed(edge):
                return ""
        except Exception:
            pass
        try:
            has_images = bool(_transition_resource_present("images") or int(image_count or 0) > 0)
        except Exception:
            has_images = False
        if not has_images:
            return ""
        path = normalize_iteration_path(explicit_selected_path or selected_path)
        if path in {"plate_training", "char_from_images"}:
            try:
                if _edge_ready(edge):
                    return "ZATWIERDŹ -> Z2"
            except Exception:
                pass
            return "UZUPEŁNIJ ZASOBY"
        return "WYBIERZ TOR PRACY"

    def _edge_t02_work_compact_status(edge) -> str:
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key != "e1_to_e3":
            return ""
        try:
            if _edge_completed(edge):
                return ""
        except Exception:
            pass
        try:
            if _edge_ready(edge):
                return "ZATWIERDŹ -> Z3"
        except Exception:
            pass
        try:
            if _transition_resource_present("plate_run"):
                return "KONTROLUJ AT"
        except Exception:
            pass
        return ""

    _step2_plate_opportunity_cache: dict | None = None

    def _step2_plate_opportunity_state() -> dict:
        nonlocal _step2_plate_opportunity_cache
        if _step2_plate_opportunity_cache is not None:
            return dict(_step2_plate_opportunity_cache)

        try:
            iteration_num = max(1, int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1))
        except Exception:
            iteration_num = 1
        try:
            minimum_plates = max(1, int(min_plates or getattr(CONFIG, "CAMPAIGN_MIN_PLATE_ANNOTATIONS", 10) or 10))
        except Exception:
            minimum_plates = 10

        def _int_from(payload: dict, key: str) -> int:
            try:
                return max(0, int((payload or {}).get(key, 0) or 0))
            except Exception:
                return 0

        def _normalize_image_name(raw_value) -> str:
            raw_text = str(raw_value or "").strip()
            if not raw_text:
                return ""
            try:
                normalized = CAMPAIGN._normalize_image_set_name(raw_text)
            except Exception:
                try:
                    normalized = Path(raw_text.replace("\\", "/")).name
                except Exception:
                    normalized = raw_text.replace("\\", "/").rsplit("/", 1)[-1]
            return str(normalized or "").strip().lower()

        try:
            iteration_stats = dict(CAMPAIGN.get_plate_approved_set_iteration_stats(iteration_num, active_project_name or None) or {})
        except Exception:
            iteration_stats = {}
        try:
            project_stats = dict(CAMPAIGN.get_plate_approved_set_stats(active_project_name or None) or {})
        except Exception:
            project_stats = {}

        current_images = _int_from(iteration_stats, "images")
        current_plates = _int_from(iteration_stats, "plates")
        project_images = _int_from(project_stats, "images")
        project_plates = _int_from(project_stats, "plates")
        previous_images = max(0, project_images - current_images)
        previous_plates = max(0, project_plates - current_plates)

        source_names: set[str] = set()
        try:
            source_count = max(0, int(CAMPAIGN.get_iteration_image_count(iteration_num, active_project_name or None) or 0))
        except Exception:
            try:
                source_count = max(0, int(image_count or 0))
            except Exception:
                source_count = 0
        try:
            manifest = dict(CAMPAIGN.load_ingest_manifest(iteration_num, active_project_name or None) or {})
        except Exception:
            manifest = {}
        if isinstance(manifest, dict):
            for item in list(manifest.get("selected_images") or []):
                if isinstance(item, dict):
                    raw_name = item.get("name") or item.get("image_name") or item.get("source_path") or ""
                else:
                    raw_name = item
                normalized = _normalize_image_name(raw_name)
                if normalized:
                    source_names.add(normalized)
            if not source_count:
                try:
                    source_count = max(0, int(manifest.get("selected_count", 0) or 0))
                except Exception:
                    source_count = 0
        if not source_count and source_names:
            source_count = len(source_names)

        approved_names: set[str] = set()
        try:
            for entry in list(CAMPAIGN.list_plate_approved_entries(active_project_name or None) or []):
                if not isinstance(entry, dict):
                    continue
                for raw_name in (entry.get("image_name", ""), entry.get("entry_key", "")):
                    normalized = _normalize_image_name(raw_name)
                    if normalized:
                        approved_names.add(normalized)
        except Exception:
            approved_names = set()

        approved_in_source = len(source_names & approved_names) if source_names else current_images
        already_done_images = max(approved_in_source, current_images)
        remaining_images = max(0, int(source_count or 0) - int(already_done_images or 0))
        ready_from_previous = bool(
            previous_plates >= minimum_plates
            and project_plates >= minimum_plates
            and current_plates < minimum_plates
        )

        _step2_plate_opportunity_cache = {
            "iteration": int(iteration_num),
            "minimum_plates": int(minimum_plates),
            "source_images": int(source_count),
            "remaining_images": int(remaining_images),
            "current_images": int(current_images),
            "current_plates": int(current_plates),
            "project_images": int(project_images),
            "project_plates": int(project_plates),
            "previous_images": int(previous_images),
            "previous_plates": int(previous_plates),
            "ready_from_previous": bool(ready_from_previous),
            "has_optional_work": bool(remaining_images > 0),
        }
        return dict(_step2_plate_opportunity_cache)

    def _edge_step2_resource_origin_status(edge) -> str:
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key != "e2_to_e4":
            return ""
        try:
            if _edge_completed(edge) or not _edge_ready(edge):
                return ""
        except Exception:
            return ""
        state = _step2_plate_opportunity_state()
        if not bool(state.get("ready_from_previous")):
            return ""
        current_plates_count = int(state.get("current_plates", 0) or 0)
        remaining_count = int(state.get("remaining_images", 0) or 0)
        if current_plates_count > 0:
            return f"AT z poprzednich iteracji +{current_plates_count} AT w IT{int(state.get('iteration', 0) or 0)}"
        if remaining_count > 0:
            return f"AT z poprzednich iteracji | +{remaining_count} obrazów w Z2"
        return "AT z poprzednich iteracji"

    def _edge_step2_work_compact_status(edge) -> str:
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key not in {"e2_to_e3", "e2_to_e4"}:
            return ""
        try:
            if _edge_completed(edge):
                return ""
        except Exception:
            pass
        target_label = "Z3" if edge_key == "e2_to_e3" else "Z4"
        try:
            if _edge_ready(edge):
                if edge_key == "e2_to_e4":
                    opportunity = _step2_plate_opportunity_state()
                    remaining_count = int(opportunity.get("remaining_images", 0) or 0)
                    if remaining_count > 0:
                        return f"DODAJ +{remaining_count} W Z2"
                    if bool(opportunity.get("ready_from_previous")):
                        return "GOTOWE Z POPRZ. ITERACJI"
                return f"ZATWIERDŹ -> {target_label}"
        except Exception:
            pass
        return "PRACUJ W Z2"

    def _edge_t06_work_compact_status(edge) -> str:
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key != "e3_to_e4":
            return ""
        try:
            if _edge_completed(edge):
                return ""
        except Exception:
            pass
        try:
            pending_t06 = dict(_t06_interrupted_work_state() or {})
        except Exception:
            pending_t06 = {}
        if pending_t06:
            work_area = str(pending_t06.get("work_area") or pending_t06.get("interrupted_kind") or "").strip().lower()
            try:
                session = dict(pending_t06.get("t06_work_session") or {})
            except Exception:
                session = {}
            substep = str(
                pending_t06.get("substep")
                or pending_t06.get("target_substep")
                or session.get("substep")
                or session.get("target_substep")
                or ""
            ).strip().lower()
            if work_area == "z3" and substep in {"3", "dataset", "pz3", "z3_pz3"}:
                return "WZNÓW PZ3"
            if work_area == "z3":
                return "WZNÓW PZ2"
            try:
                pending_images = int(pending_t06.get("unpromoted_approved_images", 0) or 0)
            except Exception:
                pending_images = 0
            if pending_images > 0:
                return "ROZLICZ [OK]"
            return "WZNÓW PRACĘ"

        try:
            gate = dict(_t06_exported_char_dataset_state() or {})
        except Exception:
            gate = {}
        ready_dataset = str(gate.get("ready_dataset") or gate.get("dataset_hint") or "").strip()
        if bool(gate.get("ok")) and ready_dataset:
            return _edge_current_iteration_work_status(edge)

        try:
            current_iter = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            current_iter = 1
        try:
            contracts = dict((CAMPAIGN.get_iteration_state() or {}).get("t06_contracts") or {})
            pz2_contract = dict(contracts.get("pz2_char_boxes") or {})
            pz2_iteration = 0
            for field in ("source_iteration", "created_iteration", "produced_iteration", "fulfilled_iteration", "iteration"):
                try:
                    pz2_iteration = int(pz2_contract.get(field, 0) or 0)
                except Exception:
                    pz2_iteration = 0
                if pz2_iteration > 0:
                    break
            pz2_reason = str(pz2_contract.get("reason") or "").strip().lower()
            pz2_backfill = bool(
                pz2_reason in {
                    "approve_step3_backfill",
                    "graph_backfill_from_pz3_summary",
                    "summary_backfill",
                    "summary_backfill_after_pz3_session",
                    "replace_approve_backfill_with_pz3_export",
                }
                or pz2_reason.startswith("graph_backfill")
                or pz2_reason.startswith("summary_backfill")
            )
            pz2_current_ready = bool(
                pz2_contract.get("fulfilled")
                and not pz2_backfill
                and pz2_iteration > 0
                and pz2_iteration == current_iter
            )
        except Exception:
            pz2_current_ready = False

        reason = str(gate.get("reason") or "").strip().lower()
        if pz2_current_ready:
            return "UTWÓRZ AZ W PZ3"
        if reason in {"stale_char_dataset", "invalid_char_dataset"}:
            return "NAPRAW: PZ2 -> PZ3"
        if reason in {"missing_char_dataset", "missing_char_boxes", "missing_perfect_plates"}:
            return "START: PZ2 -> PZ3"
        return "PRACA: PZ2 -> PZ3"

    def _edge_work_compact_status(edge) -> str:
        review_label = _edge_pending_resource_review_label(edge)
        if review_label:
            return review_label
        t01_status = _edge_t01_work_compact_status(edge)
        if t01_status:
            return t01_status
        t02_status = _edge_t02_work_compact_status(edge)
        if t02_status:
            return t02_status
        step2_status = _edge_step2_work_compact_status(edge)
        if step2_status:
            return step2_status
        t06_status = _edge_t06_work_compact_status(edge)
        if t06_status:
            return t06_status
        return _edge_current_iteration_work_status(edge)

    def _edge_status(edge) -> tuple[str, str]:
        if not _edge_gate_active(edge):
            return "", muted_dim
        if _edge_dimmed_by_selection(edge):
            return "WYBIERZ", muted_dim
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key == "e2_to_e4" and _step2_unpromoted_t05_state():
            return "PRZERWANE", warning
        if edge_key == "e3_to_e4":
            if _edge_requires_explicit_selection(edge) and not _edge_selected(edge):
                return "WYBIERZ", muted_dim
            if _edge_ready(edge):
                return "OTWARTA", success
            if _t06_interrupted_work_state():
                return "PRZERWANE", warning
        if _is_t07_graph_edge(getattr(edge, "key", "")) and _current_step4_work_interruption_state():
            return "PRZERWANE", warning
        if _is_t07_graph_edge(getattr(edge, "key", "")) and _current_t07_training_candidate_state():
            return "WYBIERZ WYNIK", warning
        if _edge_requires_explicit_selection(edge) and not _edge_selected(edge):
            return "WYBIERZ", muted_dim
        if _edge_pending_resource_review(edge):
            return "DO KONTROLI", warning
        if _edge_ready(edge):
            return "OTWARTA", success
        return "ZAMKNIĘTA", warning

    def _edge_resource_compact_status(edge) -> str:
        if _edge_requires_explicit_selection(edge) and not _edge_selected(edge):
            return ""
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if edge_key == "e2_to_e4":
            step2_origin_status = _edge_step2_resource_origin_status(edge)
            if step2_origin_status:
                return step2_origin_status
        if edge_key == "e3_to_e4":
            try:
                gate = dict(_t06_exported_char_dataset_state() or {})
            except Exception:
                gate = {}
            ready_dataset = str(gate.get("ready_dataset") or gate.get("dataset_hint") or "").strip()
            if bool(gate.get("ok")) and ready_dataset:
                def _infer_badge_dataset_iteration(dataset_value: str) -> int:
                    dataset_token = ""
                    try:
                        dataset_token = str(Path(dataset_value).resolve()).casefold()
                    except Exception:
                        dataset_token = str(dataset_value or "").replace("\\", "/").casefold()
                    if not dataset_token:
                        return 0
                    found_iterations: list[int] = []
                    try:
                        registry = CAMPAIGN.load_artifact_registry(active_project_name or None)
                    except Exception:
                        registry = {}
                    for state_key, entry in dict((registry or {}).get("iteration_state") or {}).items():
                        if not isinstance(entry, dict):
                            continue
                        contract = dict((entry.get("t06_contracts") or {}).get("pz3_char_dataset") or {})
                        contract_dataset = str(contract.get("dataset_path") or "").strip()
                        if not contract_dataset:
                            continue
                        try:
                            contract_token = str(Path(contract_dataset).resolve()).casefold()
                        except Exception:
                            contract_token = contract_dataset.replace("\\", "/").casefold()
                        if contract_token != dataset_token:
                            continue
                        try:
                            found_iterations.append(int(state_key or contract.get("iteration") or 0))
                        except Exception:
                            continue
                    return min(found_iterations) if found_iterations else 0

                try:
                    source_iteration = int(
                        gate.get("source_iteration")
                        or gate.get("pz3_iteration")
                        or gate.get("iteration")
                        or 0
                    )
                except Exception:
                    source_iteration = 0
                try:
                    current_iter = int(current_iteration or CAMPAIGN.get_current_iteration_num() or 1)
                except Exception:
                    current_iter = 1
                inferred_iteration = _infer_badge_dataset_iteration(ready_dataset)
                if inferred_iteration > 0 and (source_iteration <= 0 or inferred_iteration < source_iteration):
                    source_iteration = inferred_iteration
                if source_iteration > 0:
                    suffix = "z poprzednich iteracji" if source_iteration < current_iter else "z bieżącej iteracji"
                    return f"OK: AZ z IT{source_iteration} ({suffix})"
                return "OK: AZ gotowy"
        if _is_t07_graph_edge(getattr(edge, "key", "")):
            if _current_t07_training_candidate_state():
                return "WYBIERZ WYNIK"
            pending_t07 = _get_t07_pending_repair_approved_state()
            if pending_t07:
                try:
                    pending_images = int(pending_t07.get("unpromoted_approved_images", 0) or 0)
                except Exception:
                    pending_images = 0
                if pending_images > 0:
                    return f"NAPRAWA +{pending_images} OK"
        spec = _edge_spec(edge)
        if (
            spec is not None
            and str(getattr(spec, "key", "") or "").strip() == "e4_to_e1_next_iteration"
            and _current_step4_without_training_decision_ready()
        ):
            return "OK"
        specs = get_transition_specs_for_edge(getattr(edge, "key", ""))
        if not specs:
            return ""
        try:
            report = build_transition_resource_report(
                specs,
                getattr(transition_eval_ctx, "resource_snapshots", None),
                selected_path=selected_path,
            )
            if any(bool(getattr(row, "review_required", False)) for row in report.missing_required):
                return "KOMPLET O-AT"
            return report.compact_status()
        except Exception:
            return ""

    def _edge_resource_badge_status(edge) -> str:
        """Short, human-readable resource status for the tiny graph badge."""
        text = str(_edge_resource_compact_status(edge) or "").strip()
        if not text:
            return ""
        edge_key = str(getattr(edge, "key", "") or "").strip()
        if _is_t07_graph_edge(edge_key):
            training_snapshot = transition_eval_ctx.resource_snapshot("training_result")
            try:
                training_tone = str(getattr(training_snapshot, "tone", "") or "").strip().lower()
            except Exception:
                training_tone = ""
            if training_tone == "warning" and getattr(training_snapshot, "has_source", False):
                return "Wybierz wytrenowany model"
        upper = text.upper()
        if upper in {"OK", "WYBIERZ"}:
            return text
        if _is_t07_graph_edge(edge_key) and upper.startswith("BRAK:"):
            return "Brak: wynik treningu"
        if upper.startswith("BRAK:"):
            missing = upper.split(":", 1)[1].strip()
            if "OBRAZ" in missing:
                return "Brak: obrazy"
            if "ANOTACJE TABLIC" in missing or "TABLIC" in missing:
                return "Brak: tablice [OK]"
            if "DATASET" in missing and "ZNAK" in missing:
                return "Brak: dataset znaków"
            if "ANOTACJE ZNAK" in missing or "ZNAK" in missing:
                return "Brak: znaki"
            return text
        return text

    def _edge_approve_enabled(edge) -> bool:
        if not _edge_fields_enabled(edge):
            return False
        return bool(_edge_ready(edge))

    def _edge_resources_enabled(edge) -> bool:
        return bool(_edge_fields_enabled(edge))

    def _edge_actions_enabled(edge) -> bool:
        specs = get_transition_specs_for_edge(getattr(edge, "key", ""))
        if specs and all(str(getattr(spec, "source", "") or "").strip().upper() == "E1" for spec in specs):
            return str(getattr(edge, "key", "") or "").strip() in {"e1_to_e2", "e1_to_e3"} and bool(_edge_fields_enabled(edge))
        return bool(_edge_fields_enabled(edge))

    def _select_path(path_key: str) -> None:
        return campaign_graph_actions.execute_campaign_graph_action(
            self,
            "set_iteration_path",
            payload={"path_key": path_key, "refresh": False, "lightweight": True},
        )

    def _can_clear_step1_gate_selection(edge) -> bool:
        try:
            if str(getattr(edge, "source", "") or "").strip().upper() != "E1":
                return False
            if int(current_step or 0) != 1:
                return False
            if str(CAMPAIGN.get_step1_status() or "").strip().lower() == "approved":
                return False
            try:
                if bool(CAMPAIGN.is_t02_at_review_committed_current_iteration()):
                    return False
            except Exception:
                pass
            return True
        except Exception:
            return False

    def _clear_step1_gate_selection(*, update_status: bool = True) -> None:
        nonlocal selected_path, current_target, selected_edge_key
        try:
            CAMPAIGN.clear_iteration_path()
            CAMPAIGN.clear_iteration_target()
            if hasattr(CAMPAIGN, "clear_graph_selected_edge_key"):
                CAMPAIGN.clear_graph_selected_edge_key()
        except Exception:
            try:
                CAMPAIGN.set_iteration_path("")
                CAMPAIGN.set_iteration_target("")
                if hasattr(CAMPAIGN, "set_graph_selected_edge_key"):
                    CAMPAIGN.set_graph_selected_edge_key("")
            except Exception:
                pass
        selected_path = ""
        current_target = ""
        selected_edge_key = ""
        try:
            self._campaign_graph_selected_edge_key = ""
        except Exception:
            pass
        try:
            refresh_menu_badge = getattr(self.app, "_refresh_menu_badge", None)
            if callable(refresh_menu_badge):
                refresh_menu_badge()
        except Exception:
            pass
        try:
            target_var = getattr(self, "_wizard_step2_target_var", None)
            if target_var is not None:
                target_var.set("")
        except Exception:
            pass
        if update_status:
            try:
                self.app.update_status(
                    "Cofnięto wybór bramki E1. Możesz ponownie wybrać właściwą ścieżkę.",
                    "info",
                )
            except Exception:
                pass

    def _open_choice_guide_modal(_event=None) -> str:
        current_hint = ""
        recommendation = ""
        try:
            history_entries = list(CAMPAIGN.load_project_history(limit=80) or [])
        except Exception:
            history_entries = []
        try:
            history_summary = list(CAMPAIGN.summarize_project_history(limit=5) or [])
        except Exception:
            history_summary = []

        def _history_has_action(action_name: str, *, before_current_iteration: bool = False) -> bool:
            expected = str(action_name or "").strip()
            if not expected:
                return False
            for entry in reversed(history_entries):
                try:
                    if before_current_iteration and int(entry.get("iteration", 0) or 0) >= int(current_iteration or 1):
                        continue
                except Exception:
                    pass
                if str(entry.get("status") or "").strip().lower() not in {"", "ok"}:
                    continue
                if str(entry.get("action") or "").strip() == expected:
                    return True
            return False

        def _snapshot_has_value(key: str) -> bool:
            try:
                snapshot = transition_eval_ctx.resource_snapshot(key)
            except Exception:
                snapshot = None
            if snapshot is None:
                return False
            try:
                return bool(
                    snapshot.has_source
                    or int(snapshot.counter_value or 0) > 0
                    or str(snapshot.tone or "").strip().lower() == "success"
                )
            except Exception:
                return bool(getattr(snapshot, "has_source", False))

        has_plate_model = _snapshot_has_value("plate_model")
        has_char_model = _snapshot_has_value("char_model")
        had_previous_e4 = _history_has_action("approve_step4", before_current_iteration=True) or _history_has_action(
            "approve_step4_without_training",
            before_current_iteration=True,
        )
        try:
            if current_step == 1:
                if selected_path == "plate_training":
                    current_hint = (
                        "Teraz wybrana jest T01: przygotowujesz anotacje tablic dla obrazów "
                        "z zasobów, a dalszy wybór prowadzi do modelu tablic."
                    )
                elif selected_path == "char_from_images":
                    current_hint = (
                        "Teraz wybrana jest T01: przygotowujesz anotacje tablic dla obrazów "
                        "z zasobów, a dalszy wybór prowadzi do toru znaków."
                    )
                elif selected_path == "char_from_ready_plates":
                    current_hint = (
                        "Teraz wybrana jest T03: potwierdzasz istniejące źródło tablic i przechodzisz dalej, "
                        "bez ponownego oznaczania tablic w Z2."
                    )
                else:
                    current_hint = "Jesteś w E1: najpierw wybierz jedną bramkę elektrodą."
                if material_ready:
                    recommendation = (
                        f"Historia i stan projektu pokazują co najmniej {min_plates} anotacji tablic (AT), "
                        "które mogą być wejściem do datasetu znaków. T03 pozwala przejść dalej "
                        "bez ponownego oznaczania tablic w Z2."
                    )
                elif image_potential:
                    recommendation = (
                        f"Widzimy katalog zdjęć spełniający minimum wejścia ({image_count}/{min_images}). "
                        "Jeśli startujesz od obrazów bez zgodnych AT, T01 jest logicznym wyborem."
                    )
                elif has_plate_model or has_char_model:
                    recommendation = (
                        "Masz wskazane modele, ale same modele nie zastępują danych wejściowych. "
                        "Do T01 potrzebny jest katalog zdjęć, a do T03 istniejące źródło tablic, najczęściej AT z importu albo poprzedniej iteracji."
                    )
                else:
                    recommendation = (
                        "Nie widzę jeszcze zasobów otwierających ścieżkę. Zacznij od katalogu zdjęć albo importu anotacji tablic."
                    )
            elif current_step == 2:
                current_hint = "Jesteś w E2: wybór dotyczy pracy nad tablicami i zamknięcia bramki do dalszego etapu."
                recommendation = "Historia jest tu pomocnicza: zamykasz E2 dopiero wtedy, gdy masz zatwierdzone obrazy z tablicami."
            elif current_step == 3:
                current_hint = "Jesteś w E3: wybór dotyczy budowy i eksportu datasetu znaków."
                recommendation = "Jeśli wracasz po poprzednim treningu znaków, sprawdź czy ta iteracja dodała nowe perfecty lub nowy dataset."
            elif current_step == 4:
                if current_target == "plate":
                    current_hint = "Jesteś w E4T: wybór dotyczy treningu modelu tablic albo świadomego zakończenia iteracji bez treningu."
                elif current_target == "char":
                    current_hint = "Jesteś w E4Z: wybór dotyczy treningu modelu znaków albo świadomego zakończenia iteracji bez treningu."
                else:
                    current_hint = "Jesteś w węźle treningu: wybór dotyczy treningu albo świadomego zakończenia iteracji bez treningu."
                recommendation = "Jeśli w tej iteracji nie powstały nowe dane, trening może nie dać realnej poprawy."
        except Exception:
            current_hint = ""
            recommendation = ""

        if had_previous_e4 and current_step == 1 and has_char_model:
            recommendation = (
                f"{recommendation} Masz też historię wcześniejszego treningu modelu znaków. "
                "To pomaga w E3, ale nie omija przygotowania tablic, jeśli startujesz od nowych zdjęć."
            ).strip()

        if history_summary:
            history_lines = [f"- {line}" for line in history_summary[:5]]
        else:
            history_lines = ["- Brak zapisanej historii akcji grafu dla tego projektu."]

        lines = [
            "Poradnik wyboru bramki",
            "",
            current_hint,
            "",
            "Historia projektu",
            *history_lines,
            "",
            "Wniosek z historii i aktualnego stanu",
            recommendation or "Historia nie daje jeszcze jednoznacznej rekomendacji. Kieruj się zasobami widocznymi w bramce.",
            "",
            "T01 - Bramka przygotowania anotacji tablic na obrazach",
            (
                "Wybierz, gdy obrazy z zasobów wymagają przygotowania albo uzupełnienia anotacji tablic. "
                "W pracy bramki wybierasz, czy te anotacje mają zasilić model tablic, czy tor znaków."
            ),
            "",
            "T03 - Bramka użycia istniejących anotacji tablic pod model znaków",
            (
                "Wybierz, gdy projekt ma już źródło tablic: AT z importu albo poprzedniej iteracji, "
                "z których program może przygotować dataset znaków. "
                f"Minimum: {min_plates} anotacji tablic. Ta bramka nie wykonuje pracy, nie rozpoznaje znaków i nie wymaga modelu znaków."
            ),
            "",
            "Dalej w cyklu",
            "T04/T05 zamykają pracę nad tablicami, a T06 zamyka trening lub iterację po przygotowaniu wariantu datasetu.",
            "",
            "Zasada praktyczna",
            "Jeśli startujesz od obrazów, wybierz T01. Jeśli masz AT z importu albo poprzedniej iteracji, wybierz T03.",
        ]
        show_history = getattr(self.app, "show_project_history_dialog", None)
        _open_small_modal(
            "Poradnik wyboru bramki",
            campaign_ui_helpers._repair_polish_text("\n".join(part for part in lines if part is not None)),
            [
                ("Otwórz pełną historię projektu", show_history, "info"),
            ] if callable(show_history) else [],
        )
        return "break"

    def _open_small_modal(
        title: str,
        body_text: str,
        buttons: list[tuple[str, object, str]],
        notice: dict | None = None,
    ) -> None:
        dialog = tk.Toplevel(self.frame)
        dialog._campaign_graph_dialog = True
        is_choice_guide = str(title or "").strip() == "Poradnik wyboru bramki"
        normalized_title = str(title or "").strip().lower()
        is_resource_modal = normalized_title.startswith("zasoby")
        is_work_modal = normalized_title.startswith("praca")
        try:
            self.app.style_dialog_window(dialog, title=title, geometry=("760x640" if is_choice_guide else "620x360"), parent=self.frame)
        except Exception:
            dialog.title(title)
        try:
            dialog.minsize(680 if is_choice_guide else 560, 520 if is_choice_guide else 320)
        except Exception:
            pass
        build_surface = getattr(self.app, "_build_themed_dialog_surface", None)
        if callable(build_surface):
            body = build_surface(dialog, tone="info")
        else:
            body = tk.Frame(dialog, bg=card_bg)
            body.pack(fill=tk.BOTH, expand=True)
        title_lbl = tk.Label(
            body,
            text=title,
            fg=fg,
            bg=str(body.cget("bg") or card_bg),
            font=("Segoe UI", 11, "bold"),
            anchor="w",
        )
        title_lbl.pack(fill=tk.X, padx=14, pady=(14, 5))
        if is_choice_guide:
            display_body = body_text
        elif is_resource_modal:
            display_body = "Sprawdź stan wymaganych zasobów tej bramki."
        elif is_work_modal:
            display_body = body_text or "Wybierz akcję. Zatwierdzanie zostaje na bramce grafu."
        else:
            display_body = body_text
        tk.Label(
            body,
            text=campaign_ui_helpers._repair_polish_text(str(display_body or "").strip()),
            fg=muted,
            bg=str(body.cget("bg") or card_bg),
            justify=tk.LEFT,
            anchor="w",
            wraplength=710 if is_choice_guide else 560,
        ).pack(fill=tk.X, padx=14, pady=(0, 12))
        if notice:
            notice_title = campaign_ui_helpers._repair_polish_text(str(notice.get("title", "") or "").strip())
            notice_text = campaign_ui_helpers._repair_polish_text(str(notice.get("text", "") or "").strip())
            notice_tone = str(notice.get("tone", "warning") or "warning").strip().lower()
            notice_color = warning if notice_tone == "warning" else accent
            notice_bg = blend_hex_colors(field_bg, notice_color, 0.12)
            notice_box = tk.Frame(
                body,
                bg=notice_bg,
                highlightthickness=1,
                highlightbackground=blend_hex_colors(notice_color, field_bg, 0.45),
                highlightcolor=blend_hex_colors(notice_color, field_bg, 0.45),
            )
            notice_box.pack(fill=tk.X, padx=14, pady=(0, 12))
            if notice_title:
                tk.Label(
                    notice_box,
                    text=notice_title,
                    fg=notice_color,
                    bg=notice_bg,
                    font=("Segoe UI", 9, "bold"),
                    anchor="w",
                ).pack(fill=tk.X, padx=10, pady=(7, 1))
            if notice_text:
                tk.Label(
                    notice_box,
                    text=notice_text,
                    fg=fg,
                    bg=notice_bg,
                    justify=tk.LEFT,
                    anchor="w",
                    wraplength=540,
                ).pack(fill=tk.X, padx=10, pady=(0, 8))
        buttons_host = tk.Frame(body, bg=str(body.cget("bg") or card_bg))
        buttons_host.pack(fill=tk.X, padx=14, pady=(0, 14), side=tk.BOTTOM)
        actions_host = tk.Frame(buttons_host, bg=str(body.cget("bg") or card_bg))
        actions_host.pack(fill=tk.X)

        for index, (label, command, tone) in enumerate(buttons, start=1):
            repaired_label = campaign_ui_helpers._repair_polish_text(str(label or ""))
            button_text = repaired_label
            btn = tk.Button(
                actions_host,
                text=button_text,
                command=lambda cmd=command: (dialog.destroy(), cmd() if callable(cmd) else None),
                cursor="hand2",
                bg=blend_hex_colors(field_bg, success, 0.18),
                fg=fg,
                relief=tk.FLAT,
                padx=12,
                pady=8,
                anchor="w",
                justify=tk.LEFT,
                wraplength=540,
            )
            btn.pack(fill=tk.X, pady=(0, 7))
        close_row = tk.Frame(buttons_host, bg=str(body.cget("bg") or card_bg))
        close_row.pack(fill=tk.X, pady=(4 if buttons else 0, 0))
        tk.Button(
            close_row,
            text="Zamknij",
            command=dialog.destroy,
            cursor="hand2",
            bg=field_bg,
            fg=fg,
            relief=tk.FLAT,
            padx=10,
            pady=6,
        ).pack(side=tk.RIGHT)
        try:
            dialog.transient(self.frame)
            dialog.grab_set()
        except Exception:
            pass

    def _open_t02_actions_modal(_body_text: str, buttons: list[tuple[str, object, str]]) -> None:
        edge_key = "e1_to_e3"
        edge = CAMPAIGN_TRANSITION_GRAPH.get_edge(edge_key)
        spec = _edge_spec(edge) if edge is not None else None
        visible_gate_id = _visible_badge_id(getattr(spec, "badge_id", "T02") if spec is not None else "T02") or "T02"
        row_count = max(1, len(buttons or ()))
        dialog_height = max(306, min(420, 218 + row_count * 88))
        dialog = tk.Toplevel(self.frame)
        dialog._campaign_graph_dialog = True
        try:
            self.app.style_dialog_window(
                dialog,
                title=f"Praca {visible_gate_id}",
                geometry=f"660x{dialog_height}",
                parent=self.frame,
            )
        except Exception:
            dialog.title(f"Praca {visible_gate_id}")
        try:
            dialog.minsize(620, min(260, dialog_height))
        except Exception:
            pass
        build_surface = getattr(self.app, "_build_themed_dialog_surface", None)
        if callable(build_surface):
            body = build_surface(dialog, tone="info")
        else:
            body = tk.Frame(dialog, bg=card_bg)
            body.pack(fill=tk.BOTH, expand=True)
        body_bg = str(body.cget("bg") or card_bg)

        status_text, status_color = _edge_status(edge) if edge is not None else ("", muted)
        review_label = _edge_pending_resource_review_label(edge) if edge is not None else ""

        header = tk.Frame(body, bg=body_bg)
        header.pack(fill=tk.X, padx=16, pady=(14, 6))
        tk.Label(
            header,
            text=f"Praca bramki {visible_gate_id}",
            fg=fg,
            bg=body_bg,
            font=("Segoe UI", 12, "bold"),
            anchor="w",
        ).pack(side=tk.LEFT, fill=tk.X, expand=True)
        tk.Label(
            header,
            text=str(status_text or "WYBIERZ"),
            fg=status_color,
            bg=blend_hex_colors(body_bg, status_color, 0.10),
            font=("Segoe UI", 8, "bold"),
            padx=9,
            pady=4,
        ).pack(side=tk.RIGHT)

        intro_text = (
            "Tutaj kontrolujesz anotacje tablic z importu lub zatwierdzonej puli projektu. "
            "Po sprawdzeniu AT wróć do grafu i zatwierdź T02, aby przejść do pracy nad znakami."
        )
        tk.Label(
            body,
            text=campaign_ui_helpers._repair_polish_text(intro_text),
            fg=muted,
            bg=body_bg,
            justify=tk.LEFT,
            anchor="w",
            wraplength=610,
        ).pack(fill=tk.X, padx=16, pady=(0, 10))

        list_host = tk.Frame(body, bg=body_bg)
        list_host.pack(fill=tk.X, padx=16, pady=(0, 10))

        def _run_t02_action(command):
            close_graph_dialogs(self.frame)
            return command() if callable(command) else False

        def _draw_control_icon(canvas: tk.Canvas, tone_color: str) -> None:
            try:
                canvas.delete("all")
                bg = str(canvas.cget("bg") or field_bg)
                ink = palette["ink_deep"]
                icon_bg = blend_hex_colors(tone_color, palette["blend_light"], 0.28)
                icon_outline = blend_hex_colors(ink, tone_color, 0.08)
                check_color = palette["success"]
                canvas.create_rectangle(2, 2, 30, 30, fill=icon_bg, outline=icon_outline, width=2)
                canvas.create_line(7, 9, 20, 9, fill=ink, width=2)
                canvas.create_line(7, 15, 18, 15, fill=ink, width=2)
                canvas.create_oval(15, 15, 25, 25, outline=ink, width=2)
                canvas.create_line(23, 23, 29, 29, fill=ink, width=2)
                canvas.create_line(7, 23, 11, 27, 17, 19, fill=check_color, width=3, capstyle=tk.ROUND, joinstyle=tk.ROUND)
            except Exception:
                pass

        def _action_suggestion(label: str, tone: str) -> dict:
            label_lower = str(label or "").strip().lower()
            if "kontrol" in label_lower or "import" in label_lower:
                return {
                    "title": "KONTROLA AT",
                    "detail": review_label
                    or "Sprawdź import w Z2 i oznacz poprawne pozycje jako [OK].",
                    "tone": warning,
                    "fill": 0.13,
                }
            return {
                "title": "WYBÓR ŚCIEŻKI",
                "detail": "Potwierdza pracę na istniejącym źródle tablic.",
                "tone": accent if str(tone or "").strip() != "warning" else warning,
                "fill": 0.10,
            }

        for index, (label, command, tone) in enumerate(buttons or (), start=1):
            normalized_label = campaign_ui_helpers._repair_polish_text(str(label or "").strip())
            tone_color = warning if str(tone or "").strip().lower() == "warning" else accent
            suggestion = _action_suggestion(normalized_label, str(tone or "info"))
            suggestion_tone = str(suggestion.get("tone") or tone_color)
            row_bg = blend_hex_colors(field_bg, tone_color, 0.045)
            row_border = blend_hex_colors(tone_color, field_bg, 0.20)
            row = tk.Frame(
                list_host,
                bg=row_bg,
                highlightthickness=1,
                highlightbackground=row_border,
                highlightcolor=row_border,
            )
            row.pack(fill=tk.X, pady=(0, 8))
            row.columnconfigure(0, weight=1)
            row.columnconfigure(1, weight=0, minsize=300)
            row.columnconfigure(2, weight=0)

            tk.Label(
                row,
                text=f"{index}. {normalized_label}",
                fg=fg,
                bg=row_bg,
                font=("Segoe UI", 10, "bold"),
                anchor="w",
                justify=tk.LEFT,
                wraplength=230,
            ).grid(row=0, column=0, sticky="ew", padx=(12, 8), pady=9)

            suggestion_bg = blend_hex_colors(row_bg, suggestion_tone, float(suggestion.get("fill", 0.10) or 0.10))
            suggestion_border = blend_hex_colors(suggestion_tone, row_bg, 0.32)
            suggestion_shell = tk.Frame(
                row,
                bg=suggestion_bg,
                highlightthickness=1,
                highlightbackground=suggestion_border,
                highlightcolor=suggestion_border,
                padx=7,
                pady=5,
            )
            suggestion_shell.grid(row=0, column=1, sticky="ew", padx=(4, 4), pady=8)
            suggestion_shell.columnconfigure(1, weight=1)
            icon = tk.Canvas(
                suggestion_shell,
                width=32,
                height=32,
                bg=suggestion_bg,
                bd=0,
                highlightthickness=0,
            )
            icon.grid(row=0, column=0, rowspan=2, sticky="n", padx=(0, 8), pady=(1, 0))
            _draw_control_icon(icon, suggestion_tone)
            tk.Label(
                suggestion_shell,
                text=campaign_ui_helpers._repair_polish_text(str(suggestion.get("title") or "")),
                fg=suggestion_tone,
                bg=suggestion_bg,
                font=("Segoe UI Semibold", 8),
                anchor="w",
                justify=tk.LEFT,
            ).grid(row=0, column=1, sticky="ew")
            tk.Label(
                suggestion_shell,
                text=_format_gate_work_suggestion_text(suggestion.get("detail")),
                fg=fg,
                bg=suggestion_bg,
                font=("Segoe UI", 7),
                anchor="w",
                justify=tk.LEFT,
                wraplength=230,
            ).grid(row=1, column=1, sticky="ew")

            button_bg = blend_hex_colors(field_bg, tone_color, 0.18)
            button_hover_bg = blend_hex_colors(field_bg, tone_color, 0.30)
            choose_button = tk.Button(
                row,
                text="Wybierz",
                command=lambda cmd=command: _run_t02_action(cmd),
                cursor="hand2",
                bg=button_bg,
                activebackground=button_hover_bg,
                activeforeground=fg,
                fg=fg,
                relief=tk.FLAT,
                padx=12,
                pady=5,
                width=10,
            )
            choose_button.grid(row=0, column=2, sticky="e", padx=(2, 10), pady=8)
            try:
                choose_button.bind("<Enter>", lambda _event, btn=choose_button, color=button_hover_bg: btn.config(bg=color), add="+")
                choose_button.bind("<Leave>", lambda _event, btn=choose_button, color=button_bg: btn.config(bg=color), add="+")
            except Exception:
                pass

        footer = tk.Frame(body, bg=body_bg)
        footer.pack(fill=tk.X, padx=16, pady=(0, 12))
        tk.Button(
            footer,
            text="Zamknij",
            command=dialog.destroy,
            cursor="hand2",
            bg=field_bg,
            fg=fg,
            relief=tk.FLAT,
            padx=12,
            pady=6,
        ).pack(side=tk.RIGHT)
        try:
            dialog.transient(self.frame)
            dialog.grab_set()
        except Exception:
            pass

    def _open_t05_actions_modal(_body_text: str, buttons: list[tuple[str, object, str]]) -> None:
        edge_key = "e2_to_e4"
