        def _open_resource_cell_details(row_key: str, field_key: str) -> None:
            row_widgets = widgets.get(str(row_key or ""), {})
            text = str(row_widgets.get(f"{field_key}_full_text", "") or "").strip()
            if not text:
                text = "Brak informacji."
            field_title = "Źródło" if field_key == "source" else "Walidacja"
            row_title = str(row_widgets.get("row_label", "") or row_key or "").strip()
            details = tk.Toplevel(dialog)
            try:
                self.app.style_dialog_window(details, title=field_title, geometry="720x360", parent=dialog)
            except Exception:
                details.title(field_title)
            build_surface = getattr(self.app, "_build_themed_dialog_surface", None)
            if callable(build_surface):
                details_body = build_surface(details, tone="info")
            else:
                details_body = tk.Frame(details, bg=card_bg)
                details_body.pack(fill=tk.BOTH, expand=True)
            details_bg = str(details_body.cget("bg") or card_bg)
            tk.Label(
                details_body,
                text=f"{field_title}: {row_title}",
                fg=fg,
                bg=details_bg,
                font=("Segoe UI", 11, "bold"),
                anchor="w",
            ).pack(fill=tk.X, padx=14, pady=(14, 8))
            text_frame = tk.Frame(details_body, bg=details_bg)
            text_frame.pack(fill=tk.BOTH, expand=True, padx=14, pady=(0, 12))
            scroll = ttk.Scrollbar(text_frame, orient=tk.VERTICAL)
            text_widget = tk.Text(
                text_frame,
                wrap=tk.WORD,
                height=8,
                bg=field_bg,
                fg=fg,
                relief=tk.FLAT,
                bd=0,
                padx=10,
                pady=8,
                font=("Segoe UI", 9),
                yscrollcommand=scroll.set,
            )
            scroll.config(command=text_widget.yview)
            text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            scroll.pack(side=tk.RIGHT, fill=tk.Y)
            text_widget.insert("1.0", campaign_ui_helpers._repair_polish_text(text))
            text_widget.config(state=tk.DISABLED)
            def _close_details() -> None:
                try:
                    details.destroy()
                finally:
                    try:
                        if dialog.winfo_exists():
                            dialog.grab_set()
                    except Exception:
                        pass

            try:
                details.protocol("WM_DELETE_WINDOW", _close_details)
            except Exception:
                pass
            footer = tk.Frame(details_body, bg=details_bg)
            footer.pack(fill=tk.X, padx=14, pady=(0, 14))
            tk.Button(
                footer,
                text="Zamknij",
                command=_close_details,
                cursor="hand2",
                bg=field_bg,
                fg=fg,
                relief=tk.FLAT,
                padx=10,
                pady=6,
            ).pack(side=tk.RIGHT)
            try:
                details.transient(dialog)
                details.grab_set()
            except Exception:
                pass

